L["Automatically duplicates the raid's tanks into the Extra Frames group. Shares the 5-frame cap with hotkey picks."] = "Duplique automatiquement les tanks du raid dans le groupe de cadres supplémentaires. Partage la limite de 5 cadres avec les sélections par raccourci."
