L["Automatically refreshes the Premade Groups list every few seconds while you are browsing, so newly posted groups appear without clicking Refresh."] = "Actualise automatiquement la liste des groupes prédéfinis toutes les quelques secondes pendant que vous naviguez, pour que les nouveaux groupes apparaissent sans cliquer sur Actualiser."
