L["Force boss debuffs into a single large column matched to the frame height (excluding cast bar), aligned to the chosen side of the frame. Overrides the Debuffs Location and Debuff Size settings while active. None disables it and uses the normal Debuffs Location."] = "Force les affaiblissements de boss en une seule grande colonne ajustée à la hauteur du cadre (barre d'incantation exclue), alignée sur le côté choisi du cadre. Remplace les réglages Emplacement des affaiblissements et Taille des affaiblissements tant qu'actif. Aucun le désactive et utilise l'Emplacement des affaiblissements normal."
