L["Force-hide Blizzard's Assisted Combat Highlight (rotation helper glow) on all CDM bars, even if enabled in Blizzard's Combat settings."] = "Force le masquage de la surbrillance de combat assisté de Blizzard (lueur d'aide à la rotation) sur toutes les barres CDM, même si elle est activée dans les réglages de Combat de Blizzard."
