L["Hide consumable items (potions, healthstone) from the bar when you have none in your bags, instead of showing them dimmed. They reappear automatically once you have the item again."] = "Masque les consommables (potions, pierre de soins) de la barre lorsque vous n'en avez aucun dans vos sacs, au lieu de les afficher atténués. Ils réapparaissent automatiquement dès que vous possédez à nouveau l'objet."
L["Hide crafted items from the gear tile list.\nCrafted items cannot be upgraded at the Upgrade NPC."] = "Masque les objets fabriqués de la liste des pièces d'équipement.\nLes objets fabriqués ne peuvent pas être améliorés chez le PNJ d'amélioration."
