L["Hide friendly player health bars and instead only see their names.\n\nRequires 'Simplified Friendly Nameplates' to be disabled in Blizzard's Nameplate settings (Esc > Options > Nameplates)."] = "Masque les barres de vie des joueurs alliés et n'affiche que leurs noms.\n\nNécessite de désactiver « Barres d'info alliées simplifiées » dans les réglages de barres d'info de Blizzard (Échap > Options > Barres d'information)."
