L["Hide targeted spells on preview"] = "Masquer les sorts ciblés dans l'aperçu"
L["Hide the Reset Data button from the damage meter header."] = "Masque le bouton Réinitialiser les données de l'en-tête du compteur de dégâts."
L["Hide the brief GCD swipe that flashes when you cast any spell. The actual ability cooldown swipe still shows."] = "Masque le bref balayage de GCD qui clignote lorsque vous lancez un sort. Le balayage de recharge réel de la capacité reste affiché."
L["Hide the enemy name text while that nameplate's cast bar is visible."] = "Masque le nom de l'ennemi tant que la barre d'incantation de cette barre d'info est visible."
L["Hide the icon texture, border, and duration swipe, leaving only the stack count. Forces icon opacity, border, and duration swipe off."] = "Masque la texture de l'icône, la bordure et le balayage de durée, ne laissant que le nombre de cumuls. Force la désactivation de l'opacité de l'icône, de la bordure et du balayage de durée."
L["Hide the randomize (dice) button in the OneBag view."] = "Masque le bouton de mélange (dé) dans la vue OneBag."
L["Hide the warning text at the top of the OneBag and MultiBag views."] = "Masque le texte d'avertissement en haut des vues OneBag et MultiBag."
