L["Hide without Target"]        = "Masquer sans cible"
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "Masque l'interface de tutoriel de Blizzard : les bulles d'aide jaunes et les boutons d'aide (i) lumineux sur le grimoire, les talents, la carte, les collections et d'autres panneaux."
L["Hides Pinned Items. Re-show in settings."] = "Masque les objets épinglés. Réaffichez-les dans les réglages."
L["Hides Recent Items. Re-show in settings."] = "Masque les objets récents. Réaffichez-les dans les réglages."
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "Masque la plupart des messages d'erreur rouges (comme « Pas assez de rage » ou « Cette capacité n'est pas encore prête »). Les erreurs importantes comme un sac plein ou un journal de quêtes plein restent affichées."
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "Masque la notification « Capture d'écran enregistrée » qui apparaît après une capture d'écran."
L["Hides the Add Category button at the bottom of the bag sidebar."] = "Masque le bouton Ajouter une catégorie en bas de la barre latérale des sacs."
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Masque le bouton EllesmereUI du menu Échap/pause du jeu."
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "Masque la fenêtre d'erreur Lua. Même réglage que Réglages généraux > Développeur."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Masque le bouton du mode Déverrouillage du menu Échap/pause du jeu. Vous pouvez toujours basculer le mode Déverrouillage depuis le panneau d'options EUI."
L["Hides the collapsed Blizzard party/raid sidebar panel on the side of the screen."] = "Masque le panneau latéral réduit de groupe/raid de Blizzard sur le côté de l'écran."
L["Hides the health bar Blizzard shows at the bottom of unit tooltips."] = "Masque la barre de vie que Blizzard affiche au bas des infobulles d'unité."
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "Masque la grande fenêtre de dialogue des PNJ qui apparaît pendant les quêtes et les donjons."
L["Hides the rank number (1. 2. 3.) before each player name."] = "Masque le numéro de rang (1. 2. 3.) devant chaque nom de joueur."
L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "Masque la poignée de redimensionnement de la fenêtre de chat principale, empêchant tout redimensionnement accidentel."
L["Hides the sync icons on the sidebar module list."] = "Masque les icônes de synchronisation dans la liste des modules de la barre latérale."
