L["Show a shield icon on the cast bar when an enemy's cast cannot be interrupted."] = "Afficher une icône de bouclier sur la barre d'incantation quand l'incantation d'un ennemi ne peut pas être interrompue."
L["Show a small glowing spark that moves along the leading edge of the fill."] = "Afficher une petite étincelle lumineuse qui se déplace le long du bord avant du remplissage."
L["Show black backgrounds behind minimap indicator buttons (tracking, calendar, mail, crafting, addon buttons, flyout toggle)."] = "Afficher des arrière-plans noirs derrière les boutons indicateurs de la minicarte (pistage, calendrier, courrier, artisanat, boutons d'addon, bascule du menu déroulant)."
L["Show button backgrounds even if a spell is not assigned to that slot."] = "Afficher les arrière-plans des boutons même si aucun sort n'est assigné à cet emplacement."
L["Show combat indicator preview"] = "Afficher l'aperçu de l'indicateur de combat"
L["Show debuffs on preview"]    = "Afficher les affaiblissements dans l'aperçu"
L["Show defensives on preview"] = "Afficher les défensifs dans l'aperçu"
L["Show dispel overlay preview"] = "Afficher l'aperçu de la superposition de dissipation"
L["Show dispels on preview"]    = "Afficher les dissipations dans l'aperçu"
L["Show duration and stack count text on buff and debuff icons."] = "Afficher le texte de durée et de nombre de cumuls sur les icônes d'amélioration et d'affaiblissement."
L["Show each enchant's name as text (colored to match that item's item level) instead of its icon. The name normally appears only when hovering the icon."] = "Afficher le nom de chaque enchantement sous forme de texte (coloré selon le niveau d'objet de la pièce) au lieu de son icône. Le nom n'apparaît normalement qu'au survol de l'icône."
L["Show equipped trinkets even if they don't have an on-use effect."] = "Afficher les bijoux équipés même s'ils n'ont pas d'effet d'utilisation."
L["Show gear tiles for items already at their maximum item level."] = "Afficher les tuiles d'équipement pour les objets déjà à leur niveau d'objet maximal."
L["Show heal absorb preview"]   = "Afficher l'aperçu de l'absorption de soins"
L["Show helpful tip text on Pinned Items and Recent Items category headers."] = "Afficher un texte d'astuce sur les en-têtes des catégories Objets épinglés et Objets récents."
L["Show how many crests you can still earn before hitting the season cap (cap minus earned so far)."] = "Afficher combien d'écus vous pouvez encore gagner avant d'atteindre le plafond de la saison (plafond moins ce qui est déjà gagné)."
L["Show in All Items"]          = "Afficher dans Tous les objets"
L["Show in Arena"]              = "Afficher en arène"
L["Show in Battlegrounds"]      = "Afficher en champ de bataille"
L["Show in Center of Screen"]   = "Afficher au centre de l'écran"
L["Show in Combat"]             = "Afficher en combat"
L["Show in Dungeons"]           = "Afficher dans les donjons"
L["Show in OneBag/MultiBag"]    = "Afficher dans OneBag/MultiBag"
L["Show in Open World"]         = "Afficher en monde ouvert"
L["Show in Party"]              = "Afficher en groupe"
L["Show in Raids"]              = "Afficher en raid"
L["Show indicators on preview"] = "Afficher les indicateurs dans l'aperçu"
L["Show on Target"]             = "Afficher sur la cible"
L["Show one decimal place on health text: health values like 240.5k and health percent like 77.3%. Power text is unaffected. Off by default."] = "Afficher une décimale sur le texte de vie : des valeurs de vie comme 240.5k et un pourcentage de vie comme 77.3 %. Le texte de ressource n'est pas affecté. Désactivé par défaut."
L["Show page up/down arrows next to Action Bar 1 for cycling through action bar pages 1-6."] = "Afficher les flèches page précédente/suivante à côté de la Barre d'action 1 pour parcourir les pages 1 à 6."
L["Show player nicknames from supported addons instead of character names on your main frames."] = "Afficher les surnoms de joueur des addons pris en charge au lieu des noms de personnage sur vos cadres principaux."
L["Show private auras on preview"] = "Afficher les auras privées dans l'aperçu"
L["Show quest objective progress on nameplates for open-world mobs."] = "Afficher la progression des objectifs de quête sur les barres d'info des créatures de monde ouvert."
L["Show rune count in center and remove recharge text/animation"] = "Afficher le nombre de runes au centre et retirer le texte/l'animation de recharge"
L["Show shield effects on preview"] = "Afficher les effets de bouclier dans l'aperçu"
L["Show special reminders while out in the open world."] = "Afficher les rappels spéciaux en monde ouvert."
L["Show successful interrupt lockouts in the crowd-control icon slot.\n\nDue to addon restrictions, the duration shown is a generic 4 seconds for all classes, so it is not 100% accurate."] = "Afficher les verrouillages d'interruption réussis dans l'emplacement d'icône de contrôle de foule.\n\nEn raison des restrictions imposées aux addons, la durée affichée est générique (4 secondes pour toutes les classes) et n'est donc pas fiable à 100 %."
L["Show targeted spells on preview"] = "Afficher les sorts ciblés dans l'aperçu"
L["Show the FocusKick bar on your current target's nameplate instead of your focus target's nameplate."] = "Afficher la barre FocusKick sur la barre d'info de votre cible actuelle au lieu de celle de votre cible de focalisation."
L["Show the Pinned Items category in the sidebar and content grid."] = "Afficher la catégorie Objets épinglés dans la barre latérale et la grille de contenu."
L["Show the Recent Items category in the sidebar and content grid for newly acquired items."] = "Afficher la catégorie Objets récents dans la barre latérale et la grille de contenu pour les objets nouvellement acquis."
L["Show the expansion landing page (Omnium Folio) button at the bottom-left of the minimap. Use the cog to nudge its position."] = "Afficher le bouton de la page d'accueil de l'extension (Omnium Folio) en bas à gauche de la minicarte. Utilisez l'engrenage pour ajuster sa position."
L["Show the expansion landing page (Omnium Folio) button on the minimap. Use the cog to choose its corner and nudge its position."] = "Afficher le bouton de la page d'accueil de l'extension (Omnium Folio) sur la minicarte. Utilisez l'engrenage pour choisir son coin et ajuster sa position."
L["Show the game's spell tooltip when you hover a spell in a breakdown window."] = "Afficher l'infobulle de sort du jeu au survol d'un sort dans une fenêtre de détail."
L["Show the leader/assistant icon while you are in combat. Disable to hide it during combat."] = "Afficher l'icône de chef/assistant pendant que vous êtes en combat. Désactivez pour la masquer en combat."
L["Show the main frames' hover highlight border on this frame. Turn off so this frame never recolors on mouseover. No effect when Highlight is off in the main frames' Hover Borders."] = "Afficher la bordure de surbrillance de survol des cadres principaux sur ce cadre. Désactivez pour que ce cadre ne se recolore jamais au survol. Sans effet quand Surbrillance est désactivé dans les Bordures au survol des cadres principaux."
L["Show the name of who the boss is casting on."] = "Afficher le nom de la cible sur laquelle le boss incante."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar."] = "Afficher la partie d'une absorption qui dépasse votre vie vide et se superpose sur votre vie actuelle. Désactivé, les absorptions ne remplissent que la partie vide de la barre de vie."
L["Show the part of an absorb that exceeds your empty health and backfills over your current health. When off, absorbs only fill the empty part of the health bar; on Default Blizz Frames the glow line stays pinned at the right edge."] = "Afficher la partie d'une absorption qui dépasse votre vie vide et se superpose sur votre vie actuelle. Désactivé, les absorptions ne remplissent que la partie vide de la barre de vie ; sur les cadres Blizz par défaut, la ligne lumineuse reste ancrée au bord droit."
L["Show the recharge countdown on charge spells while a charge is still banked. When off, the recharge timer only appears at 0 charges (Blizzard default)."] = "Afficher le décompte de recharge sur les sorts à charges tant qu'une charge est encore en réserve. Désactivé, le chrono de recharge n'apparaît qu'à 0 charge (par défaut Blizzard)."
L["Show the seasonal Earned / Cap column in the crest table."] = "Afficher la colonne saisonnière Gagné / Plafond dans le tableau des écus."
L["Show top 15 entries instead of 8."] = "Afficher les 15 premières entrées au lieu de 8."
L["Show/Hide Hitbox Overlay"]   = "Afficher/Masquer la superposition de zone de clic"
L["Show/Hide on Preview"]       = "Afficher/Masquer dans l'aperçu"
L["Shows Blizzard's default icon slot background texture behind empty action bar slots."] = "Affiche la texture d'arrière-plan d'emplacement d'icône par défaut de Blizzard derrière les emplacements vides des barres d'action."
L["Shows a bar that fills over the global cooldown."] = "Affiche une barre qui se remplit pendant le temps de recharge global."
L["Shows a colored overlay at the end of the cast bar representing your network latency for each spell. Helps you time spell queuing."] = "Affiche une superposition colorée à la fin de la barre d'incantation représentant votre latence réseau pour chaque sort. Aide à synchroniser la mise en file des sorts."
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "Affiche une grande alerte à l'écran (ex. « Joueur MORT ! ») chaque fois qu'un membre du groupe ou du raid meurt, pour que vous remarquiez immédiatement les morts en donjon et en raid. Utilisez le mode Déverrouillage pour repositionner l'alerte."
L["Shows a map icon of the friend's region if they are not playing within your region"] = "Affiche une icône de carte de la région de l'ami s'il ne joue pas dans votre région"
L["Shows a movable strip of recent spell icons. Shift-drag to reposition."] = "Affiche une bande déplaçable des icônes de sorts récents. Maj+glisser pour repositionner."
L["Shows a player's RP title on their unit tooltip."] = "Affiche le titre RP d'un joueur dans son infobulle d'unité."
L["Shows a popup with party and guild keystones when typing /keys."] = "Affiche une fenêtre avec les clés du groupe et de la guilde en tapant /keys."
L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "Affiche un petit repère blanc sur la barre d'incantation à l'endroit où en sera l'incantation quand votre interruption sortira de recharge."
L["Shows a special color for nameplates that another tank in your raid has aggro on."] = "Affiche une couleur spéciale pour les barres d'info sur lesquelles un autre tank de votre raid a l'aggro."
L["Shows a special color for non caster/mini-boss enemies when you do not have aggro on them."] = "Affiche une couleur spéciale pour les ennemis non incantateurs/mini-boss quand vous n'avez pas l'aggro sur eux."
L["Shows a special color for non caster/mini-boss enemies when you have aggro on them."] = "Affiche une couleur spéciale pour les ennemis non incantateurs/mini-boss quand vous avez l'aggro sur eux."
L["Shows a standalone window with spell cast history as bars. Matches your Damage Meters styling."] = "Affiche une fenêtre autonome avec l'historique des incantations sous forme de barres. Correspond au style de votre compteur de dégâts."
L["Shows elapsed / total duration (e.g. 0.4 / 2.0) instead of counting down from the total."] = "Affiche la durée écoulée / totale (ex. 0.4 / 2.0) au lieu d'un décompte depuis le total."
L["Shows full spell and ability descriptions in tooltips instead of just the name. Only enforced on login after you toggle this setting."] = "Affiche les descriptions complètes des sorts et capacités dans les infobulles au lieu du seul nom. Appliqué uniquement à la connexion après avoir modifié ce réglage."
L["Shows item level and secondary stats in the Character button's tooltip."] = "Affiche le niveau d'objet et les statistiques secondaires dans l'infobulle du bouton Personnage."
L["Shows only crowd-control auras"] = "Affiche uniquement les auras de contrôle de foule"
L["Shows only external defensive cooldowns cast on the unit"] = "Affiche uniquement les recharges défensives externes lancées sur l'unité"
L["Shows only major defensive cooldowns"] = "Affiche uniquement les recharges défensives majeures"
L["Shows only the Buffs/Debuffs that appear on Raid Frames"] = "Affiche uniquement les améliorations/affaiblissements qui apparaissent sur les cadres de raid"
L["Shows only the Buffs/Debuffs you apply"] = "Affiche uniquement les améliorations/affaiblissements que vous appliquez"
L["Shows only the Debuffs that appear on Raid Frames"] = "Affiche uniquement les affaiblissements qui apparaissent sur les cadres de raid"
L["Shows only the Debuffs you apply"] = "Affiche uniquement les affaiblissements que vous appliquez"
L["Shows only the spells Blizzard flags as Important"] = "Affiche uniquement les sorts que Blizzard marque comme importants"
L["Shows saved instance lockouts with boss kill progress on the minimap calendar button tooltip."] = "Affiche les verrouillages d'instance enregistrés avec la progression des boss tués dans l'infobulle du bouton calendrier de la minicarte."
L["Shows the 'Disable Feature' text below the teleport button. When off, the text is hidden and the window is 20px shorter."] = "Affiche le texte « Désactiver la fonction » sous le bouton de téléportation. Désactivé, le texte est masqué et la fenêtre est plus courte de 20px."
L["Shows the consumable rank (quality) diamond icon on action buttons."] = "Affiche l'icône losange de rang (qualité) des consommables sur les boutons d'action."
L["Shows the raid target marker icon on boss frames."] = "Affiche l'icône de marqueur de cible de raid sur les cadres de boss."
L["Shows tick marks on channeled spells. Only supported spells are shown, request missing spells on Discord."] = "Affiche des repères sur les sorts canalisés. Seuls les sorts pris en charge sont affichés, demandez les sorts manquants sur Discord."
L["Shows where your interrupt will be ready during an enemy cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Affiche où votre interruption sera prête pendant une incantation ennemie. « Tick » marque l'endroit exact sur la barre d'incantation ; « Tick + Barre » colore aussi la fenêtre pendant laquelle votre interruption sera disponible."
