L["Thank you for helping test EllesmereUI during beta! During testing, many systemic changes were made to build the foundation for a stable, flexible addon going forward.\n\nTo ensure a clean experience for everyone, all settings have been automatically reset. You will need to reconfigure your UI. We apologize for the inconvenience, and appreciate your patience.\n\nPrevious profile exports are no longer compatible and will need to be re-created."] = "Merci d'avoir participé aux tests d'EllesmereUI pendant la bêta ! Durant les tests, de nombreux changements systémiques ont été apportés pour bâtir les fondations d'un addon stable et flexible pour l'avenir.\n\nPour garantir une expérience propre à tout le monde, tous les réglages ont été automatiquement réinitialisés. Vous devrez reconfigurer votre interface. Nous nous excusons pour la gêne occasionnée et vous remercions de votre patience.\n\nLes exports de profil précédents ne sont plus compatibles et devront être recréés."
