L["The amount of damage you can take"] = "La quantité de dégâts que vous pouvez encaisser"
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "La couleur d'arrière-plan derrière les barres en mode sombre (cadres d'unité, cadres de raid, barres de ressource)."
L["The class resource bar gains a spec picker to choose which specs show it, matching the power and health bars."] = "La barre de ressource de classe gagne un sélecteur de spé pour choisir quelles spés l'affichent, comme les barres de ressource et de vie."
L["The damage dealer cut of Midnight Lily. A focused, low-clutter layout that keeps your rotation and cooldowns front and center."] = "La version DPS de Midnight Lily. Une disposition épurée et centrée qui garde votre rotation et vos recharges au premier plan."
L["The default EllesmereUI look"] = "L'apparence par défaut d'EllesmereUI"
L["The dispel type icon gains an Icon Size slider in its cog menu so you can make it larger or smaller."] = "L'icône de type de dissipation gagne un curseur Taille d'icône dans son menu engrenage pour l'agrandir ou la réduire."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "La langue d'affichage du panneau d'options d'EllesmereUI. Auto suit votre client de jeu. Le texte non traduit revient à l'anglais."
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "La couleur de remplissage unie utilisée par les barres quand le mode sombre est activé (cadres d'unité, cadres de raid, barres de ressource)."
L["The highlight overlay that appears on a spell button while it is the active/current action. Disable to hide it."] = "La superposition de surbrillance qui apparaît sur un bouton de sort tant qu'il est l'action active/actuelle. Désactivez pour la masquer."
L["The interrupt flash now clears the instant a target dies, so the cast bar no longer looks squished by the death animation."] = "Le clignotement d'interruption disparaît désormais dès qu'une cible meurt, pour que la barre d'incantation ne paraisse plus écrasée par l'animation de mort."
L["The overlay that appears on the icon when you hover your mouse over a spell button"] = "La superposition qui apparaît sur l'icône quand vous survolez un bouton de sort avec la souris"
L["The overlay that appears on the icon when you press and hold a spell button"] = "La superposition qui apparaît sur l'icône quand vous maintenez un bouton de sort enfoncé"
L["The signature EllesmereUI layout exactly as designed. Vibrant class colors, clear cd tracking, and every module working in harmony."] = "La disposition signature d'EllesmereUI exactement telle que conçue. Des couleurs de classe éclatantes, un suivi clair des recharges, et chaque module en parfaite harmonie."
L["The size of your mana pool"] = "La taille de votre réserve de mana"
L["The spell picker now ends with a Missing Spells? shortcut that opens Blizzard's Cooldown Manager so you can add spells that are not listed."] = "Le sélecteur de sorts se termine désormais par un raccourci « Sorts manquants ? » qui ouvre le gestionnaire de recharge de Blizzard pour ajouter les sorts non listés."
L["Themed Blizzard frames: Character Sheet, tooltips, menus, popups, Dragon Riding HUD."] = "Cadres Blizzard thématisés : feuille de personnage, infobulles, menus, fenêtres, ATH de Chevauchée draconique."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Ces réglages privilégient la fluidité et la clarté visuelle par rapport au détail de l'environnement. Les textures restent de haute qualité pour que votre personnage et le monde restent parfaits."
L["Thick"]                      = "Épais"
L["Thickness"]                  = "Épaisseur"
L["Thickness of any Pixel Glow assigned to this bar's buttons. Assign glows by right-clicking an icon in the preview."] = "Épaisseur de toute lueur pixel assignée aux boutons de cette barre. Assignez les lueurs par un clic droit sur une icône de l'aperçu."
L["Thin"]                       = "Fin"
L["Thin Line Bottom"]           = "Ligne fine en bas"
L["Thin Line Top"]              = "Ligne fine en haut"
L["This Action Bar is also used as the Moonkin Form bar.\nChanging spells on a Druid for this bar will also change them on your Moonkin Form bar."] = "Cette barre d'action sert aussi de barre de Forme de sélénien.\nModifier les sorts d'un Druide sur cette barre les modifiera aussi sur votre barre de Forme de sélénien."
L["This bar will always be attached to your focus target's nameplate"] = "Cette barre sera toujours attachée à la barre d'info de votre cible de focalisation"
L["This bar will only show if you have an enemy targeted"] = "Cette barre ne s'affichera que si vous ciblez un ennemi"
L["This change requires a UI reload to take effect."] = "Ce changement nécessite un rechargement de l'interface pour prendre effet."
L["This element doesn't support both Height and Width matching"] = "Cet élément ne prend pas en charge l'alignement simultané de hauteur et de largeur"
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\nShadow Quality - Fair (balanced quality/FPS)\nLiquid Detail - Disabled\nParticle Density - Set to Ultra (keeps important spell effects)\nSSAO (Ambient Occlusion) - Disabled\nDepth Effects - Disabled\nCompute Effects - Disabled\nOutline Mode - Disabled\nTexture Resolution - Set to High\nSpell Density - Set to Essential\nProjected Textures - Enabled (needed for ground effects)\nView Distance - Reduced to 1\nEnvironment Detail - Reduced to 1\nGround Clutter - Reduced to 1\nRaid/Dungeon Settings - Uses same settings everywhere\nResample Sharpening - Enabled (crisper image)\nContrast - Boosted by +10 (if currently 55 or below)\nEnable Reverb - Disabled (spell and interrupt audio cues stay crisp)\n\nThese settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Cette fonction optimise vos réglages graphiques en jeu pour vous offrir la meilleure combinaison de FPS élevés et de clarté visuelle.\n\nVous pouvez annuler tous les changements à tout moment en cliquant sur « Restaurer mes réglages », qui apparaîtra après l'optimisation.\n\n\nCe que nous modifions :\n\nQualité des ombres - Correcte (équilibre qualité/FPS)\nDétail des liquides - Désactivé\nDensité des particules - Réglée sur Ultra (conserve les effets de sort importants)\nSSAO (occlusion ambiante) - Désactivé\nEffets de profondeur - Désactivés\nCalcul des effets - Désactivé\nMode de contour - Désactivé\nRésolution des textures - Réglée sur Élevée\nDensité des sorts - Réglée sur Essentiel\nTextures projetées - Activées (nécessaires pour les effets au sol)\nDistance de vue - Réduite à 1\nDétail de l'environnement - Réduit à 1\nEncombrement du sol - Réduit à 1\nRéglages Raid/Donjon - Utilise les mêmes réglages partout\nNetteté au rééchantillonnage - Activée (image plus nette)\nContraste - Augmenté de +10 (si actuellement à 55 ou moins)\nActiver la réverbération - Désactivé (les sons des sorts et des interruptions restent nets)\n\nCes réglages privilégient la fluidité et la clarté visuelle par rapport au détail de l'environnement. Les textures restent de haute qualité pour que votre personnage et le monde restent parfaits."
L["This feature requires Snap Elements to be enabled"] = "Cette fonction nécessite que l'aimantation des éléments soit activée"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Ceci est la fenêtre de file d'attente des sorts ; elle aide à éviter de mettre en file trop de sorts à la fois, ce qui donne une impression de latence. Les réglages recommandés sont généralement d'au moins 200 + votre ping local. Si vous n'êtes pas sûr de ce que fait ce réglage, laissez-le à 400."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally ~150 for melee and ~300 for casters. Higher if you have high local ping."] = "Ceci est la fenêtre de file d'attente des sorts ; elle aide à éviter de mettre en file trop de sorts à la fois, ce qui donne une impression de latence. Les réglages recommandés sont généralement d'environ 150 pour la mêlée et 300 pour les incantateurs. Plus élevé si vous avez un ping local élevé."
L["This is the full overlay that swipes from right to left on the icon during its cast duration"] = "C'est la superposition complète qui balaie de droite à gauche sur l'icône pendant sa durée d'incantation"
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "C'est ici que vous contrôlez les réglages du mode Déverrouillage.\n\nLes éléments peuvent être repositionnés par glisser ou avec les touches fléchées (+Maj)\nAncrez, alignez la hauteur ou la largeur de n'importe quel élément.\nL'aimantation se base sur l'élément le plus proche, mais vous pouvez aimanter à\n un élément spécifique via le clic droit ou l'icône de réglages."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Fait en sorte que la largeur de la barre d'incantation inclue l'icône, au lieu de la placer à gauche de la largeur des barres d'incantation."
L["This option Show Duration (Inside Cog) Enabled"] = "L'option Afficher la durée (dans l'engrenage) activée"
L["This option allows you to set custom frame sizing and positioning to different raid sizes. Note: This does NOT resize/reposition frames while in combat, if players join/leave mid combat it will resize after combat completes."] = "Cette option vous permet de définir une taille et un positionnement de cadres personnalisés pour différentes tailles de raid. Note : ceci ne redimensionne/repositionne PAS les cadres en combat ; si des joueurs rejoignent/quittent en plein combat, le redimensionnement se fera à la fin du combat."
L["This option can't be used while Expand Power Bar if No Resource is enabled."] = "Cette option ne peut pas être utilisée tant que « Étendre la barre de ressource si pas de ressource » est activé."
L["This option can't be used while Shift Elements if No Resource is enabled."] = "Cette option ne peut pas être utilisée tant que « Décaler les éléments si pas de ressource de classe » est activé."
L["This option does not work with Blizzard Bars. Please use Blizzard Edit Mode."] = "Cette option ne fonctionne pas avec les barres Blizzard. Veuillez utiliser le mode Édition de Blizzard."
L["This option is currently under maintenance"] = "Cette option est actuellement en maintenance"
L["This option is disabled while a Center Text is selected."] = "Cette option est désactivée tant qu'un texte central est sélectionné."
L["This option is not available for custom shaped icons"] = "Cette option n'est pas disponible pour les icônes de forme personnalisée"
L["This option is not supported for this bar type"] = "Cette option n'est pas prise en charge pour ce type de barre"
L["This option is now controlled by the Raid Frames addon"] = "Cette option est désormais contrôlée par l'addon Cadres de raid"
L["This option is only available for formats that display a percentage."] = "Cette option n'est disponible que pour les formats qui affichent un pourcentage."
L["This option is only available for the Custom Color Theme"] = "Cette option n'est disponible que pour le thème de couleur personnalisé"
L["This option is only available when Portrait Mode is Detached."] = "Cette option n'est disponible que lorsque le mode portrait est détaché."
L["This option is only used by the Basic border."] = "Cette option n'est utilisée que par la bordure Basique."
L["This option only affects Raid Buffs and Paladin Beacons"] = "Cette option n'affecte que les améliorations de raid et les Guides de Paladin"
L["This option requires %s to be enabled"] = "Cette option nécessite que %s soit activé"
L["This option requires Add Friendly Boss Group to be set to Healers or Always."] = "Cette option nécessite que « Ajouter un groupe de boss alliés » soit réglé sur Soigneurs ou Toujours."
L["This option requires Blizzard Style Action Bars to be disabled"] = "Cette option nécessite que « Barres d'action style Blizzard » soit désactivé"
L["This option requires Class Colors to be disabled"] = "Cette option nécessite que « Couleurs de classe » soit désactivé"
L["This option requires Class Resource to be set to Modern."] = "Cette option nécessite que « Ressource de classe » soit réglé sur Moderne."
L["This option requires Fill Color to be set to Custom"] = "Cette option nécessite que « Couleur de remplissage » soit réglé sur Personnalisé"
L["This option requires Icon Shape to be set to None or Cropped"] = "Cette option nécessite que « Forme d'icône » soit réglé sur Aucune ou Rognée"
L["This option requires Pixel Glow to be the selected glow type"] = "Cette option nécessite que « Lueur pixel » soit le type de lueur sélectionné"
L["This option requires Portrait Mode to be set to Detached."] = "Cette option nécessite que « Mode portrait » soit réglé sur Détaché."
L["This option requires Set UI Scale to 0.5333 to be disabled"] = "Cette option nécessite que « Régler l'échelle de l'interface sur 0.5333 » soit désactivé"
L["This option requires Show Tanks in Extra Group or a bound hotkey."] = "Cette option nécessite « Afficher les tanks dans le groupe supplémentaire » ou un raccourci assigné."
L["This option requires Threshold Settings to be disabled"] = "Cette option nécessite que « Réglages du seuil » soit désactivé"
L["This option requires a Border Size above 0."] = "Cette option nécessite une taille de bordure supérieure à 0."
L["This option requires a Class Icon other than None."] = "Cette option nécessite une icône de classe autre qu'Aucune."
L["This option requires a Duration Text position other than None"] = "Cette option nécessite une position de texte de durée autre qu'Aucune"
L["This option requires a Glow Type other than None"] = "Cette option nécessite un type de lueur autre qu'Aucun"
L["This option requires a Health Text format other than None"] = "Cette option nécessite un format de texte de vie autre qu'Aucun"
L["This option requires a Name Text position other than None"] = "Cette option nécessite une position de texte du nom autre qu'Aucune"
L["This option requires a Power Text format other than None"] = "Cette option nécessite un format de texte de ressource autre qu'Aucun"
L["This option requires a Stacks Text position other than None"] = "Cette option nécessite une position de texte des cumuls autre qu'Aucune"
L["This option requires a custom glow to be selected"] = "Cette option nécessite qu'une lueur personnalisée soit sélectionnée"
L["This option requires a detached position to be active."] = "Cette option nécessite qu'une position détachée soit active."
L["This option requires a dropdown selection other than Above Health Bar"] = "Cette option nécessite une sélection autre que « Au-dessus de la barre de vie »"
L["This option requires a gradient to be set"] = "Cette option nécessite qu'un dégradé soit défini"
L["This option requires a non-custom button shape"] = "Cette option nécessite une forme de bouton non personnalisée"
L["This option requires a non-custom shape to be selected"] = "Cette option nécessite qu'une forme non personnalisée soit sélectionnée"
L["This option requires a non-custom shaped action bar"] = "Cette option nécessite une barre d'action de forme non personnalisée"
L["This option requires a perpendicular Group Growth"] = "Cette option nécessite une croissance de groupe perpendiculaire"
L["This option requires a text position other than none."] = "Cette option nécessite une position de texte autre qu'aucune."
L["This option requires a text selection other than none."] = "Cette option nécessite une sélection de texte autre qu'aucune."
L["This option requires a text to be assigned"] = "Cette option nécessite qu'un texte soit assigné"
L["This option requires an aura or indicator to be assigned"] = "Cette option nécessite qu'une aura ou un indicateur soit assigné"
L["This option requires exactly 2 rows"] = "Cette option nécessite exactement 2 rangées"
L["This option requires the Border Style to be set to Solid"] = "Cette option nécessite que « Style de bordure » soit réglé sur Uni"
L["This option requires the position setting to be detached"] = "Cette option nécessite que le réglage de position soit détaché"
L["This preset"]                = "Ce préréglage"
L["This resets every EUI addon, not just the current one."] = "Ceci réinitialise tous les addons EUI, pas seulement l'actuel."
L["This setting requires a UI reload to take effect."] = "Ce réglage nécessite un rechargement de l'interface pour prendre effet."
L["This spell"]                 = "Ce sort"
L["This spell is already being used on %s"] = "Ce sort est déjà utilisé sur %s"
L["This will change the color of your bar if you have more than your chosen number of stacks"] = "Ceci changera la couleur de votre barre si vous avez plus que le nombre de cumuls choisi"
L["This will disable EllesmereUI Tracking Bars and show Blizzard's default Tracked Bars display instead."] = "Ceci désactivera les barres de suivi EllesmereUI et affichera l'affichage des barres suivies par défaut de Blizzard à la place."
L["This will discard your custom party settings for this section and use raid settings instead."] = "Ceci abandonnera vos réglages de groupe personnalisés pour cette section et utilisera les réglages de raid à la place."
L["This will display ALL of your debuffs on enemy nameplates, rather than only the important ones."] = "Ceci affichera TOUS vos affaiblissements sur les barres d'info ennemies, au lieu des seuls importants."
L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "Ceci affichera le mot « FOCUS » sous les incantateurs/mini-boss en M+ si vous n'avez pas défini de focalisation. Désactivé pour les spés sans interruption."
L["This will not override sorting by role"] = "Ceci ne remplacera pas le tri par rôle"
L["This will not reset addon-specific Quick Setup."] = "Ceci ne réinitialisera pas la configuration rapide propre à l'addon."
L["This will overwrite %1$s settings on the selected profiles with your current settings. Continue?"] = "Ceci écrasera les réglages %1$s des profils sélectionnés par vos réglages actuels. Continuer ?"
L["This will physically scatter items to random positions in your bags. The changes persist even if you disable EllesmereUI Bags."] = "Ceci dispersera physiquement les objets à des positions aléatoires dans vos sacs. Les changements persistent même si vous désactivez EllesmereUI Bags."
L["This will pin your bar to the window when it is not within the visible area"] = "Ceci épinglera votre barre à la fenêtre lorsqu'elle n'est pas dans la zone visible"
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Custom bars are not affected. Continue?"] = "Ceci réinitialisera toutes les assignations de sorts des barres par défaut pour la spé actuelle afin de correspondre à la disposition du CDM de Blizzard. Les barres personnalisées ne sont pas affectées. Continuer ?"
L["This will reset all saved panel positions and reload your UI."] = "Ceci réinitialisera toutes les positions de panneau enregistrées et rechargera votre interface."
