L["When disabled, EUI relinquishes full control of friendly player nameplates to Blizzard. Use Blizzard's own Nameplate settings (Esc > Options > Nameplates) to control them."] = "Désactivé, EUI cède à Blizzard le contrôle total des barres d'info des joueurs alliés. Utilisez les réglages de barres d'info de Blizzard (Échap > Options > Barres d'information) pour les contrôler."
L["When enabled, BM and MM specs show Focus as the standard power bar instead of a class resource bar."] = "Activé, les spés BM et MM affichent la Focalisation comme barre de ressource standard au lieu d'une barre de ressource de classe."
L["When enabled, EUI relinquishes full control of friendly player nameplates to Blizzard."] = "Activé, EUI cède à Blizzard le contrôle total des barres d'info des joueurs alliés."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position."] = "Activé, Maj+clic sur n'importe quel bouton de la minicarte (courrier, calendrier, pistage, boutons d'addon) pour le glisser à une position personnalisée."
L["When enabled, Shift+Click any sidebar icon to drag it to a custom position."] = "Activé, Maj+clic sur n'importe quelle icône de la barre latérale pour la glisser à une position personnalisée."
L["When enabled, debuff icons keep Blizzard's colored border instead of using the custom border."] = "Activé, les icônes d'affaiblissement conservent la bordure colorée de Blizzard au lieu d'utiliser la bordure personnalisée."
L["When enabled, left-click dragging a window will save its position without needing to hold Shift. Ctrl+drag still does a temporary move."] = "Activé, glisser une fenêtre au clic gauche enregistre sa position sans avoir à maintenir Maj. Ctrl+glisser effectue toujours un déplacement temporaire."
L["When enabled, left-click dragging the bag window will move it without needing to hold Shift."] = "Activé, glisser la fenêtre des sacs au clic gauche la déplace sans avoir à maintenir Maj."
L["When enabled, nameplates stack vertically instead of overlapping."] = "Activé, les barres d'info s'empilent verticalement au lieu de se chevaucher."
L["When enabled, the extra buttons (Great Vault, M+ Portals, Friends Online, Group Button) and any ungrouped minimap buttons only show while the mouse is over the minimap. The M+ Portals flyout keeps them shown until it closes."] = "Activé, les boutons supplémentaires (Grande Chambre forte, Portails M+, Amis en ligne, Bouton de groupe) et les boutons de minicarte non groupés ne s'affichent que lorsque la souris est sur la minicarte. Le menu déroulant des Portails M+ les garde affichés jusqu'à sa fermeture."
L["When hovering any action bar set to Mouseover, all Mouseover bars will appear."] = "Au survol de n'importe quelle barre d'action réglée sur Survol, toutes les barres en Survol apparaissent."
L["When the class resource bar is not shown, this automatically adds the class resource height to the power bar."] = "Quand la barre de ressource de classe n'est pas affichée, ceci ajoute automatiquement la hauteur de la ressource de classe à la barre de ressource."
L["When using custom raid sizes, don't count members in hidden groups toward the raid-size breakpoint. For example, if you hide groups 7 and 8, a full 40-man raid is sized as if it were 24-man instead of jumping to the 30-man frame size. Has no effect unless you have custom raid sizes set up."] = "Avec des tailles de raid personnalisées, ne pas compter les membres des groupes masqués dans le seuil de taille de raid. Par exemple, si vous masquez les groupes 7 et 8, un raid complet à 40 joueurs est dimensionné comme s'il était à 24 joueurs au lieu de passer à la taille de cadre à 30 joueurs. Sans effet sauf si vous avez configuré des tailles de raid personnalisées."
L["When you are solo, center the player frame on the party frame instead of anchoring it at the top."] = "En solo, centrer le cadre du joueur sur le cadre de groupe au lieu de l'ancrer en haut."
L["When you join a Group Finder group for a dungeon that has a teleport, shows a small movable popup with the dungeon name and a one-click teleport button. It hides when you enter the dungeon, leave the group, or enter combat."] = "Quand vous rejoignez un groupe de l'outil de recherche de groupe pour un donjon disposant d'une téléportation, affiche une petite fenêtre déplaçable avec le nom du donjon et un bouton de téléportation en un clic. Elle se masque quand vous entrez dans le donjon, quittez le groupe ou entrez en combat."
L["When you press Escape or Space during a cinematic, the confirmation prompt is automatically accepted."] = "Quand vous appuyez sur Échap ou Espace pendant une cinématique, la confirmation est automatiquement acceptée."
L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "Quand votre interruption est en recharge maintenant mais sera prête avant la fin de l'incantation ennemie, colore la partie de la barre d'incantation pendant laquelle votre interruption sera disponible. La couleur disparaît dès que votre interruption sort de recharge."
L["When your spec has no class resource, automatically adds the class resource height to the power bar. Automatically disabled when Power Bar height is matched to another element."] = "Quand votre spé n'a pas de ressource de classe, ajoute automatiquement la hauteur de la ressource de classe à la barre de ressource. Automatiquement désactivé quand la hauteur de la barre de ressource est alignée sur un autre élément."
L["Which view bags (and the bank) open to by default. The bank has no MultiBag view, so MultiBag opens the bank to OneBank."] = "Quelle vue les sacs (et la banque) ouvrent par défaut. La banque n'a pas de vue MultiBag, donc MultiBag ouvre la banque en OneBank."
