L["Show a 1-decimal countdown (2.7) below Threshold Seconds."]  = "Affiche un compte à rebours à 1 décimale (2,7) sous Secondes de seuil."
L["Show a 1-decimal countdown on presets and custom spell/item IDs when under the cog's Seconds Left threshold -- their active state on cooldown/utility bars, their buff duration on buff bars (both are hardcoded, so the remaining time is exact)."] = "Affiche un compte à rebours à 1 décimale sur les préréglages et les IDs de sort/objet personnalisés sous le seuil Secondes restantes de la roue -- leur état actif sur les barres Temps de recharge/Utilitaire, leur durée d'amélioration sur les barres d'amélioration (les deux sont codés en dur, donc le temps restant est exact)."
L["Show a panel of equipped-gear sockets on the character sheet; click a socket to gem it."] = "Affiche un panneau des châsses de l'équipement porté sur la feuille de personnage ; cliquez sur une châsse pour la sertir."
L["Show a pulsing dot on the Patch Notes button whenever EllesmereUI updates to a new version."] = "Affiche une pastille clignotante sur le bouton Notes de version à chaque mise à jour d'EllesmereUI."
L["Show a reminder when your active pet is set to Passive stance. Only applies to pet classes (Hunter, Warlock, Death Knight, Mage)."] = "Affiche un rappel quand votre familier actif est en posture Passive. Ne s'applique qu'aux classes à familier (Chasseur, Démoniste, Chevalier de la mort, Mage)."
L["Show on Boss Frames"]                                        = "Afficher sur les cadres de boss"
L["Show on Clock Hover"]                                        = "Afficher au survol de l'horloge"
L["Show on FPS/MS Hover"]                                       = "Afficher au survol de FPS/MS"
L["Show one-time video guide badges next to new or complex features. Each badge disappears forever once clicked."] = "Affiche des badges de guide vidéo uniques à côté des fonctionnalités nouvelles ou complexes. Chaque badge disparaît définitivement une fois cliqué."
L["Show only while in a dungeon, raid, arena or battleground. Combine with Combat to show only during instanced combat."] = "N'afficher qu'en donjon, raid, arène ou champ de bataille. Combinez avec Combat pour n'afficher que pendant un combat en instance."
L["Show only while in combat. Combine with Instances to show only during instanced combat."] = "N'afficher qu'en combat. Combinez avec Instances pour n'afficher que pendant un combat en instance."
L["Show the border style and size controls for the timer bars."] = "Affiche les contrôles de style et de taille de bordure pour les barres de minuteur."
L["Show the resource text only while the power bar is hidden - disabled, filtered off for this spec, a spec with no power, or hidden by \"Hide Power Bar if Resource\". Off = always show the text."] = "N'affiche le texte de ressource que lorsque la barre de puissance est masquée - désactivée, filtrée pour cette spé, une spé sans puissance, ou masquée par « Masquer la barre de puissance si ressource ». Désactivé = toujours afficher le texte."
L["Show world latency instead of home latency."]               = "Afficher la latence mondiale au lieu de la latence locale."
L["Shows a clickable list of online friends and guildmates in the Social and Guild button tooltips."] = "Affiche une liste cliquable des amis et membres de guilde en ligne dans les infobulles des boutons Social et Guilde."
L["Shows a faint white wash over each block on mouseover."]     = "Affiche un léger voile blanc sur chaque bloc au survol."
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "Affiche un grand texte à l'écran quand vous entrez et/ou sortez de combat (ex. « +Combat » / « -Combat »). Utilisez la roue pour définir le texte affiché, la taille, les couleurs et les transitions affichées ; utilisez le mode déverrouillage pour repositionner l'alerte."
L["Shows a rest icon while your character is resting."]         = "Affiche une icône de repos pendant que votre personnage se repose."
L["Shows an envelope icon when you have unread mail."]          = "Affiche une icône d'enveloppe quand vous avez du courrier non lu."
L["Shows only auras flagged for raid frames during combat"]     = "N'affiche que les auras marquées pour les cadres de raid pendant le combat"
L["Shows only auras with a dispel type you can dispel"]         = "N'affiche que les auras d'un type de dissipation que vous pouvez dissiper"
L["Shows only buffs that can be canceled"]                      = "N'affiche que les améliorations pouvant être annulées"
L["Shows only buffs you can spellsteal or purge"]              = "N'affiche que les améliorations que vous pouvez voler ou purger"
L["Shows only debuffs applied by bosses"]                       = "N'affiche que les affaiblissements appliqués par les boss"
L["Shows only debuffs flagged for your role"]                   = "N'affiche que les affaiblissements marqués pour votre rôle"
L["Shows only priority debuffs"]                                = "N'affiche que les affaiblissements prioritaires"
L["Shows only the Buffs that appear on Raid Frames"]            = "N'affiche que les améliorations qui apparaissent sur les cadres de raid"
L["Shows only the Buffs you apply"]                             = "N'affiche que les améliorations que vous appliquez"
L["Shows only the buffs you apply"]                             = "N'affiche que les améliorations que vous appliquez"
L["Shows silver and copper, not just gold."]                    = "Affiche l'argent et le cuivre, pas seulement l'or."
L["Shows the active talent loadout name."]                      = "Affiche le nom de la configuration de talents active."
L["Shows the coin icon next to the amount."]                    = "Affiche l'icône de pièce à côté du montant."
L["Shows the currency icon next to the amount."]                = "Affiche l'icône de monnaie à côté du montant."
L["Shows the icon next to the durability readout."]             = "Affiche l'icône à côté de l'indicateur de durabilité."
L["Shows the item level on each item in the character sheet gear flyout (the popup of same-slot bag items that appears when hovering an equipped slot), coloured by quality."] = "Affiche le niveau d'objet sur chaque objet du menu déroulant d'équipement de la feuille de personnage (la fenêtre des objets de sac du même emplacement qui apparaît au survol d'un emplacement équipé), coloré par qualité."
L["Shows the item level on weapons and armor a vendor sells."]  = "Affiche le niveau d'objet sur les armes et armures vendues par un marchand."
L["Shows the online friend and guild counters."]                = "Affiche les compteurs d'amis et de membres de guilde en ligne."
L["Shows the target marker directly before the enemy name text. Uses its own size and does not use the Core Positions raid marker slot."] = "Affiche le marqueur de cible juste avant le texte du nom de l'ennemi. Utilise sa propre taille et n'utilise pas l'emplacement de marqueur de raid des Positions principales."
L["Shows your free bag slots."]                                 = "Affiche vos emplacements de sac libres."
L["Single threshold is off while Multi-band is on.\n"]          = "Le seuil unique est désactivé quand Multi-bandes est activé.\n"
