L["That setting is stored by list position and can't be safely overridden."] = "Ce réglage est enregistré par position dans la liste et ne peut pas être remplacé en toute sécurité."
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "Le gestionnaire de temps de recharge fait bien plus qu'afficher les recharges, il a aussi des réglages par sort, des lueurs de barre, des barres de suivi et plus encore ! Découvrez des astuces pour en tirer davantage."
L["The Guild & Communities window: roster, chat, and the community list."] = "La fenêtre Guilde et communautés : liste des membres, discussion, et la liste des communautés."
L["The NPC dialog window: greeting text, gossip and quest options, and goodbye button."] = "La fenêtre de dialogue des PNJ : texte d'accueil, options de bavardage et de quête, et bouton d'au revoir."
L["The NPC quest window: quest detail, progress, and reward panels plus the multi-quest greeting list."] = "La fenêtre de quête des PNJ : détail de la quête, progression et panneaux de récompense, plus la liste d'accueil multi-quêtes."
L["The Player Spells window: talents, spec selection, and the spellbook."] = "La fenêtre des sorts du joueur : talents, sélection de spécialisation, et le grimoire."
L["The achievement window: categories, rows, progress bars, and search."] = "La fenêtre des hauts faits : catégories, lignes, barres de progression, et recherche."
L["The active override's Buff Manager is bound to the open page. Leave the Buff Manager tab to switch overrides."] = "Le gestionnaire d'améliorations du remplacement actif est lié à la page ouverte. Quittez l'onglet Gestionnaire d'améliorations pour changer de remplacement."
L["The active override's custom Buff Manager is bound to this page. Leave the Buff Manager tab to switch to another override."] = "Le gestionnaire d'améliorations personnalisé du remplacement actif est lié à cette page. Quittez l'onglet Gestionnaire d'améliorations pour passer à un autre remplacement."
L["The addon manager: list rows, checkboxes, and buttons."]     = "Le gestionnaire d'addons : lignes de liste, cases à cocher, et boutons."
L["The auction house: browse, sell, and my auctions views."]    = "L'hôtel des ventes : vues parcourir, vendre, et mes enchères."
L["The class and profession trainer window: skill list, train button, and cost display."] = "La fenêtre de maître de classe et de métier : liste de compétences, bouton d'apprentissage, et affichage du coût."
L["The customer crafting orders window: browse, order form, and my orders."] = "La fenêtre des commandes d'artisanat client : parcourir, formulaire de commande, et mes commandes."
L["The gem socketing window with squared gem slots."]           = "La fenêtre de sertissage de gemmes avec des emplacements de gemme carrés."
L["The housing dashboard window background, border, and title bar."] = "L'arrière-plan, la bordure et la barre de titre de la fenêtre du tableau de bord du logement."
L["The item conversion window (catalyst and similar kiosks)."]  = "La fenêtre de conversion d'objet (catalyseur et kiosques similaires)."
L["The item preview / transmog dressing room window."]          = "La fenêtre d'aperçu d'objet / cabine d'essayage de transmogrification."
L["The macro editor: tabs, icon grid, text well, and buttons."] = "L'éditeur de macros : onglets, grille d'icônes, zone de texte, et boutons."
L["The mailbox: inbox rows, send mail, open mail, and attachment slots."] = "La boîte aux lettres : lignes de réception, envoi de courrier, ouverture de courrier, et emplacements de pièces jointes."
L["The monthly calendar grid, event dialogs, and navigation arrows."] = "La grille du calendrier mensuel, les fenêtres d'événement, et les flèches de navigation."
L["The pasted string could not be read completely. Please paste it again."] = "La chaîne collée n'a pas pu être lue complètement. Veuillez la recoller."
L["The profession crafting window: recipe list, schematic, specializations, and crafting orders."] = "La fenêtre d'artisanat de métier : liste de recettes, schéma, spécialisations, et commandes d'artisanat."
L["The professions overview book with squared icons and flat progress bars."] = "Le livre d'aperçu des métiers avec des icônes carrées et des barres de progression plates."
L["The recipe preview window shown from a linked recipe or an inspected crafter."] = "La fenêtre d'aperçu de recette affichée depuis une recette liée ou un artisan inspecté."
L["The transmogrification window at the transmogrifier."]       = "La fenêtre de transmogrification chez le transmogrifieur."
L["The vendor window: item list, buyback, and bottom money bar."] = "La fenêtre du marchand : liste d'objets, rachat, et barre de monnaie du bas."
L["The world map window chrome and the quest log side panel."]  = "L'habillage de la fenêtre de carte du monde et le panneau latéral du journal de quêtes."
L["Themed Blizzard frames: window skins, tooltips, menus, popups, Dragon Riding HUD."] = "Cadres Blizzard thématisés : habillages de fenêtre, infobulles, menus, fenêtres, ATH de Chevauchée draconique."
L["Thickness of the Pixel Glow applied to this bar's buff icons."] = "Épaisseur de la lueur pixel appliquée aux icônes d'amélioration de cette barre."
L["This bar will always be attached to your current target's nameplate"] = "Cette barre sera toujours attachée à la barre d'information de votre cible actuelle"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Ce bloc est déjà le bloc « Remplir l'espace restant ». Cochez un autre bloc pour déplacer ce rôle."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Ceci ne peut pas changer les sorts que l'utilisateur suit dans le CDM de Blizzard.\nIl est recommandé de partager aussi votre disposition du CDM Blizzard pour toute spé que vous choisissez ici."
L["This condition is coming in a future update."]               = "Cette condition arrivera dans une future mise à jour."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Ce conditionnel n'est pas actif pour le moment. Remplissez d'abord l'une de ses conditions (par exemple, entrez dans le donjon) pour pouvoir organiser la disposition dans son contexte réel."
L["This frame's source changes require a UI reload to take effect."] = "Les changements de source de ce cadre nécessitent un rechargement de l'interface pour prendre effet."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "Le gestionnaire d'améliorations personnalisé de ce groupe ne peut être activé ou modifié qu'en jouant l'une de ses spécialisations."
L["This module can't be overridden. Exit the override editing session to open it."] = "Ce module ne peut pas être remplacé. Quittez la session d'édition de remplacement pour l'ouvrir."
L["This module is excluded from Spec Overrides."]               = "Ce module est exclu des remplacements de spécialisation."
L["This option requires a custom thickness to be set."]         = "Cette option nécessite qu'une épaisseur personnalisée soit définie."
L["This page is excluded from overrides."]                      = "Cette page est exclue des remplacements."
L["This replaces %d existing value(s) for this setting across your specs. Do you want to continue?"] = "Ceci remplace %d valeur(s) existante(s) pour ce réglage sur vos spécialisations. Voulez-vous continuer ?"
L["This replaces %d existing value(s) for this setting on this bar. Do you want to continue?"] = "Ceci remplace %d valeur(s) existante(s) pour ce réglage sur cette barre. Voulez-vous continuer ?"
L["This setting already has an override for %s"]                = "Ce réglage a déjà un remplacement pour %s"
L["This setting can't be overridden."]                          = "Ce réglage ne peut pas être remplacé."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Cette unité utilise le cadre par défaut de Blizzard -- il n'y a aucun réglage EllesmereUI à configurer ici."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "Le cadre de cette unité est masqué -- il n'y a aucun réglage EllesmereUI à configurer ici."
L["This will create a fully unique Buff Manager for this conditional group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect it."] = "Ceci créera un gestionnaire d'améliorations entièrement unique pour ce groupe conditionnel. Vos réglages actuels du gestionnaire d'améliorations sont copiés comme point de départ, et les changements apportés à votre gestionnaire par défaut ne l'affecteront plus."
L["This will create a fully unique Buff Manager for this override group. Your current Buff Manager settings are copied as its starting point, and changes made to your default Buff Manager will no longer affect these specs."] = "Ceci créera un gestionnaire d'améliorations entièrement unique pour ce groupe de remplacement. Vos réglages actuels du gestionnaire d'améliorations sont copiés comme point de départ, et les changements apportés à votre gestionnaire par défaut n'affecteront plus ces spécialisations."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Ceci créera un mode déverrouillage entièrement unique pour ce groupe conditionnel. Les changements apportés à votre mode déverrouillage par défaut ne l'affecteront plus."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Ceci créera un mode déverrouillage entièrement unique pour ce groupe de remplacement. Les changements apportés à votre mode déverrouillage par défaut n'affecteront plus ces spécialisations."
L["This will reset all default bar spell assignments for the current spec to match Blizzard's CDM layout. Spells you added yourself (presets, custom IDs and racials) are kept. Continue?"] = "Ceci réinitialisera toutes les assignations de sorts des barres par défaut de la spé actuelle pour correspondre à la disposition du CDM de Blizzard. Les sorts que vous avez ajoutés vous-même (préréglages, IDs personnalisés et raciaux) sont conservés. Continuer ?"
L["This will reset all saved panel positions and zoom levels and reload your UI."] = "Ceci réinitialisera toutes les positions de panneau et niveaux de zoom enregistrés et rechargera votre interface."
