L["A Frame Strata dropdown in the Character Crosshair cog controls whether the crosshair draws above or below other UI"] = "Un menu déroulant Niveau d'affichage dans l'engrenage du réticule de personnage contrôle si le réticule s'affiche au-dessus ou en dessous du reste de l'interface"
