L["A checked Hide visibility condition now always hides its element in both match modes, and every condition has its own Show and Hide row, with new Out of Combat and Not Skyriding (Airborne) rows."] = "Une condition de visibilité Masquer cochée masque désormais toujours son élément dans les deux modes de correspondance, et chaque condition dispose de ses propres lignes Afficher et Masquer, avec de nouvelles lignes Hors combat et Pas en vol draconique (en vol)."
L["A clean, airy layout with a calm feel and clear information at a glance. Comfortable for long sessions in any content."] = "Une disposition épurée et aérée, avec une ambiance calme et des informations claires en un coup d'œil. Confortable pour de longues sessions, quel que soit le contenu."
L["A luminous healing setup built around raid frames and crisp readability, keeping your team's health front and center at a glance."] = "Une configuration de soin lumineuse construite autour des cadres de raid et d'une lisibilité nette, gardant la santé de votre équipe au premier plan en un coup d'œil."
L["A new option that makes enemy nameplates pulse with a red glow the moment a target drops below 30% health, so a whole pack tells you at a glance which mobs are in execute range."] = "Une nouvelle option qui fait pulser les barres d'info ennemies d'une lueur rouge dès qu'une cible passe sous 30 % de vie, pour repérer en un coup d'œil quels monstres d'un groupe sont à portée d'exécution."
L["A quick view of every font setting in one place."] = "Une vue rapide de tous les réglages de police en un seul endroit."
L["A quick view of every texture setting in one place."] = "Une vue rapide de tous les réglages de texture en un seul endroit."
L["A raid control panel with ready check, pull timer and raid markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Un panneau de contrôle de raid avec vérification de préparation, minuteur d'engagement et repères de raid. En raid, il ne s'affiche que si vous êtes le chef ou un assistant, car aucun de ses boutons ne fonctionne sans cela ; en groupe, il s'affiche toujours."
L["A shadowed, understated layout that keeps the screen quiet and the essentials close. Information appears exactly when you need it."] = "Une disposition sobre et ombrée qui garde l'écran discret et l'essentiel à portée de main. Les informations apparaissent exactement quand vous en avez besoin."
L["A spec override owns this setting, so this conditional value never applies outside an editing session. Remove the spec override to let it through."] = "Une surcharge de spécialisation possède ce réglage, donc cette valeur conditionnelle ne s'applique jamais en dehors d'une session d'édition. Retirez la surcharge de spécialisation pour la laisser passer."
L["A spec override setting Visibility to Never no longer leaves the frame missing after switching back to another spec."] = "Une surcharge de spécialisation réglant la Visibilité sur Jamais ne laisse plus le cadre manquant après être revenu à une autre spécialisation."
L["A standalone cast bar for this unit, placeable anywhere in Unlock Mode. Runs alongside the Unit Frames cast bars."] = "Une barre d'incantation autonome pour cette unité, plaçable n'importe où en Mode déverrouillage. Fonctionne en parallèle des barres d'incantation des cadres d'unité."
