L["Adds Bonus Roll and Group Loot movers to Unlock Mode."] = "Ajoute les déplaceurs Jet bonus et Butin de groupe au Mode déverrouillage."
L["Adds a Targeting line showing who the hovered player or NPC is targeting, in green when it's you."] = "Ajoute une ligne de ciblage indiquant qui le joueur ou PNJ survolé cible, en vert lorsque c'est vous."
L["Adds a compact Raid Tools window -- target/world markers, ready check, role check and pull timer in one resizable row. It runs alongside whichever Show as layout is picked above (or with Raid Tools fully off), moves and resizes independently through Unlock Mode, and only appears while you're actually in a raid group."] = "Ajoute une fenêtre compacte d'Outils de raid -- repères de cible/monde, vérification de préparation, vérification de rôle et minuteur d'engagement dans une seule ligne redimensionnable. Elle fonctionne en parallèle de la disposition « Afficher en tant que » choisie ci-dessus (ou même avec les Outils de raid totalement désactivés), se déplace et se redimensionne indépendamment via le Mode déverrouillage, et n'apparaît que lorsque vous êtes réellement dans un groupe de raid."
L["Adds a mover for Blizzard's top-center event text and widgets (scenario, event, and encounter bars)."] = "Ajoute un déplaceur pour le texte d'événement et les widgets en haut au centre de Blizzard (barres de scénario, d'événement et de combat)."
L["Adds a small filled dot at the center of the cursor circle. Uses the same color and opacity as the circle."] = "Ajoute un petit point plein au centre du cercle du curseur. Utilise la même couleur et opacité que le cercle."
L["Adds a steady red glow around the nameplate while the Near Aggro color is active."] = "Ajoute une lueur rouge continue autour de la barre d'info tant que la couleur Proche de l'aggro est active."
L["Adds a strip down the left edge of a loot toast in the item's quality color. The flat skin drops Blizzard's quality ring around the icon, so this puts that rarity cue back."] = "Ajoute une bande le long du bord gauche d'une notification de butin dans la couleur de qualité de l'objet. Le thème épuré retire l'anneau de qualité de Blizzard autour de l'icône, ceci restaure donc cet indice de rareté."
L["Adds three optional world-marker keybinds that remain usable in combat. Place drops the first free marker at the cursor in Star to Skull order; Undo removes the last marker placed through Quick Fire; Clear removes all world markers. Every binding starts empty. Marker changes made elsewhere during combat are picked up afterward."] = "Ajoute trois raccourcis optionnels de repères du monde qui restent utilisables en combat. Placer dépose le premier repère libre au curseur, dans l'ordre Étoile à Crâne ; Annuler retire le dernier repère placé via Tir rapide ; Effacer retire tous les repères du monde. Chaque raccourci démarre vide. Les changements de repères effectués ailleurs pendant le combat sont pris en compte ensuite."
L["Adds timestamps to system messages, loot, achievements, and addon messages, not just player chat."] = "Ajoute des horodatages aux messages système, au butin, aux hauts faits et aux messages d'addons, pas seulement au chat des joueurs."
