L["Aligns the tab bar to the outer sidebar edge instead of only the chat panel edge."] = "Aligne la barre d'onglets sur le bord extérieur de la barre latérale au lieu du seul bord du panneau de chat."
L["All Buffs or Has Duration is selected, so every buff already shows. Use the red Hide box to exclude these instead."] = "Toutes les améliorations ou A une durée est sélectionné, donc toutes les améliorations s'affichent déjà. Utilisez plutôt la case rouge Masquer pour les exclure."
