L["All Debuffs is selected, so every debuff already shows. Use the red Hide box to exclude these instead."] = "Tous les affaiblissements est sélectionné, donc tous les affaiblissements s'affichent déjà. Utilisez plutôt la case rouge Masquer pour les exclure."
L["All Debuffs"] = "Tous les affaiblissements"
