L["All Non Healers/Aug"] = "Tous les non-soigneurs/Aug"
L["All Other Specs"] = "Toutes les autres spécialisations"
L["All debuffs except the ones you or your pet applied."] = "Tous les affaiblissements sauf ceux appliqués par vous ou votre familier."
L["All entries in the Threshold Settings spec dropdown are now clickable."] = "Toutes les entrées du menu déroulant de spécialisation des réglages de seuil sont désormais cliquables."
L["Allowed Demons picks which demons count as correct for any Warlock spec, and the Missing Pet reminder now summons on click"] = "Démons autorisés détermine quels démons comptent comme corrects pour toute spécialisation de Démoniste, et le rappel Familier manquant invoque désormais au clic"
L["Aloft"] = "Aloft" -- TODO: confirmar termo oficial
L["Already tracked"] = "Déjà suivi"
L["Also show the badge in dungeons and raids, where most enemies are elite."] = "Afficher aussi le badge en donjon et en raid, où la plupart des ennemis sont d'élite."
L["Also show the strip on gold toasts, in the header's gold color. Gold has no rarity to signal, so this is off by default."] = "Afficher aussi la bande sur les notifications d'or, dans la couleur or de l'en-tête. L'or n'a pas de rareté à signaler, donc ceci est désactivé par défaut."
L["Also use the split dialog with Auto Split in OneBag, MultiBag, the reagent bag, the bank and the guild bank, replacing Blizzard's split popup there. All Items and category views always use it."] = "Utilise aussi la fenêtre de division avec Division automatique dans OneBag, MultiBag, le sac à composants, la banque et la banque de guilde, en remplaçant la fenêtre de division de Blizzard. Les vues Tous les objets et par catégorie l'utilisent toujours."
L["Altar of Fangs"] = "Autel des Crocs" -- TODO: confirmar termo oficial
L["Always Show Cooldown Edge"] = "Toujours afficher le bord de recharge"
L["Always Show Pet Frame"] = "Toujours afficher le cadre du familier"
L["Always Show Split Times"] = "Toujours afficher les temps intermédiaires"
L["Always Show While Skyriding /\nIn Vehicle"] = "Toujours afficher en vol draconique /\nEn véhicule"
L["Always Visible"] = "Toujours visible"
L["Always color the item level by item rarity instead of its upgrade track."] = "Toujours colorer le niveau d'objet selon la rareté de l'objet plutôt que sa piste d'amélioration."
L["Always keeps it fully visible. Mouseover fades it out until the cursor is over it."] = "Le garde toujours totalement visible. Survol l'estompe jusqu'à ce que le curseur soit dessus."
L["Always keeps the shown windows and the button that opens them fully visible. Mouseover fades them out until you move your cursor over them."] = "Garde toujours les fenêtres affichées et le bouton qui les ouvre totalement visibles. Survol les estompe jusqu'à ce que vous déplaciez votre curseur dessus."
L["Always on for Whirlwind and Sweeping Strikes charges: range coloring at/above the threshold is the only way these bars can display thresholds."] = "Toujours actif pour les charges de Coup d'ouragan et Frappes balayantes : la coloration selon la plage au seuil ou au-dessus est le seul moyen pour ces barres d'afficher des seuils."
L["Always show Blizzard's bright rotating edge on cooldowns in this bar. Hide Recharge Edge still overrides this for individual charge spells."] = "Toujours afficher le bord tournant lumineux de Blizzard sur les recharges de cette barre. Masquer le bord de recharge prime toujours sur ceci pour les sorts à charges individuels."
L["Always show less common settings instead of collapsing them behind a Show Less Common link."] = "Toujours afficher les réglages moins courants au lieu de les replier derrière un lien Afficher moins de réglages courants."
L["Always shows the chat tabs. Mouseover hides them until you move the cursor over the tab bar."] = "Affiche toujours les onglets de chat. Survol les masque jusqu'à ce que vous déplaciez le curseur sur la barre d'onglets."
L["Ambience"] = "Ambiance"
L["An Unanchored Position"] = "Une position non ancrée"
L["Anchor To"] = "Ancrer à"
L["Anchor icons and text as if no power bar existed, so frames with and without one line up identically."] = "Ancre les icônes et le texte comme si aucune barre de ressource n'existait, pour que les cadres avec et sans celle-ci s'alignent de façon identique."
L["Anchor the scroll-to-bottom arrow to the chat's corner like default UI"] = "Ancre la flèche de défilement vers le bas au coin du chat comme l'interface par défaut"
L["Anchor to Debuffs"] = "Ancrer aux affaiblissements"
L["Anchors the Scroll to Bottom button to the bottom-right corner of the chat panel instead of the sidebar."] = "Ancre le bouton Défiler jusqu'en bas au coin inférieur droit du panneau de chat au lieu de la barre latérale."
L["Announce Focus"] = "Annoncer la focalisation"
L["Another override group already provides the custom Debuff Manager for your current spec."] = "Un autre groupe de surcharge fournit déjà le gestionnaire d'affaiblissements personnalisé pour votre spécialisation actuelle."
L["Any LibDataBroker plugin registered right now. One block per plugin -- add the block again for a second one."] = "Tout plugin LibDataBroker actuellement enregistré. Un bloc par plugin -- ajoutez à nouveau le bloc pour en obtenir un second."
L["Any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it."] = "Tout affaiblissement avec un type de dissipation (Magie, Malédiction, Maladie, Poison, Saignement), même si vous ne pouvez pas le retirer."
L["AoF"] = "AoF" -- JARGAO
L["Appends the cast target to the spell name (Spell Name - Target), class colored, and disables the separate Spell Target display."] = "Ajoute la cible de l'incantation au nom du sort (Nom du sort - Cible), coloré par classe, et désactive l'affichage séparé de la cible du sort."
L["Applies one text size to every chat window, saved with your profile. Individual windows can still be adjusted from their tab's right-click menu until the next login re-applies the profile size."] = "Applique une seule taille de texte à toutes les fenêtres de chat, enregistrée avec votre profil. Les fenêtres individuelles peuvent toujours être ajustées depuis le menu clic droit de leur onglet, jusqu'à ce que la prochaine connexion réapplique la taille du profil."
