L["Choose the profile-wide border or glow used for Blizzard's Assisted Combat suggestion."] = "Choisissez la bordure ou la lueur, valable pour tout le profil, utilisée pour la suggestion de Combat assisté de Blizzard." -- TODO: confirmar termo oficial
L["Choose which addons to include in your exported profile. Check everything for a full profile export."] = "Choisissez quels addons inclure dans votre profil exporté. Cochez tout pour un export complet du profil."
L["Choose which channels get a bubble.\n\nSay, Yell, NPCs and Emotes share one Blizzard switch. It is turned on while at least one of the four is ticked, and put back the way you had it once you clear the last one. Party and Raid have switches of their own and start out matching what you already had, so no group bubbles turn up in a chat that had none.\n\nGuild is not offered: Blizzard draws no bubble for guild chat, and there is nothing for us to restyle."] = "Choisissez quels canaux obtiennent une bulle.\n\nDire, Crier, PNJ et Émotes partagent un seul interrupteur Blizzard. Il est activé dès qu'au moins un des quatre est coché, et remis comme vous l'aviez laissé une fois le dernier décoché. Groupe et Raid ont leurs propres interrupteurs et démarrent en accord avec ce que vous aviez déjà, afin qu'aucune bulle de groupe n'apparaisse dans un chat qui n'en avait pas.\n\nGuilde n'est pas proposé : Blizzard n'affiche aucune bulle pour le chat de guilde, et il n'y a rien à restyliser pour nous."
L["Choose which specs sync with %1$s, including your alts' specs (the source is always included)"] = "Choisissez quelles spécialisations se synchronisent avec %1$s, y compris les spécialisations de vos alts (la source est toujours incluse)"
L["Choose which tooltips appear on hover. Affects all unit frames, including boss frames."] = "Choisissez quelles infobulles apparaissent au survol. Affecte tous les cadres d'unité, y compris les cadres de boss."
