L["Clickable links and player names on lines with shortened channel names now respond exactly where they appear, and the wheel scrolls into restored history right after a reload."] = "Les liens cliquables et les noms de joueurs sur les lignes avec des noms de canaux raccourcis répondent désormais exactement là où ils apparaissent, et la molette défile dans l'historique restauré juste après un rechargement."
