L["Close After (sec)"] = "Fermer après (sec)"
L["Close After Delay"] = "Délai avant fermeture"
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Ferme un menu ouvert sans rien utiliser. Échap fait également toujours cela. Une touche partagée par tous les menus, réservée uniquement pendant qu'un menu est ouvert -- un bouton de souris conserve son usage normal le reste du temps."
L["Closes an open menu without using anything. Escape always does this as well. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Ferme un menu ouvert sans rien utiliser. Échap fait également toujours cela. Une touche partagée par tous les menus, réservée uniquement pendant qu'un menu est ouvert -- un bouton de souris conserve son usage normal le reste du temps.\n\nClic gauche pour définir un raccourci, puis appuyez sur n'importe quelle touche ou\ncliquez sur n'importe quel bouton de souris pour l'utiliser.\nÉchap annule. Clic droit ici pour délier."
L["Coin Colored"] = "Couleur de pièce"
L["Collapses the windows back to the icon on their own after they've been open (and the cursor hasn't been over them) for the delay below -- the same result as clicking the close button, just on a timer. Moving the cursor over the windows pauses the timer and it starts over once you look away."] = "Replie les fenêtres vers l'icône automatiquement après qu'elles soient restées ouvertes (et que le curseur n'ait pas été dessus) pendant le délai ci-dessous -- le même résultat qu'un clic sur le bouton de fermeture, mais sur une minuterie. Déplacer le curseur sur les fenêtres met la minuterie en pause, qui redémarre dès que vous regardez ailleurs."
L["Color Name by Reaction"] = "Colorer le nom selon la réaction"
L["Color by Rarity"] = "Colorer par rareté"
L["Color by Type (Magic/Enrage)"] = "Colorer par type (Magie/Enrage)"
L["Color by Type"] = "Colorer par type"
L["Color of the flat overlay behind the Compact Band's buttons."] = "Couleur de la superposition plate derrière les boutons de la Bande compacte."
L["Color of the out-of-range darken overlay. Defaults to gray -- pick something else if it's hard to see against your Fill Color."] = "Couleur de l'assombrissement hors de portée. Gris par défaut -- choisissez autre chose si c'est difficile à voir sur votre couleur de remplissage."
L["Color the bar differently at several stack counts. The highest count you have reached wins."] = "Colore la barre différemment à plusieurs paliers de cumuls. Le palier le plus élevé atteint l'emporte."
L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Colore la barre de vie selon la quantité de vie restante, au lieu d'une couleur unie. Classique passe du vert à plein vie au jaune puis au rouge à vide. Couleurs personnalisées mélange les trois teintes de cette ligne -- plein (100 %), moitié (50 %) et vide (0 %). Réactif à la classe affiche la couleur de classe à pleine vie, se fondant vers les couleurs à 50 % et 0 % à mesure que l'unité subit des dégâts. Désactivé laisse les teintes de couleur de remplissage unies en charge ; dans tous les cas, le Dégradé ci-dessous s'applique toujours, à partir de la couleur choisie ici."
L["Colored Percentages"] = "Pourcentages colorés"
L["Colored Values"] = "Valeurs colorées"
L["Colors group and raid member names by their class when they appear in the text of Say, Yell, Party, and Raid messages."] = "Colore les noms des membres du groupe et du raid selon leur classe lorsqu'ils apparaissent dans le texte des messages Dire, Crier, Groupe et Raid."
L["Colors the cast segment during which your interrupt will be available."] = "Colore le segment d'incantation pendant lequel votre interruption sera disponible."
L["Colors the enemy nameplate name text to match the unit's reaction (Hostile or Neutral) instead of the Enemy Name Text color."] = "Colore le texte du nom sur la barre d'info ennemie selon la réaction de l'unité (Hostile ou Neutre) au lieu de la couleur de texte de nom ennemi."
