L["Combines with the conditions below: shows outright once at least one passes, otherwise still reveals on hover. A checked Hide state still hides it, hover included."] = "Se combine avec les conditions ci-dessous : s'affiche directement dès qu'au moins une est remplie, sinon se révèle quand même au survol. Un état Masquer coché le masque tout de même, survol inclus."
L["Comma separated stack counts to put a tick mark at. Type all to mark every stack."] = "Nombres de cumuls séparés par des virgules où placer une marque. Tapez all pour marquer chaque cumul."
