L["Compact Band puts markers, ready check and pull timer in one resizable row. The other choices keep the original window layouts."] = "Bande compacte regroupe les repères, la vérification de préparation et le minuteur d'engagement dans une seule ligne redimensionnable. Les autres choix conservent les dispositions de fenêtre originales."
L["Compact Band"] = "Bande compacte"
