L["Compare only against splits from the same key level (off: new key levels compare against your dungeon best)."] = "Comparer uniquement avec les temps intermédiaires du même niveau de clé (désactivé : les nouveaux niveaux de clé se comparent à votre meilleur temps de donjon)."
L["Comparison"] = "Comparaison"
L["Concentrated Health Potion"] = "Potion de soins concentrée" -- TODO: confirmar termo oficial
L["Configurable text color, size, bar height and text position for the queue accept countdown, via a swatch and cog beside Show Queue Timer"] = "Couleur, taille et position du texte, et hauteur de barre configurables pour le compte à rebours d'acceptation de file d'attente, via une pastille et un engrenage à côté d'Afficher le minuteur de file d'attente"
L["Conflicting Keybind"] = "Raccourci en conflit"
L["Contained"] = "Contenu"
L["Controls the display order of raid and party frames. Set higher to show above other elements."] = "Contrôle l'ordre d'affichage des cadres de raid et de groupe. Augmentez la valeur pour afficher au-dessus des autres éléments."
L["Controls the frame layering (strata) this bar renders on. Raise it if the bar is being covered by another window; lower it if it should render behind other UI."] = "Contrôle le niveau d'affichage (strate) sur lequel cette barre s'affiche. Augmentez-le si la barre est recouverte par une autre fenêtre ; diminuez-le si elle doit s'afficher derrière le reste de l'interface."
L["Controls the opacity of the flat color background behind action button icons."] = "Contrôle l'opacité de l'arrière-plan de couleur unie derrière les icônes des boutons d'action."
L["Controls where status icons are displayed. Use the individual settings to choose which icons are shown: Ready Check, Resurrection, Other Phase, or Other Party."] = "Contrôle où les icônes de statut s'affichent. Utilisez les réglages individuels pour choisir quelles icônes sont affichées : Vérification de préparation, Résurrection, Autre phase, ou Autre groupe."
L["Controls where the incoming-summon icon is displayed, independent of the Status Icon slot above."] = "Contrôle où l'icône d'invocation entrante s'affiche, indépendamment de l'emplacement d'icône de statut ci-dessus."
L["Controls whether the Dead status text is displayed and where, independent of the Offline/AFK Status Text above."] = "Contrôle si le texte de statut Mort s'affiche et où, indépendamment du texte de statut Hors ligne/AFK ci-dessus."
L["Controls whether the Offline/AFK status text is displayed and where. Dead status text has its own independent settings below."] = "Contrôle si le texte de statut Hors ligne/AFK s'affiche et où. Le texte de statut Mort a ses propres réglages indépendants ci-dessous."
