L["Countdown length in seconds. Compact Band uses First with Ctrl + Left Click, Second with Shift + Left Click, Third with Left Click, and Right Click stops the timer. Set a timer to 0 to disable that shortcut."] = "Durée du compte à rebours en secondes. La Bande compacte utilise Premier avec Ctrl + clic gauche, Deuxième avec Maj + clic gauche, Troisième avec clic gauche, et le clic droit arrête le minuteur. Réglez un minuteur sur 0 pour désactiver ce raccourci."
L["Countdown length of this pull button, in seconds. Set it to 0 to hide the button; with all three at 0 the whole pull row disappears, Stop included."] = "Durée du compte à rebours de ce bouton d'engagement, en secondes. Réglez-le sur 0 pour masquer le bouton ; avec les trois à 0, toute la ligne d'engagement disparaît, Arrêt inclus."
