L["Draw a 1px divider between the spell icon and the cast bar, matching the border color."] = "Trace un séparateur de 1px entre l'icône du sort et la barre d'incantation, correspondant à la couleur de bordure."
L["Draw a filled background behind the text and border. Off draws the text and border on their own."] = "Trace un arrière-plan rempli derrière le texte et la bordure. Désactivé trace le texte et la bordure seuls."
L["Draw a solid one-pixel separator between the icon and cast bar when the icon is part of the bar."] = "Trace un séparateur uni d'un pixel entre l'icône et la barre d'incantation lorsque l'icône fait partie de la barre."
L["Draw role icons behind the frame border, including the hover and target highlight."] = "Trace les icônes de rôle derrière la bordure du cadre, y compris le surlignage de survol et de cible."
L["Draw tick lines across the bar at positions you choose."] = "Trace des lignes de graduation sur la barre aux positions de votre choix."
L["Draws a border around each pip instead of the bar as a whole."] = "Trace une bordure autour de chaque pastille au lieu de toute la barre."
L["Drop the individual Tab 1 / Tab 2 / Warbank Tab entries once the category list is doing the navigating. The consolidated views stay. Note that right-clicking a tab entry is the only way to rename a tab or change its deposit filters, so leave this off if you still need that."] = "Retire les entrées individuelles Onglet 1 / Onglet 2 / Onglet de banque de bataillon une fois que la liste des catégories assure la navigation. Les vues consolidées restent. Notez que le clic droit sur une entrée d'onglet est le seul moyen de renommer un onglet ou de changer ses filtres de dépôt, donc laissez ceci désactivé si vous en avez encore besoin."
L["Drops columns nothing in this group can satisfy instead of greying them: no mage means no Intellect column, and a Mythic+ key means no Vantus. Turn off to keep every column in place whatever the group."] = "Retire les colonnes qu'aucun membre de ce groupe ne peut satisfaire au lieu de les griser : pas de mage signifie pas de colonne Intelligence, et une clé Mythique+ signifie pas de Vantus. Désactivez pour garder toutes les colonnes en place quel que soit le groupe."
L["Drops crests you own none of, keeping the block short early in a season. They stay listed in the tooltip."] = "Retire les écus dont vous ne possédez aucun exemplaire, gardant le bloc court en début de saison. Ils restent listés dans l'infobulle."
L["Druid Forms"] = "Formes de druide"
L["Druid travel, aquatic and flight forms count as mounted."] = "Les formes de voyage, aquatique et de vol du druide comptent comme montées."
L["Due to Blizzard API restrictions, Blizzard's native %s can't be hidden in combat and will show the whole time you are in combat. Recommended: match the %s frame's source -- both Blizzard Default, or both EllesmereUI."] = "En raison des restrictions de l'API Blizzard, le %s natif de Blizzard ne peut pas être masqué en combat et s'affichera pendant toute la durée du combat. Recommandé : faites correspondre la source du cadre %s -- les deux en Blizzard par défaut, ou les deux en EllesmereUI."
L["Due to Blizzard API restrictions, Blizzard's native focus-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Focus frame's source -- both Blizzard Default, or both EllesmereUI."] = "En raison des restrictions de l'API Blizzard, la cible-de-focalisation native de Blizzard ne peut pas être masquée en combat et s'affichera pendant toute la durée du combat. Recommandé : faites correspondre la source du cadre Focalisation -- les deux en Blizzard par défaut, ou les deux en EllesmereUI."
L["Due to Blizzard API restrictions, Blizzard's native target-of-target can't be hidden in combat and will show the whole time you are in combat. Recommended: match the Target frame's source -- both Blizzard Default, or both EllesmereUI."] = "En raison des restrictions de l'API Blizzard, la cible-de-la-cible native de Blizzard ne peut pas être masquée en combat et s'affichera pendant toute la durée du combat. Recommandé : faites correspondre la source du cadre Cible -- les deux en Blizzard par défaut, ou les deux en EllesmereUI."
L["Dungeons, raids, scenarios, arenas and battlegrounds. Garrisons do not count."] = "Donjons, raids, scénarios, arènes et champs de bataille. Les garnisons ne comptent pas."
