L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI n'a pas pu enregistrer cette modification dans votre disposition du Mode édition, elle doit donc être définie manuellement. Le Gestionnaire de recharge doit être désactivé pendant cette opération, car il masque les visualiseurs de recharge de Blizzard et un visualiseur masqué ne peut pas être sélectionné en Mode édition.\n\n"
L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n1. Disable EllesmereUI Cooldown Manager (button below).\n2. Open Edit Mode from the Game Menu.\n3. Select each Cooldown Manager viewer and set Visibility to Always.\n4. On Tracked Buffs and Tracked Bars, tick Hide When Inactive.\n5. Save the layout and leave Edit Mode.\n6. Re-enable EllesmereUI Cooldown Manager."] = "EllesmereUI n'a pas pu enregistrer cette modification dans votre disposition du Mode édition, elle doit donc être définie manuellement. Le Gestionnaire de recharge doit être désactivé pendant cette opération, car il masque les visualiseurs de recharge de Blizzard et un visualiseur masqué ne peut pas être sélectionné en Mode édition.\n\n1. Désactivez le Gestionnaire de recharge EllesmereUI (bouton ci-dessous).\n2. Ouvrez le Mode édition depuis le Menu du jeu.\n3. Sélectionnez chaque visualiseur du Gestionnaire de recharge et réglez la Visibilité sur Toujours.\n4. Sur Améliorations suivies et Barres suivies, cochez Masquer si inactif.\n5. Enregistrez la disposition et quittez le Mode édition.\n6. Réactivez le Gestionnaire de recharge EllesmereUI."
L["EllesmereUI restyles Blizzard's chat bubbles and turns on the switches it needs. Party and Raid keep your current setting, and everything is put back when you turn this off."] = "EllesmereUI restyle les bulles de chat de Blizzard et active les interrupteurs nécessaires. Groupe et Raid conservent votre réglage actuel, et tout est remis en place lorsque vous désactivez ceci."
