L["Hide and show every damage meter window at once. The state is not saved; a reload restores the configured visibility.\n\nThe bound key is taken over while it is set. Use the cog to include the combat timer and Spell History.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Masquer et afficher toutes les fenêtres de compteur de dégâts à la fois. L'état n'est pas enregistré ; un rechargement restaure la visibilité configurée.\n\nLa touche assignée est accaparée tant qu'elle est définie. Utilisez l'engrenage pour inclure le chrono de combat et l'historique des sorts.\n\nClic gauche pour définir un raccourci.\nClic droit pour le retirer."
L["Hide enemy nameplates while you are out of combat; they return the moment combat starts. Drives the same game setting as the Show Enemy Name Plates keybind."] = "Masquer les barres d'info ennemies hors combat ; elles reviennent dès le début du combat. Agit sur le même réglage de jeu que le raccourci Afficher les plaques d'identification ennemies."
L["Hide entries this character cannot use: another class's specializations and spells, and macros this character does not have. One shared menu then fits every character. The menu editor always shows every entry."] = "Masquer les entrées que ce personnage ne peut pas utiliser : les spécialisations et sorts d'une autre classe, ainsi que les macros que ce personnage n'a pas. Un seul menu partagé convient alors à tous les personnages. L'éditeur de menu affiche toujours toutes les entrées."
L["Hide every Cooldown Manager glow out of combat and bring them all back the moment you enter combat."] = "Masquer toutes les lueurs du Gestionnaire de recharge hors combat et les faire toutes revenir dès l'entrée en combat."
L["Hide every Cooldown Manager glow while you are out of combat: proc glows, active state, max stacks, buff and pandemic glows, cooldown ready glows and bar glows.\n\nThey come back the moment you enter combat, including a glow that started before the pull.\n\nApplies to every CDM bar and to the Tracking Bars at once. Glows from other EllesmereUI modules are not affected.\n\nThe Bar Glows page keeps its own per-mapping Only In Combat toggle; this one applies on top of it."] = "Masquer toutes les lueurs du Gestionnaire de recharge hors combat : lueurs de proc, état actif, cumuls max, lueurs d'amélioration et de pandémie, lueurs de recharge prête et lueurs de barre.\n\nElles reviennent dès l'entrée en combat, y compris une lueur qui a commencé avant le pull.\n\nS'applique à toutes les barres CDM et aux barres de suivi à la fois. Les lueurs des autres modules d'EllesmereUI ne sont pas affectées.\n\nLa page Lueurs de barre conserve son propre interrupteur « Uniquement en combat » par association ; celui-ci s'applique en plus."
L["Hide in Delves"] = "Masquer dans les gouffres"
L["Hide in PvP"] = "Masquer en JcJ"
L["Hide the 1-pixel border around the cast bar spell icon."] = "Masquer la bordure d'1 pixel autour de l'icône de sort de la barre d'incantation."
L["Hide the 1-pixel outline around the bar."] = "Masquer le contour d'1 pixel autour de la barre."
L["Hide the charge number on action buttons when it reaches 0, instead of showing a 0. The number returns as soon as a charge or item comes back."] = "Masquer le nombre de charges sur les boutons d'action lorsqu'il atteint 0, au lieu d'afficher un 0. Le nombre revient dès qu'une charge ou un objet redevient disponible."
L["Hide the charge number while a spell has no charges left, instead of showing a 0. The number returns as soon as a charge comes back."] = "Masquer le nombre de charges tant qu'un sort n'a plus de charge, au lieu d'afficher un 0. Le nombre revient dès qu'une charge redevient disponible."
L["Hide the preview"] = "Masquer l'aperçu"
L["Hide these instead of showing them"] = "Masquer ceux-ci au lieu de les afficher"
L["Hide this bar completely while out of combat, even when the tracked buff/cooldown is active."] = "Masquer complètement cette barre hors combat, même lorsque l'amélioration/la recharge suivie est active."
L["Hide this bar's icon art, cooldown swipe, recharge edge and cooldown text, leaving only the charge or stack count."] = "Masquer le visuel d'icône, le balayage de recharge, le contour de recharge et le texte de recharge de cette barre, ne laissant que le nombre de charges ou de cumuls."
L["Hide this bar's icons and show only the duration text."] = "Masquer les icônes de cette barre et n'afficher que le texte de durée."
L["Hide when Skyriding Mounted"] = "Masquer en vol draconique monté"
L["Hide while this condition is true"] = "Masquer tant que cette condition est vraie"
L["Hides Blizzard's \"Loot Rolls\" window -- the running list of dropped items showing who rolled what and who won. Use the cog to let it appear briefly and close itself instead. The Need/Greed roll popups themselves are not affected."] = "Masque la fenêtre « Tirages au sort » de Blizzard -- la liste continue des objets récupérés indiquant qui a tiré quoi et qui a gagné. Utilisez l'engrenage pour la faire apparaître brièvement puis se refermer d'elle-même. Les fenêtres surgissantes de tirage Besoin/Cupidité elles-mêmes ne sont pas affectées."
L["Hides the Top Bar Event Text mover in Unlock Mode while keeping its saved position applied."] = "Masque le déplaceur du texte d'événement de la barre supérieure en mode Déverrouillage tout en conservant sa position enregistrée."
L["Hides the master header and its minimize button at the top of the tracker. When shown, it's skinned to match the section headers below it (Quests, Achievements, ...)."] = "Masque l'en-tête principal et son bouton de réduction en haut du suivi. Quand il est affiché, il est habillé pour correspondre aux en-têtes de section en dessous (Quêtes, Hauts faits, ...)."
L["Hides the ready check glyph above the prompt, leaving just the question and the Yes / No buttons. Applies while the Ready Check reskin is enabled."] = "Masque le symbole de vérification de préparation au-dessus de l'invite, ne laissant que la question et les boutons Oui / Non. S'applique tant que l'habillage de la Vérification de préparation est activé."
L["Highest First"] = "Le plus élevé en premier"
L["Highest group size that uses this layout."] = "Taille de groupe maximale utilisant cette disposition."
L["Highlight Border"] = "Bordure de surbrillance"
L["Hold Capped Artisan Payouts"] = "Conserver les gains d'artisan plafonnés" -- TODO: confirmar termo oficial
L["Hold a key to open a menu of actions; point or scroll to choose, release to fire."] = "Maintenez une touche pour ouvrir un menu d'actions ; pointez ou faites défiler pour choisir, relâchez pour valider."
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire. Build up to 16 menus in Arc, Fan, or Grid layouts, nest menus inside menus, and tune every setting per menu."] = "Maintenez un raccourci pour ouvrir un menu d'actions ; pointez ou faites défiler pour choisir, relâchez pour valider. Créez jusqu'à 16 menus en disposition Arc, Éventail ou Grille, imbriquez des menus dans des menus, et ajustez chaque réglage par menu."
L["Hold a keybind to open a menu of actions; point or scroll to choose, release to fire."] = "Maintenez un raccourci pour ouvrir un menu d'actions ; pointez ou faites défiler pour choisir, relâchez pour valider."
L["Hold a keybind to open a palette of actions; point or scroll to choose, release to fire."] = "Maintenez un raccourci pour ouvrir une palette d'actions ; pointez ou faites défiler pour choisir, relâchez pour valider."
L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "Fige le bloc à cette largeur et tronque le texte trop long, afin qu'un module complémentaire dont le texte change constamment de longueur ne décale jamais les blocs voisins. Zéro ajuste le bloc à la taille du texte actuel du module."
