L["Hover Border Size"] = "Taille de la bordure au survol"
L["Hovering names in the Guild & Communities roster no longer errors, and member tooltips keep their race and class lines."] = "Survoler des noms dans la liste de la Guilde et communautés ne génère plus d'erreur, et les infobulles des membres conservent leurs lignes de race et de classe."
L["How Blizzard's next-spell suggestion is drawn on the button. Button Overlay replaces the blue ring with a flat tint, leaving the button edge free for the proc glow."] = "Comment la suggestion de prochain sort de Blizzard est dessinée sur le bouton. Superposition de bouton remplace l'anneau bleu par une teinte plate, laissant le bord du bouton libre pour la lueur de proc."
L["How extra columns grow when the second column appears or disappears. Grow Right keeps the left column in place, Grow Left keeps the right column in place, Grow Centered keeps the bar centered."] = "Comment les colonnes supplémentaires croissent quand la deuxième colonne apparaît ou disparaît. Croissance à droite garde la colonne gauche en place, Croissance à gauche garde la colonne droite en place, Croissance centrée garde la barre centrée."
L["How extra rows grow when the second row appears or disappears. Grow Down keeps the top row in place, Grow Up keeps the bottom row in place, Grow Centered keeps the bar centered."] = "Comment les rangées supplémentaires croissent quand la deuxième rangée apparaît ou disparaît. Croissance vers le bas garde la rangée du haut en place, Croissance vers le haut garde la rangée du bas en place, Croissance centrée garde la barre centrée."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span. A nest reaches over the plain entries it passes, and they only give up their angles while it is open."] = "Jusqu'où, le long de l'arc, un nid peut étaler ses entrées. Contenu le garde à l'écart du nid voisin de chaque côté, afin que deux nids ne se dessinent jamais l'un sur l'autre. Débordant lui permet d'utiliser toute l'Étendue max. de nid. Un nid s'étend par-dessus les entrées simples qu'il traverse, et celles-ci ne cèdent leur angle que tant qu'il est ouvert."
L["How far along the arc a nest may spread its entries. Contained keeps it clear of the next nest either side, so two of them are never drawn on top of one another. Overflowing lets it use the whole of Max Nest Span."] = "Jusqu'où, le long de l'arc, un nid peut étaler ses entrées. Contenu le garde à l'écart du nid voisin de chaque côté, afin que deux nids ne se dessinent jamais l'un sur l'autre. Débordant lui permet d'utiliser toute l'Étendue max. de nid."
L["How far along the arc a nest may spread its entries."] = "Jusqu'où, le long de l'arc, un nid peut étaler ses entrées."
L["How long the windows stay open, cursor off them, before Auto-Minimize collapses them."] = "Combien de temps les fenêtres restent ouvertes, curseur hors d'elles, avant que la Réduction automatique ne les réduise."
L["How many decimal places the number carries."] = "Combien de décimales le nombre comporte."
L["How many entries a row of the grid holds. 1 stacks them into a single column; %1$s -- the most slots an action menu can hold -- lays them out in a single row."] = "Combien d'entrées une rangée de la grille contient. 1 les empile en une seule colonne ; %1$s -- le nombre maximal d'emplacements qu'un menu d'actions peut contenir -- les dispose en une seule rangée."
L["How many icons to show on the base row (the row that fills first and that Row Growth keeps in place). The rest go on the second row."] = "Combien d'icônes afficher sur la rangée de base (la rangée qui se remplit en premier et que la Croissance de rangée garde en place). Le reste va sur la deuxième rangée."
L["How many pixels the custom effect extends beyond the icon."] = "De combien de pixels l'effet personnalisé dépasse l'icône."
L["How much is trimmed from the icon's top and bottom, as a percentage per side. 10% is the classic cropped look."] = "Quelle part est rognée en haut et en bas de l'icône, en pourcentage par côté. 10 % donne l'aspect rogné classique."
