L["Icon ID always shown for this spell (empty removes)"] = "ID d'icône toujours affiché pour ce sort (vide pour retirer)"
L["Icon Outset"] = "Saillie d'icône"
L["Icon Slots Tall (0 = Off)"] = "Emplacements d'icône en hauteur (0 = désactivé)"
