L["Icon duration, stacks, keybinds and tracking bar text"] = "Texte de durée, de cumuls, de raccourcis et de barre de suivi d'icône"
L["Icon file ID for '"] = "ID de fichier d'icône pour '"
L["IconID"] = "IconID" -- JARGAO
L["Icons Ignore Power Bar"] = "Les icônes ignorent la barre de ressource"
L["Ignore"] = "Ignorer"
L["Imp"] = "Diablotin"
L["Import & Reload"] = "Importer et recharger"
L["Import Full Account Data"] = "Importer toutes les données de compte"
L["Import the sharer's complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. This replaces ALL of your own overrides. Off = keep yours untouched."] = "Importer la configuration complète des remplacements du partageur : valeurs de remplacement par spécialisation et conditionnelles, groupes, leurs dispositions personnalisées en mode Déverrouillage, et les remplacements du Gestionnaire d'améliorations. Cela remplace TOUS vos propres remplacements. Désactivé = conserver les vôtres intacts."
L["Important (Priority)"] = "Important (priorité)"
L["Important Cast Glow Settings"] = "Réglages de la lueur d'incantation importante"
L["Important Only"] = "Important uniquement"
L["Important and Own"] = "Important et personnel"
L["Important or Own"] = "Important ou personnel"
L["Improved Talent Loadouts"] = "Configurations de talents améliorées"
L["In Any Group"] = "Dans n'importe quel groupe"
L["In Party & Raid"] = "En groupe et en raid"
L["In Raid"] = "En raid"
L["In The Armory and the Weapons / Trinkets, Armor, and Item Set Gear category views, group items under equip-slot sub-headers (Head, Shoulders, Chest, Cosmetic, ...). Does not add sidebar views."] = "Dans The Armory et les vues de catégorie Armes / Babioles, Armure et Équipement de sets d'objets, regrouper les objets sous des sous-en-têtes d'emplacement d'équipement (Tête, Épaules, Torse, Cosmétique, ...). N'ajoute pas de vues dans la barre latérale."
L["In Vehicle"] = "En véhicule"
L["In raid groups under 10 players, show group 1 as party frames and hide everyone else."] = "Dans les groupes de raid de moins de 10 joueurs, afficher le groupe 1 sous forme de cadres de groupe et masquer tous les autres."
L["In the OneBank and OneWarbank views, split the grid under expansion headers, newest first. Per-tab views are unaffected."] = "Dans les vues OneBank et OneWarbank, diviser la grille sous des en-têtes d'extension, la plus récente en premier. Les vues par onglet ne sont pas affectées."
L["In-combat ally breakdowns are now dungeon-only, cutting Damage Meters memory use in raids where duplicate specs blocked most of them anyway."] = "Les détails des alliés en combat sont désormais réservés aux donjons, ce qui réduit l'utilisation mémoire du Compteur de dégâts en raid, où les spécialisations en double en bloquaient de toute façon la plupart."
L["In-game countdown unavailable in combat; the boss mod pull timer still started."] = "Compte à rebours du jeu indisponible en combat ; le chrono de pull de l'addon de boss a tout de même démarré."
L["Include Combat Timer"] = "Inclure le chrono de combat"
L["Include Global Settings"] = "Inclure les réglages globaux"
L["Include Icon in Bar Border"] = "Inclure l'icône dans la bordure de la barre"
L["Include Overrides"] = "Inclure les remplacements"
L["Include Spell History"] = "Inclure l'historique des sorts"
L["Include Window Skins"] = "Inclure les habillages de fenêtres"
L["Include fonts, custom colours, dark mode and accent colour with this export. Off = only the selected modules' own settings export, keeping the recipient's global look."] = "Inclure les polices, les couleurs personnalisées, le mode sombre et la couleur d'accent dans cet export. Désactivé = seuls les réglages propres aux modules sélectionnés sont exportés, en conservant l'apparence globale du destinataire."
L["Include fonts, custom colours, dark mode, accent colour and UI scale with this export. Off = only the selected modules' own settings export, keeping the recipient's global look."] = "Inclure les polices, les couleurs personnalisées, le mode sombre, la couleur d'accent et l'échelle de l'interface dans cet export. Désactivé = seuls les réglages propres aux modules sélectionnés sont exportés, en conservant l'apparence globale du destinataire."
L["Include your Blizz UI Enhanced settings from the Window Skins and Tooltips, Menus & Popups tabs. These are account-wide: if the importer opts in, they overwrite that player's settings across ALL of their profiles."] = "Inclure vos réglages de l'Interface Blizz améliorée depuis les onglets Habillages de fenêtres et Infobulles, menus et fenêtres surgissantes. Ceux-ci sont valables sur tout le compte : si l'importateur les accepte, ils écrasent les réglages de ce joueur sur TOUS ses profils."
L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Inclure votre configuration complète des remplacements : valeurs de remplacement par spécialisation et conditionnelles, groupes, leurs dispositions personnalisées en mode Déverrouillage, et les remplacements du Gestionnaire d'améliorations. À l'import, cela remplace entièrement les remplacements du destinataire."
L["Include:"] = "Inclure :"
L["Included debuffs show in addition to your Debuff Filter selection (unless it is set to Only Tracked Auras)."] = "Les affaiblissements inclus s'affichent en plus de votre sélection de Filtre des affaiblissements (sauf s'il est réglé sur Auras suivies uniquement)."
L["Indicator "] = "Indicateur "
L["Indicator Color"] = "Couleur de l'indicateur"
L["Indicators added here show on every spec in this group. The Base Icons grid lives in %1$s."] = "Les indicateurs ajoutés ici s'affichent sur chaque spécialisation de ce groupe. La grille Icônes de base se trouve dans %1$s."
L["Inherited from %1$s"] = "Hérité de %1$s"
L["Inherited from %1$s. Edit it there, or use the tile toggle to enable or disable it for this spec."] = "Hérité de %1$s. Modifiez-le là-bas, ou utilisez l'interrupteur de la tuile pour l'activer ou le désactiver pour cette spécialisation."
L["Inherited from %1$s. Editable only there."] = "Hérité de %1$s. Modifiable uniquement là-bas."
