L["Keep Action Bar 1 on its current page when you shapeshift, stealth, or change stance, instead of swapping to that form's bar.\n\nKeybinds follow what the bar shows, so the key always casts the icon you see. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Garder la Barre d'action 1 sur sa page actuelle lorsque vous changez de forme, entrez en camouflage ou changez de posture, au lieu de basculer vers la barre de cette forme.\n\nLes raccourcis suivent ce que la barre affiche, donc la touche lance toujours le sort que vous voyez. Le lancement répété par maintien est désactivé sur la Barre d'action 1 tant que ceci est activé."
L["Keep Action Bar 1 on its current page while skyriding, instead of swapping to the skyriding bar.\n\nYour skyriding abilities live on that bar, so put them on another bar before enabling this. Press-and-hold repeat casting is turned off on Action Bar 1 while this is enabled."] = "Garder la Barre d'action 1 sur sa page actuelle en vol draconique, au lieu de basculer vers la barre de vol draconique.\n\nVos capacités de vol draconique se trouvent sur cette barre, donc placez-les sur une autre barre avant d'activer ceci. Le lancement répété par maintien est désactivé sur la Barre d'action 1 tant que ceci est activé."
L["Keep Keys on Bar Swap (global)"] = "Conserver les touches lors du changement de barre (global)"
L["Keep Mine"] = "Garder les miens"
L["Keep keybind text identical when your action bar swaps -- rogue stealth, druid forms, skyriding. Also covers conditional macros like \"/cast [bonusbar:1] Backstab; Shadow Dance\", where the key would otherwise jump to whichever branch is live.\n\nThe key then only changes when you actually move the ability or rebind it.\n\nOn by default. Applies to every CDM bar at once."] = "Garder le texte de raccourci identique lorsque votre barre d'action change -- camouflage de voleur, formes de druide, vol draconique. Couvre aussi les macros conditionnelles comme « /cast [bonusbar:1] Coup bas; Danse des ombres », où la touche sauterait sinon vers la branche active.\n\nLa touche ne change alors que lorsque vous déplacez réellement la capacité ou la réassignez.\n\nActivé par défaut. S'applique à toutes les barres CDM à la fois."
L["Keep the cast bar visible (sitting empty) when you are not casting, instead of hiding it."] = "Garder la barre d'incantation visible (vide) lorsque vous n'incantez pas, au lieu de la masquer."
L["Keep the item count visible and show 0 instead of hiding it when you have none of the item (e.g. potions, healthstone)."] = "Garder le nombre d'objets visible et afficher 0 au lieu de le masquer lorsque vous n'avez aucun exemplaire de l'objet (ex. : potions, pierre de soins)."
L["Keep the timer visible out of combat, showing the last fight's duration."] = "Garder le chrono visible hors combat, en affichant la durée du dernier combat."
L["Keep this menu open when you let go of its keybind.\nPoint at an entry and press the Select Action key to use it.\nPress the menu's own keybind again, or Escape, to close it."] = "Garder ce menu ouvert lorsque vous relâchez son raccourci.\nPointez une entrée et appuyez sur la touche Sélectionner l'action pour l'utiliser.\nAppuyez à nouveau sur le raccourci propre au menu, ou sur Échap, pour le fermer."
L["Keep your own UI scale. Off = apply the UI scale this profile was made with (changes the scale for all your characters)."] = "Garder votre propre échelle d'interface. Désactivé = appliquer l'échelle d'interface avec laquelle ce profil a été créé (change l'échelle pour tous vos personnages)."
L["Keep"] = "Garder"
L["Keeps Artisan's Consortium Payouts closed while Shard of Dundun is at its maximum, then resumes automatic opening after you spend shards."] = "Garde les gains du Consortium des artisans fermés tant que l'Éclat de Dundun est à son maximum, puis reprend l'ouverture automatique une fois les éclats dépensés." -- TODO: confirmar termo oficial
L["Keeps Blizzard's own buff and debuff display and turns off the built-in Buffs and Debuffs bars. Custom bars keep working."] = "Conserve l'affichage natif des améliorations et affaiblissements de Blizzard et désactive les barres d'Améliorations et d'Affaiblissements intégrées. Les barres personnalisées continuent de fonctionner."
L["Keeps a saved signup note you can copy into the Sign Up dialog with the Copy button."] = "Conserve une note d'inscription enregistrée que vous pouvez copier dans la fenêtre d'inscription avec le bouton Copier."
L["Keeps this bar fully visible while flying on a skyriding mount (or Druid Flight Form), or while it's paged onto the vehicle bar (Action Bar 1 while the player is in a vehicle), regardless of the Visibility mode above."] = "Garde cette barre entièrement visible en volant sur une monture de vol draconique (ou en Forme de vol du druide), ou lorsqu'elle est basculée sur la barre de véhicule (Barre d'action 1 lorsque le joueur est dans un véhicule), quel que soit le mode de Visibilité ci-dessus."
L["Key Already Bound"] = "Touche déjà assignée"
L["Keybind Scope"] = "Portée du raccourci"
L["Keybind, Macro, Charges & Cooldown Text (per bar)"] = "Texte de raccourci, de macro, de charges et de recharge (par barre)"
L["Keybinds set in EllesmereUI's own key fields now fire when two or more modifiers are held (for example Ctrl+Alt+1); re-bind any that never triggered."] = "Les raccourcis définis dans les propres champs de touche d'EllesmereUI se déclenchent désormais lorsque deux modificateurs ou plus sont maintenus (par exemple Ctrl+Alt+1) ; réassignez ceux qui ne se déclenchaient jamais."
L["Keystone Popup Text Size"] = "Taille du texte de la fenêtre surgissante de clé"
