L["Layering of the bar window relative to other UI elements. Raise it if other frames are covering it, or lower it to sit behind them."] = "Superposition de la fenêtre de barre par rapport aux autres éléments d'interface. Augmentez-la si d'autres cadres la recouvrent, ou baissez-la pour qu'elle passe derrière eux."
