L["Left-click a ready Mythic+ teleport in the tooltip to cast it."] = "Clic gauche sur une téléportation Mythique+ prête dans l'infobulle pour l'invoquer."
L["Left-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Clic gauche pour définir un raccourci, puis appuyez sur n'importe quelle touche ou\ncliquez sur n'importe quel bouton de souris pour l'utiliser.\nÉchap annule. Clic droit ici pour le retirer."
