L["Level | Name"] = "Niveau | Nom"
L["Lifts player, target, focus, and boss cast bars above other frames so they are never hidden behind them."] = "Élève les barres d'incantation du joueur, de la cible, du point de mire et des boss au-dessus des autres cadres afin qu'elles ne soient jamais masquées derrière eux."
L["Limit the bars to the selected content and combat states; nothing selected shows them everywhere."] = "Limiter les barres au contenu et aux états de combat sélectionnés ; rien de sélectionné les affiche partout."
L["Line Color"] = "Couleur de ligne"
L["Line Width"] = "Largeur de ligne"
L["Line"] = "Ligne"
L["Liquid Luster is available as a Custom Buff Bar potion preset alongside Light's Potential and Potion of Recklessness."] = "Liquid Luster est disponible comme préréglage de potion pour la Barre d'amélioration personnalisée, aux côtés de Light's Potential et de la Potion d'imprudence." -- TODO: confirmar termo oficial
L["Liquid Luster"] = "Liquid Luster" -- TODO: confirmar termo oficial
L["List item categories in the bank sidebar the way the bags sidebar does -- groups such as The Armory with Weapons and Armor under them. Selecting one filters the grid to that category. Categories that split further list their parts as a third level while selected: Professions by profession, Armor by equipment slot, Trade Goods by material. Spans your character bank and warband together, so a category shows everything you own."] = "Lister les catégories d'objets dans la barre latérale de la banque comme le fait celle des sacs -- des groupes tels que The Armory avec Armes et Armure en dessous. En sélectionner une filtre la grille à cette catégorie. Les catégories qui se subdivisent listent leurs parties comme un troisième niveau une fois sélectionnées : Professions par métier, Armure par emplacement d'équipement, Matériaux par matériau. Couvre à la fois votre banque de personnage et celle du bataillon, si bien qu'une catégorie affiche tout ce que vous possédez."
L["Lists every group member against the consumables a raid expects -- flask, food, augment rune, vantus -- whenever a ready check starts, whoever started it."] = "Compare chaque membre du groupe aux consommables attendus en raid -- fiole, nourriture, rune d'augmentation, vantus -- à chaque lancement d'une vérification de préparation, quel que soit qui l'a lancée."
L["Lists only the people something is actually wrong with, so a thirty-man roster becomes the three names you need to whisper. Someone whose client has not reported yet is not counted as missing."] = "Ne liste que les personnes ayant réellement un problème, transformant ainsi un effectif de trente joueurs en les trois noms à contacter en privé. Quelqu'un dont le client n'a pas encore répondu n'est pas compté comme manquant."
