L["Major catch-ups for German, Korean, Brazilian Portuguese, Simplified Chinese, and Traditional Chinese, plus Bags menus, prompts, and bank headers now translate."] = "Rattrapages majeurs pour l'allemand, le coréen, le portugais brésilien, le chinois simplifié et le chinois traditionnel ; de plus, les menus des sacs, les invites et les en-têtes de banque se traduisent désormais."
