L["Makes partially filled Soul Shards and Essence darker than completed ones."] = "Assombrit les Fragments d'âme et l'Essence partiellement remplis par rapport à ceux complets."
L["Makes the game tooltip follow your mouse cursor instead of showing at its fixed screen position (drag the Tooltip box in Unlock Mode to change that). Use the arrows icon to pick the position relative to the cursor and fine-tune the X/Y offset."] = "Fait suivre l'infobulle du jeu par votre curseur au lieu de l'afficher à sa position fixe à l'écran (faites glisser la boîte Infobulle en mode Déverrouillage pour changer cela). Utilisez l'icône de flèches pour choisir la position relative au curseur et ajuster finement le décalage X/Y."
L["Makes this the override. It replaces the whole Visibility setting, so the conditions below no longer apply while it does. Click it again to remove the override."] = "Fait de ceci le remplacement. Il remplace entièrement le réglage de Visibilité, donc les conditions ci-dessous ne s'appliquent plus tant qu'il est actif. Cliquez à nouveau dessus pour retirer le remplacement."
