L["Not available in Dark Mode. Dark Mode colors can be adjusted in Global Settings -> Fonts & Colors."] = "Non disponible en mode sombre. Les couleurs du mode sombre peuvent être ajustées dans Réglages globaux -> Polices et couleurs."
L["Not available while a legacy visibility value is selected. Pick Never or Always first."] = "Non disponible tant qu'une ancienne valeur de visibilité est sélectionnée. Choisissez d'abord Jamais ou Toujours."
L["Not available while a spell on this bar uses a Cooldown State Shift Icons setting"] = "Non disponible tant qu'un sort de cette barre utilise un réglage Décaler les icônes selon l'état de recharge"
