L["Not in a guild"] = "Pas dans une guilde"
L["Not overridable"] = "Non remplaçable"
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies. Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "Non remplaçable. Ces conditions sont partagées et ne peuvent être modifiées que lorsqu'aucun remplacement n'est en cours d'édition. Un remplacement remplace entièrement le réglage de Visibilité -- Jamais, Toujours ou Survol -- et ignore tout ce qui est défini ici tant qu'il s'applique. Survol est verrouillé ici aussi pour cet élément : son mécanisme de survol suit le réglage partagé, donc un remplacement ne pourrait que le laisser affiché."
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies."] = "Non remplaçable. Ces conditions sont partagées et ne peuvent être modifiées que lorsqu'aucun remplacement n'est en cours d'édition. Un remplacement remplace entièrement le réglage de Visibilité -- Jamais, Toujours ou Survol -- et ignore tout ce qui est défini ici tant qu'il s'applique."
L["Not used in Icon display mode"] = "Non utilisé en mode d'affichage Icône"
L["Nothing Extra"] = "Rien de plus"
L["Nothing to add"] = "Rien à ajouter"
L["November"] = "Novembre"
L["Nudge the bubble up or down from where the game put it. Zero sits exactly on Blizzard's own position, which is already over the speaker's head."] = "Ajuster légèrement la bulle vers le haut ou le bas par rapport à l'endroit où le jeu l'a placée. Zéro correspond exactement à la position de Blizzard, déjà au-dessus de la tête du locuteur."
L["OH"] = "OH" -- TODO: confirmar termo oficial
L["OVERRIDES WARNING"] = "AVERTISSEMENT DE REMPLACEMENT"
L["October"] = "Octobre"
L["Off (default): the cast bar fades with real transparency, matching the whole-frame Out of Range Alpha (best if you're colour-matching the frame and cast bar). On: the old behavior -- a black overlay dims the bar instead of fading it, which can't discolor a shielded/uninterruptible cast's tint but won't visually match the frame's fade."] = "Désactivé (par défaut) : la barre d'incantation s'estompe avec une vraie transparence, correspondant à l'Alpha hors de portée du cadre entier (idéal si vous faites correspondre les couleurs du cadre et de la barre d'incantation). Activé : l'ancien comportement -- une superposition noire assombrit la barre au lieu de l'estomper, ce qui ne peut pas altérer la teinte d'une incantation protégée/ininterruptible mais ne correspondra pas visuellement au fondu du cadre."
L["Offensive CDs"] = "Recharges offensives"
L["Offsets the base row's icon size in pixels from Icon Scale. The second row keeps the base size."] = "Décale en pixels la taille d'icône de la rangée de base par rapport à l'Échelle d'icône. La deuxième rangée garde la taille de base."
L["Offsets the second row's icon size in pixels from Icon Scale. The base row keeps the base size."] = "Décale en pixels la taille d'icône de la deuxième rangée par rapport à l'Échelle d'icône. La rangée de base garde la taille de base."
L["On Cooldown"] = "En recharge"
L["On My Way"] = "J'arrive"
L["Once the lockout expires, show a Ready label on the icon in place of the countdown. The visibility rule above still applies."] = "Une fois le verrouillage expiré, afficher une étiquette Prêt sur l'icône à la place du compte à rebours. La règle de visibilité ci-dessus s'applique toujours."
L["One Button Assist Icon"] = "Icône d'assistance à bouton unique" -- TODO: confirmar termo oficial
L["One Window combines everything into a single element; the Only choices show just that part."] = "Une fenêtre combine tout en un seul élément ; les choix Uniquement n'affichent que cette partie."
L["One Window"] = "Une fenêtre"
L["One video walks you through the most important changes in 12.1 and how to get the most out of EllesmereUI under them. Copy the link and give it a watch before you dive in."] = "Une vidéo vous guide à travers les changements les plus importants de la 12.1 et la façon de tirer le meilleur parti d'EllesmereUI avec eux. Copiez le lien et regardez-la avant de vous lancer."
L["One-time copy of the Raid Frames Buff Manager filters into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "Copie ponctuelle des filtres du Gestionnaire d'améliorations des cadres de raid vers ces filtres. Les filtres de même nom sont ÉCRASÉS ; les deux listes restent séparées par la suite."
L["One-time copy of your Player Aura Bars filter setups into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "Copie ponctuelle de vos configurations de filtres des Barres d'aura du joueur vers ces filtres. Les filtres de même nom sont ÉCRASÉS ; les deux listes restent séparées par la suite."
L["Only Dispellable by You"] = "Dissipable par vous uniquement"
L["Only Dispellable"] = "Dissipable uniquement"
L["Only Group & Pull"] = "Groupe et pull uniquement"
L["Only Markers"] = "Repères uniquement"
L["Only Open MenuOut of Combat."] = "Ouvrir le menu uniquement hors combat."
L["Only Show Numbers"] = "Afficher uniquement les nombres"
L["Only Show in Housing"] = "Afficher uniquement dans le logement"
L["Only Show when Mounted"] = "Afficher uniquement lorsque monté"
L["Only Tracked Auras"] = "Auras suivies uniquement"
L["Only With Multiple Boss Frames"] = "Uniquement avec plusieurs cadres de boss"
L["Only applies when Name > Target is selected."] = "S'applique uniquement lorsque Nom > Cible est sélectionné."
L["Only applies when the selected text includes a Name."] = "S'applique uniquement lorsque le texte sélectionné inclut un Nom."
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "Disponible uniquement avec la direction « Depuis » -- elle met en surbrillance les jalons au niveau ou au-dessus du seuil."
L["Only glow once the buff's stack count matches the comparison set via the gear."] = "Ne briller que lorsque le nombre de cumuls de l'amélioration correspond à la comparaison définie via l'engrenage."
L["Only in Combat"] = "Uniquement en combat"
L["Only play alerts while in combat."] = "Ne jouer les alertes qu'en combat."
L["Only recolor the fill when more than one boss frame is active at once (a multi-boss phase). With a single boss frame up, it keeps its normal color even while targeted. Off (default) recolors regardless of how many boss frames are active."] = "Ne recolorer le remplissage que lorsque plusieurs cadres de boss sont actifs à la fois (une phase multi-boss). Avec un seul cadre de boss actif, il garde sa couleur normale même lorsqu'il est ciblé. Désactivé (par défaut) recolore quel que soit le nombre de cadres de boss actifs."
L["Only show buffs cast by you."] = "N'afficher que les améliorations lancées par vous."
L["Only show debuffs that have a duration, excluding permanent ones. Combines with the filters below; checked alone it shows every timed debuff."] = "N'afficher que les affaiblissements ayant une durée, à l'exclusion des permanents. Se combine avec les filtres ci-dessous ; coché seul, il affiche tout affaiblissement chronométré."
-- == frFR translation batch 3 (2026-09-14) ==
L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "N'afficher que les affaiblissements dont la durée totale ne dépasse pas ce nombre de secondes. Se combine avec les filtres ; Illimité n'applique aucune limite."
L["Only show the alert while in combat."] = "N'afficher l'alerte qu'en combat."
L["Only show these buffs when you cast them."] = "N'afficher ces améliorations que lorsque vous les lancez."
L["Only show this bar while the tracked buff/cooldown is active. Unchecked keeps an empty bar on screen at all times."] = "N'afficher cette barre que lorsque l'amélioration/la recharge suivie est active. Décoché garde une barre vide à l'écran en permanence."
L["Only shows the GCD circle while you are in combat."] = "N'affiche le cercle de GCD que lorsque vous êtes en combat."
L["Only shows the cast bar circle while you are in combat."] = "N'affiche le cercle de la barre d'incantation que lorsque vous êtes en combat."
L["Only shows the cursor circle while you are in combat."] = "N'affiche le cercle du curseur que lorsque vous êtes en combat."
L["Only while AIRBORNE on a glide-capable mount or flight form. For the mount itself, ground included, use Skyriding Mount."] = "Uniquement EN VOL sur une monture capable de planer ou une forme de vol. Pour la monture elle-même, sol inclus, utilisez Monture de vol draconique."
L["Only works outside of Instances"] = "Ne fonctionne qu'en dehors des instances"
L["Opacity of the Button Overlay tint."] = "Opacité de la teinte de Superposition de bouton."
L["Opacity of the background overlay. 0 removes it entirely; the 9.0.7 default is 62."] = "Opacité de la superposition d'arrière-plan. 0 la retire entièrement ; la valeur par défaut de la 9.0.7 est 62."
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "Opacité du remplissage de la barre ; en dessous de 100, le monde apparaît à travers le remplissage au lieu de l'arrière-plan."
L["Opacity of the cast bar fill; below 100 the world shows through the fill instead of the background."] = "Opacité du remplissage de la barre d'incantation ; en dessous de 100, le monde apparaît à travers le remplissage au lieu de l'arrière-plan."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Opacité du remplissage de ressource ; en dessous de 100, le monde apparaît à travers le remplissage au lieu de l'arrière-plan."
L["Opacity used for enemy nameplates outside the selected attack range."] = "Opacité utilisée pour les barres d'info ennemies hors de la portée d'attaque sélectionnée."
L["Open At"] = "Ouvrir à"
L["Open Character Sheet"] = "Ouvrir la feuille de personnage"
L["Open Edit Mode"] = "Ouvrir le mode Édition"
L["Open Talents"] = "Ouvrir les talents"
L["Open World"] = "Monde ouvert"
L["Opening Myslot again forces every bar visible, including bars using Match Any, Hide with Target or the mounted visibility conditions."] = "Rouvrir Myslot force l'affichage de toutes les barres, y compris celles utilisant Correspondre à n'importe laquelle, Masquer avec cible ou les conditions de visibilité monté."
L["Opens"] = "Ouvre"
L["Order"] = "Ordre"
L["Organizes your friends list into collapsible custom groups."] = "Organise votre liste d'amis en groupes personnalisés réductibles."
L["Others are missing my buff"] = "D'autres n'ont pas mon amélioration"
L["Others are missing my buff: remind when a groupmate is missing a buff you can cast.\nI am missing others' buffs: remind when you are missing a buff a groupmate could give you (only shown when someone who can cast it is present). Off by default."] = "D'autres n'ont pas mon amélioration : rappeler lorsqu'un coéquipier n'a pas une amélioration que vous pouvez lancer.\nIl me manque les améliorations des autres : rappeler lorsqu'il vous manque une amélioration qu'un coéquipier pourrait vous donner (affiché uniquement lorsque quelqu'un capable de la lancer est présent). Désactivé par défaut."
L["Out of Combat Color"] = "Couleur hors combat"
L["Out of Combat Settings"] = "Réglages hors combat"
L["Out of Range Opacity"] = "Opacité hors de portée"
L["Out-of-range coloring now tracks the spell actually on the icon while a proc or talent override replaces it, instead of the base spell's range."] = "La coloration hors de portée suit désormais le sort réellement affiché sur l'icône lorsqu'un proc ou un remplacement de talent le remplace, au lieu de la portée du sort de base."
L["Out-of-range frames darken instead of fading transparent, matching Blizzard's default party/raid frame look. Uses the same Out of Range Alpha % as brightness: 100% = no visible difference in/out of range, 10% = out-of-range frames drop to 10% brightness."] = "Les cadres hors de portée s'assombrissent au lieu de s'estomper en transparence, comme l'apparence par défaut des cadres de groupe/raid de Blizzard. Utilise le même % d'Alpha hors de portée comme luminosité : 100 % = aucune différence visible dans/hors de portée, 10 % = les cadres hors de portée tombent à 10 % de luminosité."
L["Outfit"] = "Tenue"
L["Outfits"] = "Tenues"
L["Outline style override for all %1$s text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de %1$s. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Action Bars text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Barres d'action. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all AuraBuff Reminders text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Rappels d'auras. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Bags text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Sacs. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Blizz UI Enhanced text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte d'Interface Blizz améliorée. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Chat text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Chat. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Cooldown Manager text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Gestionnaire de recharge. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Damage Meters text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Compteur de dégâts. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all DataBars text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de DataBars. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Friends List text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Liste d'amis. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Minimap text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Minicarte. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Mythic+ Tools text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte d'Outils Mythique+. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Nameplates text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Barres d'info. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Quality of Life text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Confort de jeu. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Quest Tracker text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Suivi de quêtes. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Quickdraw text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Quickdraw. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Resource & Cast Bars text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Barres de ressource et d'incantation. Contour global EUI suit le réglage Mode de contour global ci-dessus."
L["Outline style override for all Unit Frames text. EUI Global Outline follows the global Outline Mode setting above."] = "Remplacement du style de contour pour tout le texte de Cadres d'unité. Contour global EUI suit le réglage Mode de contour global ci-dessus."
