L["Overrides"] = "Remplacements"
L["Overshield is the part of an absorb exceeding your empty health. Always backfills it over current health from the shield's edge; From Left grows it from the opposite end of the bar; Never hides it."] = "Le surbouclier est la part d'une absorption dépassant votre vie vide. Toujours le remplit par-dessus la vie actuelle depuis le bord du bouclier ; Depuis la gauche le fait croître depuis l'extrémité opposée de la barre ; Jamais le masque."
