L["Pick the sound to be played from the list. Default is Robot Blip."] = "Choisissez le son à jouer dans la liste. Par défaut : Robot Blip."
L["Pick which content the class-special reminders (poisons/rites/imbues/shields) appear in.\nRested areas (cities and inns) always stay hidden."] = "Choisissez dans quel contenu les rappels spécifiques à la classe (poisons/rites/enchantements temporaires/boucliers) apparaissent.\nLes zones de repos (villes et auberges) restent toujours masquées."
L["Pick which content these Warlock reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Choisissez dans quel contenu ces rappels de Démoniste apparaissent.\nLes zones de repos (villes et auberges) restent toujours masquées."
L["Pick which content these aura reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Choisissez dans quel contenu ces rappels d'aura apparaissent.\nLes zones de repos (villes et auberges) restent toujours masquées."
L["Pick which content these consumable reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Choisissez dans quel contenu ces rappels de consommables apparaissent.\nLes zones de repos (villes et auberges) restent toujours masquées."
L["Pick which content this section's reminders appear in.\nRested areas (cities and inns) always stay hidden."] = "Choisissez dans quel contenu les rappels de cette section apparaissent.\nLes zones de repos (villes et auberges) restent toujours masquées."
L["Picking a raid marker from the fallback unit menu (shown for group members whose data has not streamed in) is now greyed out like the other unavailable actions there instead of throwing a blocked-action error."] = "Choisir un repère de raid depuis le menu d'unité de repli (affiché pour les membres du groupe dont les données ne sont pas encore arrivées) est désormais grisé comme les autres actions indisponibles à cet endroit, au lieu de générer une erreur d'action bloquée."
