L["Racial spells assigned to a custom bar stay there through spec changes and relogs, and racials untracked in Blizzard's Cooldown Manager display again."] = "Les sorts raciaux assignés à une barre personnalisée y restent lors des changements de spécialisation et des reconnexions, et les sorts raciaux non suivis s'affichent à nouveau dans le Gestionnaire de recharge de Blizzard."
