L["Raid frame absorbs and health ticks, nameplate health updates, tracking bar pairing and unit frame absorbs all do less work per event"] = "Les absorptions et ticks de vie des cadres de raid, les mises à jour de vie des barres d'info, l'association des barres de suivi et les absorptions des cadres d'unité effectuent tous moins de travail par événement"
L["Raid frame buffs and debuffs are rebuilt for Midnight's new aura engine. Track whole spell categories with filters, then give each one its own display."] = "Les améliorations et affaiblissements des cadres de raid sont reconstruits pour le nouveau moteur d'auras de Midnight. Suivez des catégories entières de sorts avec des filtres, puis donnez à chacune son propre affichage."
L["Raid only. Left-click the Durability column's header icon anytime to use the Auto-Hammer (item 132514) -- no one needs to be low first. When a player's Durability reading drops to 25% or below, their name blinks as a heads-up, but that's just a warning, not a requirement to click."] = "Raid uniquement. Clic gauche sur l'icône d'en-tête de la colonne Durabilité à tout moment pour utiliser le Marteau automatique (objet 132514) -- personne n'a besoin d'être bas en premier. Lorsque la durabilité d'un joueur descend à 25 % ou moins, son nom clignote comme avertissement, mais ce n'est qu'un avertissement, pas une obligation de cliquer." -- TODO: confirmar termo oficial
L["Raid only. Left-click the Food column's header icon anytime to drop a feast at your own feet: Feast of Knowledge, falling back to Amani Cornucopia and then Loa's Gathering depending on what's in your bags. Disarmed while you already have a Well Fed buff active, so there's no wasted click."] = "Raid uniquement. Clic gauche sur l'icône d'en-tête de la colonne Nourriture à tout moment pour déposer un festin à vos pieds : Festin de la connaissance, avec repli sur Corne d'abondance amani puis Rassemblement des loas selon ce qu'il y a dans vos sacs. Désarmé tant que vous avez déjà une amélioration Bien nourri active, pour éviter un clic inutile." -- TODO: confirmar termo oficial
L["Raises or lowers the tracker's frame strata. Increase it if other UI elements are drawing on top of the tracker; decrease it if the tracker is drawing on top of something it shouldn't."] = "Augmente ou diminue la strate de cadre du suivi. Augmentez-la si d'autres éléments d'interface se dessinent par-dessus le suivi ; diminuez-la si le suivi se dessine par-dessus quelque chose qu'il ne devrait pas."
