L["Recolor the bar while you have a buff. The first active buff in the list wins, so order = priority. Overrides threshold coloring while active.\nYou must be tracking the buff in Blizzard CDM, added to EUI CDM, and this only works with CDM trackable buffs."] = "Recolorer la barre tant que vous avez une amélioration. La première amélioration active de la liste l'emporte, donc l'ordre = priorité. Remplace la coloration par seuil tant qu'elle est active.\nVous devez suivre l'amélioration dans le CDM de Blizzard, l'ajouter au CDM EUI, et cela ne fonctionne qu'avec les améliorations suivables par le CDM."
L["Recolors this boss frame's health bar fill with the color chosen below while it is your current target. Boss frames only."] = "Recolore le remplissage de la barre de vie de ce cadre de boss avec la couleur choisie ci-dessous tant qu'il est votre cible actuelle. Cadres de boss uniquement."
L["Rectangular"] = "Rectangulaire"
L["Refresh using tooltip scan data.\n For exact costs, use |cffffffff'Update at Upgrader'|r\n while at an Item Upgrade NPC."] = "Actualiser à partir des données scannées de l'infobulle.\n Pour des coûts exacts, utilisez |cffffffff'Mettre à jour chez l'amélioreur'|r\n auprès d'un PNJ d'amélioration d'objet." -- TODO: confirmar termo oficial
L["Refresh using tooltip scan data.\n"] = "Actualiser à partir des données scannées de l'infobulle.\n"
L["Regular Import"] = "Import standard"
L["Reloading the UI while in combat no longer causes script-ran-too-long errors and half-loaded modules."] = "Recharger l'interface en combat ne cause plus d'erreurs de script trop long ni de modules à moitié chargés."
L["Reminder Sound"] = "Son de rappel"
L["Reminder names, item counts and the mana warning"] = "Noms de rappel, nombres d'objets et avertissement de mana"
L["Reminder threshold while you are in a dungeon before a Mythic+ key starts (Mythic 0 / keystone lobby). Set it high enough that you top up buffs and food before pulling, so you begin the key with enough duration to last it.\n0 = only when fully expired.\nIgnored once the key is active or you are in combat (then only when the buff is fully gone)."] = "Seuil de rappel pendant que vous êtes dans un donjon avant le début d'une clé Mythique+ (Mythique 0 / hall de la clé). Réglez-le assez haut pour que vous complétiez vos améliorations et votre nourriture avant de pull, afin de commencer la clé avec assez de durée pour la tenir.\n0 = uniquement lorsque totalement expiré.\nIgnoré une fois la clé active ou en combat (alors uniquement lorsque l'amélioration a totalement disparu)."
L["Remove 10 Man size"] = "Retirer la taille à 10 joueurs"
