L["Remove from Group"] = "Retirer du groupe"
L["Remove the Anchor To position"] = "Retirer la position Ancrer à"
L["Remove the stranded '%s' override for %s? The spec returns to the shared default."] = "Retirer le remplacement orphelin « %s » pour %s ? La spécialisation revient au réglage par défaut partagé."
L["Removes the block from the bar inside dungeons and raids, where there are no player coordinates."] = "Retire le bloc de la barre à l'intérieur des donjons et des raids, où il n'y a pas de coordonnées de joueur."
-- == frFR translation batch 4 (2026-09-14) ==
L["Removes the color codes the plugin writes into its own text, so this block's Text Color applies. Off keeps the plugin's colors."] = "Retire les codes couleur que le module complémentaire écrit dans son propre texte, afin que la Couleur de texte de ce bloc s'applique. Désactivé conserve les couleurs du module complémentaire."
L["Removing "] = "Suppression de "
L["Removing third-party addon skins requires a UI reload."] = "Retirer les habillages d'addons tiers nécessite un rechargement de l'interface."
L["Rename Action Menu"] = "Renommer le menu d'actions"
L["Rename Filter"] = "Renommer le filtre"
L["Rename Friend Group"] = "Renommer le groupe d'amis"
L["Rename Indicator"] = "Renommer l'indicateur"
L["Repair"] = "Réparer"
L["Replace with Buff"] = "Remplacer par une amélioration"
L["Replaces Blizzard's default buff and debuff display with fully customizable bars."] = "Remplace l'affichage par défaut des améliorations et affaiblissements de Blizzard par des barres entièrement personnalisables."
L["Replaces Buff Glow: the icon glows when its stack count matches the comparison below, using this spell's Buff Glow style (Modern WoW Glow if none is set)."] = "Remplace Lueur d'amélioration : l'icône brille lorsque son nombre de cumuls correspond à la comparaison ci-dessous, en utilisant le style de Lueur d'amélioration de ce sort (Lueur moderne de WoW si aucun n'est défini)."
L["Replaces the spendable amount with the crests you have earned this season, out of the season cap. The tooltip lists both numbers side by side."] = "Remplace le montant dépensable par les écus gagnés cette saison, sur le plafond de la saison. L'infobulle liste les deux nombres côte à côte."
L["Reputation Bar Text Size"] = "Taille du texte de la barre de réputation"
L["Reputation Bar Texture"] = "Texture de la barre de réputation"
L["Requires Bar display mode"] = "Nécessite le mode d'affichage Barre"
L["Requires Max Icons to be above 0"] = "Nécessite que Icônes max soit supérieur à 0"
L["Requires Sync Style with Chat Panel disabled"] = "Nécessite que Synchroniser le style avec le panneau de discussion soit désactivé"
L["Requires a Debuff Display"] = "Nécessite un Affichage d'affaiblissement"
L["Requires a client with gliding events."] = "Nécessite un client avec des événements de vol plané."
L["Requires the Icon display mode"] = "Nécessite le mode d'affichage Icône"
L["Rescue tool for a profile built inside an override: the selected group's settings and layouts become this profile's own baseline, then ALL spec override groups are deleted. Conditional overrides are not affected."] = "Outil de secours pour un profil construit à l'intérieur d'un remplacement : les réglages et dispositions du groupe sélectionné deviennent la base propre de ce profil, puis TOUS les groupes de remplacement par spécialisation sont supprimés. Les remplacements conditionnels ne sont pas affectés."
L["Reset Button"] = "Bouton de réinitialisation"
L["Reset Position"] = "Réinitialiser la position"
L["Reset Zoom"] = "Réinitialiser le zoom"
L["Reset failed - there are still players inside the instance."] = "Échec de la réinitialisation - il reste des joueurs à l'intérieur de l'instance."
L["Resize Blizzard's default game text from 75-125%"] = "Redimensionner le texte de jeu par défaut de Blizzard de 75 à 125 %"
L["Reskin Extra Action Buttons"] = "Réhabiller les boutons d'action supplémentaires"
L["Reskin Widget Bars"] = "Réhabiller les barres de widgets"
L["Reskins the dungeon and battleground queue accept popups with the EUI dark style, and adds an accept countdown timer bar to the dungeon one."] = "Réhabille les fenêtres surgissantes d'acceptation de file d'attente de donjon et de champ de bataille avec le style sombre EUI, et ajoute une barre de compte à rebours d'acceptation à celle du donjon."
L["Resource, cast and GCD bar textures"] = "Textures des barres de ressource, d'incantation et de GCD"
L["Resting"] = "Repos"
L["Restyle Blizzard's chat bubbles for the channels you pick beside this.\n\nEllesmereUI keeps Blizzard's bubbles switched on and draws over them, so every bubble stays where the game put it, including the one over your own head. Nameplates are not involved and do not need to be visible.\n\nChannels you leave off keep Blizzard's own look."] = "Réhabiller les bulles de discussion de Blizzard pour les canaux que vous choisissez à côté de ceci.\n\nEllesmereUI garde les bulles de Blizzard activées et dessine par-dessus, afin que chaque bulle reste là où le jeu l'a placée, y compris celle au-dessus de votre propre tête. Les barres d'info ne sont pas concernées et n'ont pas besoin d'être visibles.\n\nLes canaux que vous laissez décochés conservent l'apparence propre de Blizzard."
L["Restyles Blizzard's on-screen progress bars (event objectives, nameplate counters) to the EUI look. Requires reload to apply.\n\nThese bars are drawn over rather than modified, so if the game ever reports their contents as protected the original bar is shown instead.\n\nUse the cog to set a minimum size, so bars on shrunken nameplates stay readable."] = "Réhabille les barres de progression à l'écran de Blizzard (objectifs d'événement, compteurs de barre d'info) à l'apparence EUI. Nécessite un rechargement pour s'appliquer.\n\nCes barres sont dessinées par-dessus plutôt que modifiées, donc si le jeu signale un jour leur contenu comme protégé, la barre originale s'affiche à la place.\n\nUtilisez l'engrenage pour définir une taille minimale, afin que les barres sur des barres d'info réduites restent lisibles."
L["Retired"] = "Retiré"
L["Reveal on hover only. Combines with the conditions below: hover-reveals while they all pass, stays hidden while any fails."] = "Révéler uniquement au survol. Se combine avec les conditions ci-dessous : révèle au survol tant qu'elles sont toutes remplies, reste masqué si l'une d'elles échoue."
L["Reverse"] = "Inverser"
L["Right Text Class Color"] = "Couleur de classe du texte droit"
L["Right of Window"] = "À droite de la fenêtre"
L["Right-Click to Cancel"] = "Clic droit pour annuler"
L["Right-Click to set custom alert text."] = "Clic droit pour définir un texte d'alerte personnalisé."
L["Right-click a tab in the bank sidebar to rename it or set its deposit filters."] = "Clic droit sur un onglet de la barre latérale de la banque pour le renommer ou définir ses filtres de dépôt."
L["Right-clicking a buff icon cancels the buff. Turning this off makes the bar's icons click-through; tooltips still follow the Show Tooltips setting."] = "Un clic droit sur une icône d'amélioration annule l'amélioration. Désactiver ceci rend les icônes de la barre transparentes aux clics ; les infobulles suivent toujours le réglage Afficher les infobulles."
L["Right-clicking a raid member who is in a different zone now opens the player menu instead of the pet menu."] = "Un clic droit sur un membre du raid se trouvant dans une zone différente ouvre désormais le menu du joueur au lieu du menu du familier."
