L["Saved between reloads and relogs. In Group Finder, choose Copy, press Ctrl+C, then Ctrl+V."] = "Conservé entre les rechargements et les reconnexions. Dans l'Outil de recherche de groupe, choisissez Copier, appuyez sur Ctrl+C, puis Ctrl+V."
