L["Scales the loot and gold toasts."] = "Redimensionne les notifications de butin et d'or."
L["Scales the size of Blizzard's default game text (menus, tooltips, quest log, and more). Requires a UI reload."] = "Redimensionne la taille du texte de jeu par défaut de Blizzard (menus, infobulles, journal de quêtes, et plus). Nécessite un rechargement de l'interface."
L["Scales the text size of Blizzard tooltips."] = "Redimensionne la taille du texte des infobulles de Blizzard."
L["Scales the tracking blips drawn on the map (herbs, ore, quest dots). The map itself keeps its size; other minimap elements are unaffected."] = "Redimensionne les repères de suivi dessinés sur la carte (herbes, minerai, points de quête). La carte elle-même garde sa taille ; les autres éléments de la minicarte ne sont pas affectés."
L["Scan all equipped gear costs at the Item Upgrade NPC.\n Scans each slot one at a time — this can take up to 10 seconds.\n Requires the Item Upgrade window to be open."] = "Scanner tous les coûts d'équipement porté auprès du PNJ d'amélioration d'objet.\n Scanne chaque emplacement un par un — cela peut prendre jusqu'à 10 secondes.\n Nécessite que la fenêtre d'amélioration d'objet soit ouverte."
L["Scan all equipped gear costs at the Item Upgrade NPC.\n"] = "Scanner tous les coûts d'équipement porté auprès du PNJ d'amélioration d'objet.\n"
L["Screen layer the bar renders on; changing a grouped bar changes its whole group."] = "Couche d'écran sur laquelle la barre s'affiche ; modifier une barre groupée modifie tout son groupe."
L["Screen layer this bar and its icons render on."] = "Couche d'écran sur laquelle cette barre et ses icônes s'affichent."
L["Screen layer this bar renders on. Raise it to draw over other frames, lower it to sit behind them."] = "Couche d'écran sur laquelle cette barre s'affiche. Augmentez-la pour dessiner par-dessus d'autres cadres, diminuez-la pour qu'elle passe derrière eux."
