L["Seconds after which history icons fade out. The timer pauses during combat. 0 = never."] = "Nombre de secondes après lequel les icônes d'historique s'estompent. Le minuteur se met en pause pendant le combat. 0 = jamais."
L["Seconds counts the time down in tenths. GCD Count counts whole global cooldowns instead, so inside Arcane Soul it reads as the number of Arcane Barrages that still fit, ending on a coloured LAST. Seconds + GCD in Soul mixes the two: tenths counting down to the window, Barrage count once it opens."] = "Secondes décompte le temps en dixièmes. Nombre de GCD compte plutôt des recharges globales entières, donc à l'intérieur de l'Âme arcanique, il indique le nombre de Rafales arcaniques qui tiennent encore, se terminant sur un DERNIER coloré. Secondes + GCD dans l'Âme mélange les deux : dixièmes décomptant jusqu'à la fenêtre, nombre de Rafales une fois ouverte." -- TODO: confirmar termo oficial
L["Seconds of Arcane Surge left when the countdown appears. Always in seconds, including in GCD mode."] = "Secondes de Poussée arcanique restantes lorsque le compte à rebours apparaît. Toujours en secondes, y compris en mode GCD." -- TODO: confirmar termo oficial
L["Seconds"] = "Secondes"
