L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Définit la police des noms qui flottent au-dessus des joueurs, des PNJ et des ennemis dans le monde.\n\nSéparé de la Police globale - modifier ceci n'affecte pas le reste de l'interface, et la Police globale ne l'affecte pas.\n\nPar défaut de Blizzard laisse le texte de nom totalement intact.\n\n|cffff4d4dNécessite une reconnexion ou un redémarrage de WoW pour prendre effet.|r"
L["Settings Overrides are the most powerful system in EllesmereUI, and the deepest. A few minutes with this video will save you hours of working it out on your own."] = "Les Remplacements de réglages sont le système le plus puissant d'EllesmereUI, et le plus complexe. Quelques minutes avec cette vidéo vous épargneront des heures à le comprendre seul."
