L["Show copies of the same item that sit in separate bag slots as one icon with their counts added together. Turn this off to keep every slot separate, for example when you deliberately split stacks. Merging is always paused while the mail, trade, auction house, bank or guild bank window is open, since those take one bag slot at a time."] = "Afficher les copies d'un même objet situées dans des emplacements de sac séparés comme une seule icône dont les nombres sont additionnés. Désactivez ceci pour garder chaque emplacement séparé, par exemple lorsque vous divisez délibérément des piles. La fusion est toujours suspendue tant que la fenêtre de courrier, d'échange, d'hôtel des ventes, de banque ou de banque de guilde est ouverte, car celles-ci occupent un emplacement de sac à la fois."
L["Show every buff that has a duration (hides permanent buffs). Use the Hide lane below to remove specific filters."] = "Afficher toutes les améliorations ayant une durée (masque les améliorations permanentes). Utilisez la voie Masquer ci-dessous pour retirer des filtres spécifiques."
L["Show every buff that has a duration (hides permanent buffs). While this is on, checked filters below are hidden instead of added."] = "Afficher toutes les améliorations ayant une durée (masque les améliorations permanentes). Tant que ceci est activé, les filtres cochés ci-dessous sont masqués au lieu d'être ajoutés."
L["Show every buff. Use the Hide lane below to remove specific filters."] = "Afficher toutes les améliorations. Utilisez la voie Masquer ci-dessous pour retirer des filtres spécifiques."
L["Show every buff. While this is on, checked filters below are hidden from the bar instead of added."] = "Afficher toutes les améliorations. Tant que ceci est activé, les filtres cochés ci-dessous sont masqués de la barre au lieu d'être ajoutés."
L["Show every buff. While this is on, checked filters below are hidden from the frame instead of added."] = "Afficher toutes les améliorations. Tant que ceci est activé, les filtres cochés ci-dessous sont masqués du cadre au lieu d'être ajoutés."
L["Show every debuff in the base grid. The Base Filters dropdown is ignored while this is on."] = "Afficher tous les affaiblissements dans la grille de base. Le menu déroulant Filtres de base est ignoré tant que ceci est activé."
L["Show every debuff in this indicator. Use the Hide lane below to remove specific filters."] = "Afficher tous les affaiblissements dans cet indicateur. Utilisez la voie Masquer ci-dessous pour retirer des filtres spécifiques."
L["Show every debuff. Use the Hide lane below to remove specific filters."] = "Afficher tous les affaiblissements. Utilisez la voie Masquer ci-dessous pour retirer des filtres spécifiques."
L["Show every debuff. While this is on, checked filters below are hidden from the bar instead of added."] = "Afficher tous les affaiblissements. Tant que ceci est activé, les filtres cochés ci-dessous sont masqués de la barre au lieu d'être ajoutés."
L["Show every debuff. While this is on, checked filters below are hidden from the frame instead of added."] = "Afficher tous les affaiblissements. Tant que ceci est activé, les filtres cochés ci-dessous sont masqués du cadre au lieu d'être ajoutés."
L["Show every debuff. While this is on, checked filters below are hidden from the grid instead of added."] = "Afficher tous les affaiblissements. Tant que ceci est activé, les filtres cochés ci-dessous sont masqués de la grille au lieu d'être ajoutés."
L["Show how many of the consumable you have left in your bags."] = "Afficher combien de ce consommable il vous reste dans vos sacs."
L["Show in Instances"] = "Afficher en instance"
L["Show item or spell tooltips when hovering reminder icons."] = "Afficher les infobulles d'objet ou de sort au survol des icônes de rappel."
L["Show on Ready Check"] = "Afficher lors de la vérification de préparation"
L["Show one plain cast bar per enemy nameplate that is casting, gathered into a single movable group with the spell name, its target, and the cast timer."] = "Afficher une simple barre d'incantation par barre d'info ennemie en train d'incanter, regroupées dans un seul groupe déplaçable avec le nom du sort, sa cible, et le minuteur d'incantation."
L["Show one sub-category per equipment set (named after the set) nested under Item Set Gear. Gear in several sets goes to the first one."] = "Afficher une sous-catégorie par set d'équipement (nommée d'après le set) imbriquée sous Équipement de sets d'objets. L'équipement présent dans plusieurs sets va dans le premier."
L["Show reminders when remaining buff time is below this many minutes.\n0 = only when fully expired.\nIgnored in combat and during Mythic+ keys (then only when the buff is gone)."] = "Afficher les rappels lorsque le temps restant de l'amélioration est inférieur à ce nombre de minutes.\n0 = uniquement lorsque totalement expirée.\nIgnoré en combat et pendant les clés Mythique+ (alors uniquement lorsque l'amélioration a disparu)."
L["Show rune count in center and remove recharging text/animation"] = "Afficher le nombre de runes au centre et retirer le texte/l'animation de rechargement"
L["Show special reminders while out in the open world.\nReminders are always hidden in rested areas (cities and inns)."] = "Afficher des rappels spéciaux en monde ouvert.\nLes rappels sont toujours masqués dans les zones de repos (villes et auberges)."
L["Show the Mythic+ teleport section in the tooltip. Ready rows are click-to-teleport."] = "Afficher la section de téléportation Mythique+ dans l'infobulle. Les lignes prêtes sont cliquables pour se téléporter."
L["Show the Sated/Exhaustion lockout countdown on the icon."] = "Afficher le compte à rebours de verrouillage Sated/Exhaustion sur l'icône." -- TODO: confirmar termo oficial
L["Show the bar full of its fill color while no global cooldown is running, instead of the background color."] = "Afficher la barre entièrement remplie de sa couleur de remplissage tant qu'aucune recharge globale n'est en cours, au lieu de la couleur d'arrière-plan."
L["Show the bright spark at the leading edge of the cast bar fill."] = "Afficher l'étincelle brillante au bord avant du remplissage de la barre d'incantation."
L["Show the charge and stack counters on this bar's icons."] = "Afficher les compteurs de charge et de cumul sur les icônes de cette barre."
L["Show the crafted quality rank on tracked items, matching the rank icon on the action bars. Items with no crafted quality are unaffected. Only shown while the item is owned."] = "Afficher le rang de qualité d'artisanat sur les objets suivis, correspondant à l'icône de rang sur les barres d'action. Les objets sans qualité d'artisanat ne sont pas affectés. Affiché uniquement tant que l'objet est possédé."
L["Show the enemy's raid target marker to the left of the spell name."] = "Afficher le repère de cible de raid de l'ennemi à gauche du nom du sort."
L["Show the pet frame whenever you have a pet, ignoring the Player frame's visibility settings."] = "Afficher le cadre du familier dès que vous avez un familier, en ignorant les réglages de visibilité du cadre du joueur."
L["Show the player's title inline with their name, and/or their guild on a line below it, on friendly nameplates."] = "Afficher le titre du joueur sur la même ligne que son nom, et/ou sa guilde sur une ligne en dessous, sur les barres d'info amicales."
L["Show the player's title or guild in a smaller line below their name on friendly nameplates."] = "Afficher le titre ou la guilde du joueur sur une ligne plus petite sous son nom, sur les barres d'info amicales."
L["Show the rotating cooldown edge on every cooldown in this bar, not just while a charge is recharging. Hide Recharge Edge still overrides this for individual charge spells."] = "Afficher le contour de recharge tournant sur chaque recharge de cette barre, pas seulement pendant qu'une charge se recharge. Masquer le contour de rechargement remplace toujours ceci pour les sorts à charges individuelles."
L["Show the selected action's name next to the selected icon."] = "Afficher le nom de l'action sélectionnée à côté de l'icône sélectionnée."
L["Show the tracker as the Rebirth icon or as a compact text line with charges and time until the next one."] = "Afficher le suivi comme l'icône de Rédemption ou comme une ligne de texte compacte avec les charges et le temps jusqu'à la prochaine." -- TODO: confirmar termo oficial
L["Show the unit's tooltip when hovering the frame itself."] = "Afficher l'infobulle de l'unité au survol du cadre lui-même."
L["Show this indicator's buffs in the exact order you arrange (the first 10 arranged buffs are guaranteed; any beyond follow the default sorting)."] = "Afficher les améliorations de cet indicateur exactement dans l'ordre que vous arrangez (les 10 premières améliorations arrangées sont garanties ; au-delà, elles suivent le tri par défaut)."
L["Show this indicator's buffs on every spec of your class, not only this spec."] = "Afficher les améliorations de cet indicateur sur toutes les spécialisations de votre classe, pas seulement celle-ci."
L["Show total equipped durability above the character model, colored from green to red."] = "Afficher la durabilité totale équipée au-dessus du modèle du personnage, colorée du vert au rouge."
L["Show weapon oil and imbue icons at the front of this bar. They are weapon enchants rather than auras, so they show independently of the options above -- and the aura grid is shifted inward to make room for them, with every row shifting over by the same amount."] = "Afficher les icônes d'huile d'arme et d'enchantement temporaire à l'avant de cette barre. Ce sont des enchantements d'arme plutôt que des auras, donc elles s'affichent indépendamment des options ci-dessus -- et la grille d'auras est décalée vers l'intérieur pour leur faire de la place, chaque rangée se décalant de la même quantité."
L["Show while this condition is false"] = "Afficher tant que cette condition est fausse"
L["Show who each spell is being cast on, exactly like the nameplate cast bars."] = "Afficher sur qui chaque sort est incanté, exactement comme les barres d'incantation des barres d'info."
L["Show who the spell is being cast on, exactly like the nameplate cast bars."] = "Afficher sur qui le sort est incanté, exactement comme les barres d'incantation des barres d'info."
L["Show your own class buffs on every spec, not only on the tracked healer spec."] = "Afficher les améliorations de votre propre classe sur toutes les spécialisations, pas seulement sur la spécialisation de soigneur suivie."
L["Show/Hide Windows Keybind"] = "Raccourci Afficher/Masquer les fenêtres"
L["Showing the '%s' override's value. Edit it from that override's editing mode."] = "Affiche la valeur du remplacement « %s ». Modifiez-la depuis le mode d'édition de ce remplacement."
L["Showing this aura from any caster; click for your casts only."] = "Affiche cette aura de n'importe quel lanceur ; cliquez pour vos incantations uniquement."
L["Showing this aura from your casts only; click for any caster."] = "Affiche cette aura de vos incantations uniquement ; cliquez pour n'importe quel lanceur."
L["Shown At Cursor"] = "Affiché au curseur"
L["Shown on Modifier"] = "Affiché sur modificateur"
L["Shown"] = "Affiché"
L["Shows Sweeping Strikes charges on the resource bar; Unit Frames and the personal Nameplate show them regardless."] = "Affiche les charges d'Attaques circulaires sur la barre de ressource ; les cadres d'unité et la barre d'info personnelle les affichent quoi qu'il en soit."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size, bar height and text offset."] = "Affiche une barre de compte à rebours sous la fenêtre surgissante d'acceptation de file d'attente, indiquant combien de temps vous avez pour accepter. Fonctionne avec ou sans l'habillage. Utilisez la pastille et l'engrenage pour définir la couleur du texte du compte à rebours, la taille du texte, la hauteur de barre et le décalage du texte."
L["Shows a countdown bar below the queue accept popup indicating how long you have to accept. Works with or without the reskin. Use the swatch and cog to set the countdown text color, text size. bar height and text offset."] = "Affiche une barre de compte à rebours sous la fenêtre surgissante d'acceptation de file d'attente, indiquant combien de temps vous avez pour accepter. Fonctionne avec ou sans l'habillage. Utilisez la pastille et l'engrenage pour définir la couleur du texte du compte à rebours, la taille du texte. hauteur de barre et décalage du texte."
L["Shows a countdown to the Arcane Soul window over the last seconds of Arcane Surge, then the time left inside it. Sunfury Arcane Mages only."] = "Affiche un compte à rebours jusqu'à la fenêtre de l'Âme arcanique durant les dernières secondes de Poussée arcanique, puis le temps restant à l'intérieur. Mages Arcane Furie solaire uniquement." -- TODO: confirmar termo oficial
L["Shows a house or globe icon marking which latency each value is."] = "Affiche une icône de maison ou de globe indiquant à quelle latence correspond chaque valeur."
L["Shows a mana percentage row for every healer in your group as its own movable text display. Position it in Unlock Mode."] = "Affiche une ligne de pourcentage de mana pour chaque soigneur de votre groupe, comme son propre affichage de texte déplaçable. Positionnez-le en mode Déverrouillage."
L["Shows a single Blood Plague debuff on enemy nameplates instead of one per copy (Blood Boil from weapon copies)."] = "Affiche un seul affaiblissement Peste sanguine sur les barres d'info ennemies au lieu d'un par copie (Ébullition de sang des copies d'armes)." -- TODO: confirmar termo oficial
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Affiche une petite marque blanche indiquant où en sera l'incantation lorsque votre interruption sortira de recharge."
L["Shows any debuff with a dispel type (Magic, Curse, Disease, Poison, Bleed), even if you cannot remove it"] = "Affiche tout affaiblissement avec un type de dissipation (Magie, Malédiction, Maladie, Poison, Saignement), même si vous ne pouvez pas le retirer"
L["Shows each crest's icon in front of its amount."] = "Affiche l'icône de chaque écu devant son montant."
L["Shows each healer's name before the number while in a raid. In a party the display always shows numbers only."] = "Affiche le nom de chaque soigneur avant le nombre en raid. En groupe, l'affichage montre toujours uniquement les nombres."
L["Shows every debuff except the ones you or your pet apply"] = "Affiche tous les affaiblissements sauf ceux que vous ou votre familier appliquez"
L["Shows every debuff on this frame."] = "Affiche tous les affaiblissements sur ce cadre."
L["Shows external defensives cast on you (Pain Suppression, Ironbark, etc.) in its own movable frame; position it via Unlock Mode."] = "Affiche les défensifs externes lancés sur vous (Suppression de la douleur, Ecorcefer, etc.) dans son propre cadre déplaçable ; positionnez-le via le mode Déverrouillage."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Affiche les grands montants avec des suffixes K/M (284 208po devient 284,2Kpo) au lieu du nombre complet groupé. L'infobulle affiche toujours le montant exact."
L["Shows only debuffs Blizzard flags as important"] = "Affiche uniquement les affaiblissements que Blizzard marque comme importants"
L["Shows only debuffs Blizzard flags as important."] = "Affiche uniquement les affaiblissements que Blizzard marque comme importants."
L["Shows only debuffs from Blizzard's curated raid-frame debuff set"] = "Affiche uniquement les affaiblissements de l'ensemble d'affaiblissements de cadre de raid sélectionné par Blizzard"
L["Shows only debuffs not caused by any player or player pet (this is what shows most pve debuffs, do not check this while All Debuffs is selected!"] = "Affiche uniquement les affaiblissements non causés par un joueur ou un familier de joueur (c'est ce qui affiche la plupart des affaiblissements PvE, ne cochez pas ceci tant que Tous les affaiblissements est sélectionné !"
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Affiche uniquement les affaiblissements que vous appliquez et que Blizzard marque aussi comme importants."
L["Shows only the debuffs you apply."] = "Affiche uniquement les affaiblissements que vous appliquez."
L["Shows only the stricter in-combat subset of the raid set"] = "Affiche uniquement le sous-ensemble plus strict en combat de l'ensemble de raid"
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Affiche uniquement les Auras suivies de ce cadre ; ajoutez-les avec Modifier les auras suivies en haut de ce menu."
L["Shows start as a small icon, and the keybind switches between the icon and the full windows. Turn off to show full windows and make the keybind hide and show them."] = "Affiche au démarrage sous forme de petite icône, et le raccourci bascule entre l'icône et les fenêtres complètes. Désactivez pour afficher les fenêtres complètes et faire en sorte que le raccourci les masque et les affiche."
L["Shows the Convert to Raid button, which reads Convert to Party while you are in a raid."] = "Affiche le bouton Convertir en raid, qui devient Convertir en groupe pendant que vous êtes en raid."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "Affiche le bouton Dissoudre. Il demande toujours confirmation avant de dissoudre, mais le masquer l'éloigne définitivement des clics accidentels."
L["Shows the Role Check button in window layouts and enables Right Click: Role Check on Compact Band."] = "Affiche le bouton Vérification de rôle dans les dispositions de fenêtre et active Clic droit : Vérification de rôle sur la Bande compacte."
L["Shows the Role Check button. Turn it off and the remaining buttons close the gap."] = "Affiche le bouton Vérification de rôle. Désactivez-le et les boutons restants comblent l'espace."
L["Shows the approximate distance to your current target as movable on-screen text (default 30-35). Use the cog for format, alignment, and text size; use Unlock Mode to position or Anchor to your Player Frame."] = "Affiche la distance approximative jusqu'à votre cible actuelle sous forme de texte déplaçable à l'écran (30-35 par défaut). Utilisez l'engrenage pour le format, l'alignement et la taille du texte ; utilisez le mode Déverrouillage pour la positionner ou l'ancrer à votre cadre de joueur."
L["Shows the audio icon next to the volume bar."] = "Affiche l'icône audio à côté de la barre de volume."
L["Shows the checked classes' mobility spell(s) counting down on cooldown. Nothing checked = feature disabled. Use Unlock Mode to reposition/resize."] = "Affiche le(s) sort(s) de mobilité des classes cochées en décompte de recharge. Rien de coché = fonctionnalité désactivée. Utilisez le mode Déverrouillage pour repositionner/redimensionner."
L["Shows the combat status text only while your character is in combat."] = "Affiche le texte de statut de combat uniquement tant que votre personnage est en combat."
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Affiche le texte de description de la monnaie dans l'infobulle. Désactivez pour une infobulle compacte avec juste le nom et le montant."
L["Shows the debuff's dispel type icon (Magic, Curse, Disease, Poison, Bleed) on the bar."] = "Affiche l'icône de type de dissipation de l'affaiblissement (Magie, Malédiction, Maladie, Poison, Saignement) sur la barre."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Affiche les affaiblissements que vous appliquez plus les affaiblissements importants de n'importe qui."
L["Shows the default Friends section for friends not in a custom group."] = "Affiche la section Amis par défaut pour les amis qui ne sont dans aucun groupe personnalisé."
L["Shows the focus target's raid marker icon next to the cast bar itself, instead of (or in addition to) the frame-level marker in Extras."] = "Affiche l'icône de repère de raid de la cible du point de mire à côté de la barre d'incantation elle-même, au lieu de (ou en plus de) le repère au niveau du cadre dans Extras."
L["Shows the items as a list instead of pages."] = "Affiche les objets sous forme de liste au lieu de pages."
L["Shows the nameplate-style dragon badge on elite, rare elite, and rare targets."] = "Affiche le badge de dragon de style barre d'info sur les cibles d'élite, d'élite rare et rares."
L["Shows the overlay only for debuffs you can currently dispel."] = "Affiche la superposition uniquement pour les affaiblissements que vous pouvez actuellement dissiper."
L["Shows the ping mark on a member's frame when someone pings them (needs Blizzard's Show Pings on Raid Frames setting on)."] = "Affiche la marque de ping sur le cadre d'un membre lorsque quelqu'un le ping (nécessite le réglage Blizzard Afficher les pings sur les cadres de raid activé)."
L["Shows the plugin's own icon next to its text."] = "Affiche la propre icône du module complémentaire à côté de son texte."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Affiche le texte du module complémentaire. Désactivé laisse un bloc icône seule qui conserve toujours l'infobulle et les clics du module complémentaire."
L["Shows the profession icons next to the text."] = "Affiche les icônes de métier à côté du texte."
L["Shows the rotation-helper ring on the button holding the One Button Assist action."] = "Affiche l'anneau d'aide à la rotation sur le bouton contenant l'action Assistance à bouton unique."
L["Shows the spec icon next to the text."] = "Affiche l'icône de spécialisation à côté du texte."
L["Shows the window even when you can do nothing about what it reports. Every column is read from your own client, so this view is complete rather than degraded."] = "Affiche la fenêtre même lorsque vous ne pouvez rien faire de ce qu'elle rapporte. Chaque colonne est lue depuis votre propre client, donc cette vue est complète plutôt que dégradée."
L["Shows where your interrupt will be ready during a cast. \"Tick\" marks the exact spot on the cast bar; \"Tick + Bar\" also colours the window during which your interrupt will be available."] = "Affiche où votre interruption sera prête pendant une incantation. « Trait » marque l'emplacement exact sur la barre d'incantation ; « Trait + barre » colore aussi la fenêtre durant laquelle votre interruption sera disponible."
L["Shows your best split on upcoming bosses instead of only killed ones."] = "Affiche votre meilleur temps intermédiaire sur les boss à venir au lieu des seuls boss tués."
L["Side"] = "Côté"
L["Sidebar"] = "Barre latérale"
L["Signup Note"] = "Note d'inscription"
L["Simplified Chinese caught up on the recent additions (chat recall, the performance reminder, Ignore Pain tracking and more)."] = "Le chinois simplifié a rattrapé les ajouts récents (rappel de discussion, le rappel de performance, le suivi d'Ignorer la douleur et plus)."
L["Single"] = "Simple"
L["Size Falloff"] = "Dégradé de taille"
L["Size by Active Groups"] = "Taille selon les groupes actifs"
L["Size matching is unavailable with Blizzard Style Action Bars."] = "L'alignement de taille n'est pas disponible avec les Barres d'action de style Blizzard."
L["Sizes the movement alert's free text, bar number and icon countdown. Switching the alert's Display Mode re-seeds this value."] = "Dimensionne le texte libre, le numéro de barre et le compte à rebours d'icône de l'alerte de déplacement. Changer le Mode d'affichage de l'alerte réinitialise cette valeur."
L["Skin "] = "Habillage "
L["Skin Third-Party Addons"] = "Habiller les addons tiers"
L["Skips your own frame when Show Tanks duplicates the raid's tanks. Hotkey picks can still add you."] = "Ignore votre propre cadre lorsque Afficher les tanks duplique les tanks du raid. Les sélections par raccourci peuvent toujours vous ajouter."
L["Skiron Cooldown Manager"] = "Skiron Cooldown Manager" -- JARGAO
L["Skull"] = "Crâne"
L["Skurri"] = "Skurri" -- JARGAO
L["Skyriding (Airborne)"] = "Vol draconique (en vol)"
L["Skyriding Mount"] = "Monture de vol draconique"
L["Slash"] = "Barre oblique"
L["Slot ID"] = "ID d'emplacement"
L["Slowly orbits your action bar buttons around each bar's centre while Party Mode is active. The buttons stay upright, so clicking, cooldowns and keybinds are unaffected. Pauses in combat, where moving a button is blocked."] = "Fait orbiter lentement les boutons de votre barre d'action autour du centre de chaque barre tant que le Mode groupe est actif. Les boutons restent droits, donc les clics, les recharges et les raccourcis ne sont pas affectés. Se met en pause en combat, où déplacer un bouton est bloqué."
L["SlugOutlineDescription"] = "SlugOutlineDescription" -- JARGAO
L["Smallest on-screen size a reskinned bar is drawn at.\n\nWidget bars on a nameplate inherit that nameplate's scale, so they come out tiny on small units. Below this size the bar is scaled up instead, text and all.\n\nSet to 0 to mirror Blizzard's size exactly."] = "Plus petite taille à l'écran à laquelle une barre réhabillée est dessinée.\n\nLes barres de widgets sur une barre d'info héritent de l'échelle de cette barre d'info, donc elles ressortent minuscules sur les petites unités. En dessous de cette taille, la barre est agrandie à la place, texte compris.\n\nRéglez sur 0 pour reproduire exactement la taille de Blizzard."
L["Smarter Pickers"] = "Sélecteurs plus intelligents"
L["Smooth Bar Animation"] = "Animation de barre fluide"
L["Solid Border"] = "Bordure pleine"
L["Some addon skins could not apply live. A UI reload will fully apply them."] = "Certains habillages d'addons n'ont pas pu s'appliquer à chaud. Un rechargement de l'interface les appliquera pleinement."
L["Sort Direction"] = "Sens de tri"
L["Sort Method"] = "Méthode de tri"
L["Sort Options"] = "Options de tri"
L["Sort to Bottom"] = "Trier vers le bas"
L["Sorted"] = "Trié"
L["Sorting normally packs your items into the first free slots, at the top of the grid. Turn this on to pack them into the last slots instead, so the empty slots end up at the top. The item order itself does not change. This affects the OneBag, MultiBag and bank views -- category views fill their own grid with no gaps, so there is nothing to move. MultiBag and the bank use Blizzard's own sorting, so while this is on it also flips Blizzard's cleanup direction; turning it back off restores the direction you had."] = "Le tri regroupe normalement vos objets dans les premiers emplacements libres, en haut de la grille. Activez ceci pour les regrouper dans les derniers emplacements à la place, afin que les emplacements vides se retrouvent en haut. L'ordre des objets lui-même ne change pas. Cela affecte les vues OneBag, MultiBag et banque -- les vues par catégorie remplissent leur propre grille sans espace, donc il n'y a rien à déplacer. MultiBag et la banque utilisent le tri propre de Blizzard, donc tant que ceci est activé, cela inverse aussi le sens de rangement de Blizzard ; le désactiver restaure le sens que vous aviez."
L["Sound Effects"] = "Effets sonores"
L["Space between the text and the edge of the bubble."] = "Espace entre le texte et le bord de la bulle."
L["Space"] = "Espace"
L["Speaks the ability name once, right when it comes off cooldown -- not a running countdown. None = no speech."] = "Prononce le nom de la capacité une fois, juste lorsqu'elle sort de recharge -- pas un décompte continu. Aucun = pas de voix."
L["Spec / Talents / Spellbook"] = "Spécialisation / Talents / Grimoire"
L["Spec Override"] = "Remplacement de spécialisation"
L["Spec and conditional overrides can now hold the Visibility setting itself, replacing it with Never, Always or Mouseover for those specs."] = "Les remplacements de spécialisation et conditionnels peuvent désormais contenir le réglage de Visibilité lui-même, le remplaçant par Jamais, Toujours ou Survol pour ces spécialisations."
