L["Split Stack"] = "Diviser la pile"
L["Split items by category -- Armor, Consumables, Professions and so on -- using the same category list, order and renames as the All Items bag view. Nests inside the expansion headers when Nest by Expansion is also on. Categories that split further do so automatically: gear by equipment slot, Professions and Trade Goods by profession and material type."] = "Diviser les objets par catégorie -- Armure, Consommables, Professions et ainsi de suite -- en utilisant la même liste, le même ordre et les mêmes renommages de catégories que la vue de sac Tous les objets. S'imbrique sous les en-têtes d'extension lorsque Imbriquer par extension est aussi activé. Les catégories qui se subdivisent davantage le font automatiquement : équipement par emplacement, Professions et Matériaux par métier et type de matériau."
L["Split this stack into empty slots repeatedly until only the chosen amount or less remains. Alt+Enter does the same."] = "Diviser cette pile dans des emplacements vides de façon répétée jusqu'à ce qu'il ne reste que le montant choisi ou moins. Alt+Entrée fait de même."
L["Spraybots"] = "Spraybots" -- JARGAO
L["Square or Rectangular Shape"] = "Forme carrée ou rectangulaire"
L["Squares the extra action and zone ability buttons and gives them a thin black border.\n\nOff by default. The size slider below works whether this is on or off."] = "Rend carrés les boutons d'action supplémentaire et de capacité de zone et leur donne une fine bordure noire.\n\nDésactivé par défaut. Le curseur de taille ci-dessous fonctionne que ceci soit activé ou non."
L["Stack Based Bar"] = "Barre basée sur les cumuls"
L["Stack Splitter"] = "Diviseur de pile"
L["Stack Text and Glows"] = "Texte de cumul et lueurs"
L["Stack Thresholds"] = "Seuils de cumul"
