L["Suppresses \"You have learned a new spell/ability/passive effect\" and \"You have unlearned ...\" system messages, like the ones spammed every time you switch spec or talent loadout."] = "Supprime les messages système « Vous avez appris un nouveau sort/une nouvelle capacité/un nouvel effet passif » et « Vous avez désappris... », comme ceux qui s'affichent en masse à chaque changement de spécialisation ou de configuration de talents."
L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat.\n\nNote: while this is active, holding Left+Right click to move forward won't work if your cursor is over a suppressed nameplate/unit, since this feature has to take over the right mouse button entirely to block targeting."] = "Supprime le ciblage par clic droit. Ennemis s'applique partout. Alliés en combat ne supprime les cibles amicales que lorsque vous êtes en combat, afin que vous puissiez toujours cliquer droit sur les marchands et les PNJ hors combat.\n\nRemarque : lorsque cette option est active, maintenir Clic gauche+droit pour avancer ne fonctionnera pas si votre curseur se trouve sur une barre d'info/unité supprimée, car cette fonction doit entièrement prendre le contrôle du clic droit pour bloquer le ciblage."
L["Swap Combat Potions When Missing"] = "Remplacer les potions de combat manquantes"
L["Swap Light/Reckless Pots When Missing"] = "Remplacer les potions légères/téméraires manquantes"
L["Switch At"] = "Basculer à"
L["Switch Blizzard's chat bubbles off for as long as you are inside a dungeon, raid, scenario or battleground, and back on the way out.\n\nEllesmereUI never restyles bubbles inside an instance: the game's bubble frames are off limits to addons there. This decides whether Blizzard's own are visible at all."] = "Désactive les bulles de dialogue de Blizzard tant que vous êtes dans un donjon, un raid, un scénario ou un champ de bataille, et les réactive en sortant.\n\nEllesmereUI ne restyle jamais les bulles à l'intérieur d'une instance : les cadres de bulles du jeu y sont hors de portée des addons. Ceci détermine simplement si celles de Blizzard sont visibles ou non."
L["Switch to Experience"] = "Basculer vers l'expérience"
L["Switch to Reputation"] = "Basculer vers la réputation"
L["Sync Border with Chat Panel"] = "Synchroniser la bordure avec le panneau de discussion"
L["Sync cleared -- fewer than two specs remained selected."] = "Synchronisation effacée - moins de deux spécialisations sont restées sélectionnées."
L["Sync cleared -- only one spec was selected. Tick at least two specs (including other characters' specs) to sync between them."] = "Synchronisation effacée - une seule spécialisation était sélectionnée. Cochez au moins deux spécialisations (y compris celles d'autres personnages) pour synchroniser entre elles."
L["Syncing generic CDs/buffs across %d specs. Icon order is not synced -- each spec keeps its own arrangement."] = "Synchronisation des CD/améliorations génériques sur %d spécialisations. L'ordre des icônes n'est pas synchronisé - chaque spécialisation conserve sa propre disposition."
