L["Thank you for making EllesmereUI possible."] = "Merci de rendre EllesmereUI possible."
L["Thank you to all who support EllesmereUI and its incredible support team!"] = "Merci à tous ceux qui soutiennent EllesmereUI et son incroyable équipe de support !"
L["The Battle.net friend online and offline toast gets a window skin, with its own Friend Notifications card"] = "Le toast de connexion/déconnexion d'un ami Battle.net reçoit un habillage de fenêtre, avec sa propre carte Notifications d'amis"
L["The Battle.net popup when a friend comes online or goes offline, plus broadcasts and invites."] = "La fenêtre Battle.net qui s'affiche quand un ami se connecte ou se déconnecte, ainsi que les diffusions et invitations."
L["The Blinding Vale"] = "Le Vallon aveuglant" -- TODO: confirmar termo oficial
L["The Combat Indicator is not available for the Focus frame."] = "L'indicateur de combat n'est pas disponible pour le cadre Focalisation."
L["The LFG Reminder popup now matches dungeon names on every client language, not only English and Russian."] = "La fenêtre de rappel LFG reconnaît désormais les noms de donjons dans toutes les langues du client, pas seulement l'anglais et le russe."
L["The Missing Pet reminder no longer appears while mounted or flashes on dismount."] = "Le rappel de familier manquant n'apparaît plus en étant monté et ne clignote plus en descendant de monture."
L["The Pet Bar cannot use group-based visibility."] = "La Barre de familier ne peut pas utiliser la visibilité basée sur le groupe."
L["The Social window frame, border, title bar, Battle.net bar, search boxes, filter dropdowns and buttons. List contents and the side tab icons stay untouched."] = "Le cadre, la bordure, la barre de titre, la barre Battle.net, les champs de recherche, les menus déroulants de filtre et les boutons de la fenêtre Social. Le contenu des listes et les icônes des onglets latéraux restent inchangés."
L["The Venomous Abyss"] = "L'Abysse venimeux" -- TODO: confirmar termo oficial
L["The Whirlwind and Sweeping Strikes bar honors the Empty Bar Overlay again so spent charges show in Dark Mode, no longer draws a second set of divider lines with Bar Spacing set, hides its threshold strip while thresholds are disabled, and accepts a stack threshold up to 20."] = "La barre Coup d'ouragan et Frappes balayantes respecte de nouveau la Superposition de barre vide, si bien que les charges consommées s'affichent en Mode sombre ; elle ne dessine plus un second jeu de lignes de séparation lorsque l'Espacement des barres est défini, masque sa bande de seuil lorsque les seuils sont désactivés, et accepte un seuil de charges allant jusqu'à 20."
L["The \"You received\" popups for loot, currency, and upgrades."] = "Les fenêtres « Vous avez reçu » pour le butin, la monnaie et les améliorations."
L["The \"you have been invited to a group\" dialogs, with your role and Accept / Decline."] = "Les fenêtres « vous avez été invité à rejoindre un groupe », avec votre rôle et Accepter / Refuser."
L["The active override's custom %s is bound to this page. Leave the %s tab to switch to another override."] = "Le %s personnalisé du remplacement actif est lié à cette page. Quittez l'onglet %s pour passer à un autre remplacement."
L["The bank window catches up to the bags: nest OneBank and OneWarbank by expansion, group items by your bag categories with automatic splits by equipment slot, profession and material, and browse a category sidebar that spans your character bank and warband together."] = "La fenêtre de banque rattrape les sacs : imbriquez OneBank et OneWarbank par extension, regroupez les objets selon vos catégories de sacs avec des séparations automatiques par emplacement d'équipement, métier et matériau, et parcourez une barre latérale de catégories qui couvre à la fois la banque de votre personnage et celle du bataillon."
L["The damage and tank cut of Light of Nitex. The same style refocused on your rotation, procs, and cooldowns front and center."] = "La version dégâts et tank de Light of Nitex. Le même style recentré sur votre rotation, vos procs et vos temps de recharge mis en avant."
L["The dark counterpart to Lazar's Dawn. A moody, high-contrast layout that keeps focus locked on the fight."] = "Le pendant sombre de Lazar's Dawn. Une disposition sombre et très contrastée qui garde l'attention rivée sur le combat."
L["The delve difficulty window: tier dropdown, reward list and Enter button. The Map Properties row is left stock -- it is a Blizzard widget display and is not safe to restyle."] = "La fenêtre de difficulté des gouffres : liste déroulante de palier, liste de récompenses et bouton Entrer. La ligne Propriétés de la carte reste d'origine - il s'agit d'un affichage de widget Blizzard qu'il n'est pas prudent de restyler."
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "L'exact inverse de Vol draconique (en vol) : tout ce qui n'est pas en vol sur une monture capable de planer ou une forme de vol, y compris le fait de se tenir au sol."
L["The gap between a nested menu's icons and the entry that opens it."] = "L'espace entre les icônes d'un menu imbriqué et l'entrée qui l'ouvre."
L["The item upgrade window: upgrade slot, track selector, cost, and the currency strip."] = "La fenêtre d'amélioration d'objet : emplacement d'amélioration, sélecteur de palier, coût et bandeau de monnaie."
L["The loot window: item rows with squared icons, kept item quality colors."] = "La fenêtre de butin : lignes d'objets avec icônes carrées, couleurs de qualité d'objet conservées."
L["The most cast bars shown at once. Extra casters take a bar as soon as one frees up."] = "Le nombre maximal de barres d'incantation affichées à la fois. Les lanceurs supplémentaires prennent une barre dès qu'une se libère."
L["The need / greed / pass roll popups, with a squared icon and a flat roll timer."] = "Les fenêtres contextuelles de tirage Besoin / Cupidité / Passer, avec une icône carrée et un minuteur de tirage plat."
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "Le groupe de remplacement « %s » fournit déjà le mode Déverrouillage personnalisé pour votre spécialisation actuelle. Personnalisez-le là-bas, ou retirez cette spécialisation de ce groupe."
L["The panel the minimap Group Finder eye shows on hover: queue titles, role icons and counts, and time in queue."] = "Le panneau que l'œil de l'Outil de recherche de groupe de la minicarte affiche au survol : titres de file d'attente, icônes et effectifs de rôle, et temps en file d'attente."
L["The pending-rolls window: encounter picker, roll timer, and the result rows."] = "La fenêtre des tirages en attente : sélecteur de rencontre, minuteur de tirage et lignes de résultat."
L["The pet frame updates its name and portrait when you swap pets (for example Voidwalker to Felhunter)."] = "Le cadre du familier met à jour son nom et son portrait lorsque vous changez de familier (par exemple, de Suppôt du Vide à Chasse-Fel)."
L["The player-to-player trade window: frame, both item columns, the enchant slots, money rows and buttons. Item icons are squared and carry a rarity border. Both portraits are removed, as on every other window."] = "La fenêtre d'échange entre joueurs : cadre, les deux colonnes d'objets, les emplacements d'enchantement, les lignes d'argent et les boutons. Les icônes d'objets sont carrées et affichent une bordure de rareté. Les deux portraits sont supprimés, comme sur toutes les autres fenêtres."
L["The ready check prompt with its Yes / No buttons, plus the initiator's response list."] = "La fenêtre de vérification de préparation avec ses boutons Oui / Non, ainsi que la liste des réponses de l'initiateur."
L["The ready check prompt with its Yes / No buttons."] = "La fenêtre de vérification de préparation avec ses boutons Oui / Non."
L["The refresh rate now bottoms out at 0.5s (lower saved values move up to it), trimming memory churn during combat."] = "Le taux de rafraîchissement ne descend désormais plus sous 0,5 s (les valeurs enregistrées inférieures remontent à ce seuil), réduisant la sollicitation mémoire en combat."
L["The scriptProfile CVar is enabled."] = "La CVar scriptProfile est activée."
L["The single stack threshold is off while Multiple Thresholds is on."] = "Le seuil de pile unique est désactivé tant que Seuils multiples est activé."
L["The standard buff grid"] = "La grille d'améliorations standard"
L["The standard debuff grid"] = "La grille d'affaiblissements standard"
L["The stricter in-combat subset of the raid set."] = "Le sous-ensemble plus strict en combat de l'ensemble de raid."
L["The taintLog CVar is enabled."] = "La CVar taintLog est activée."
L["The taintLog and scriptProfile CVars are enabled."] = "Les CVars taintLog et scriptProfile sont activées."
L["The target effect's border size no longer snaps back to normal while a cast bar is shown with Border Wraps Around Cast Bar enabled."] = "La taille de bordure de l'effet de cible ne revient plus brusquement à la normale lorsqu'une barre d'incantation s'affiche avec Bordure autour de la barre d'incantation activée."
L["The widest angle a nest's entries may spread over. They stay on one ring for as long as they fit inside it; the rest go onto a second ring further out."] = "L'angle maximal sur lequel les entrées d'un nid peuvent s'étaler. Elles restent sur un seul anneau tant qu'elles y tiennent ; le reste se place sur un second anneau plus à l'extérieur."
L["The widest angle a nest's entries may spread over."] = "L'angle maximal sur lequel les entrées d'un nid peuvent s'étaler."
L["These are the same settings found on each module's own pages, not separate ones."] = "Ce sont les mêmes réglages que ceux trouvés sur les pages propres à chaque module, pas des réglages séparés."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Ces spécialisations conservent des valeurs de remplacement qu'aucun mode d'édition de groupe ne peut plus atteindre (laissées par des changements d'appartenance). Elles s'appliquent toujours. Retirez-en une pour ramener cette spécialisation à la valeur par défaut partagée."
L["Thickness applies to Solid Border and Pixel Glow"] = "L'épaisseur s'applique à Bordure pleine et Lueur pixelisée"
L["Thickness in physical pixels for Solid Border and Pixel Glow."] = "Épaisseur en pixels physiques pour Bordure pleine et Lueur pixelisée."
L["Thickness in physical pixels. -1 follows the Debuff Manager's Border setting, 0 hides the dispel color border."] = "Épaisseur en pixels physiques. -1 suit le réglage Bordure du Gestionnaire d'affaiblissements, 0 masque la bordure de couleur de dissipation."
L["Third Timer"] = "Troisième chrono"
L["This Setting Has Overrides"] = "Ce réglage a des remplacements"
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "Cette barre a un Décalage de barre supplémentaire (X %1$s, Y %2$s) défini dans ses options. Le mode Déverrouillage affiche la position de base ; le décalage se réapplique à la sortie."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Ceci ne peut pas être annulé. Pensez à exporter d'abord ce profil comme sauvegarde."
L["This cannot be undone. Export your own profile as a backup first."] = "Ceci ne peut pas être annulé. Exportez d'abord votre propre profil comme sauvegarde."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Ce contrôle a récemment changé de sens : il copie désormais DEPUIS le cadre que vous choisissez. Confirmer copiera tous les réglages partagés DEPUIS %1$s VERS %2$s."
L["This element cannot use group-based visibility."] = "Cet élément ne peut pas utiliser la visibilité basée sur le groupe."
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Cet élément s'affiche dès qu'UNE condition Afficher correspond. Masquer conserve son sens dans les deux modes de correspondance : un Masquer coché masque toujours, sur chaque ligne."
L["This element shows as soon as ONE condition matches, and a Hide lane then means show while that condition is false."] = "Cet élément s'affiche dès qu'UNE condition correspond, et une ligne Masquer signifie alors s'afficher tant que cette condition est fausse."
L["This element will only show while you are inside a house or plot"] = "Cet élément ne s'affichera que lorsque vous êtes dans une maison ou une parcelle"
L["This element will only show while you are mounted"] = "Cet élément ne s'affichera que lorsque vous êtes monté"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Cet export inclut des réglages inter-profils qui écraseront les réglages de l'utilisateur important, y compris Confort de jeu, Hovercast et d'autres qui ne devraient normalement pas être partagés avec des profils standards. CECI N'EST PAS RECOMMANDÉ pour le partage public de profils."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Cette fonction optimise vos réglages graphiques en jeu pour vous offrir la meilleure combinaison de FPS élevés et de clarté visuelle.\n\nVous pouvez annuler tous les changements à tout moment en cliquant sur « Restaurer mes réglages », qui apparaîtra après l'optimisation.\n\n\nCe que nous modifions :\n\n"
L["This feature runs continuous range checks against every visible enemy nameplate. It is one of the more expensive features in EllesmereUI and can measurably increase CPU usage in crowded areas."] = "Cette fonction effectue des vérifications de portée en continu sur chaque barre d'info ennemie visible. C'est l'une des fonctions les plus coûteuses d'EllesmereUI et elle peut augmenter sensiblement l'utilisation du CPU dans les zones surchargées."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "Le Gestionnaire d'affaiblissements personnalisé de ce groupe ne peut être activé ou modifié qu'en jouant l'une de ses spécialisations."
L["This is a voice preview"] = "Ceci est un aperçu vocal"
L["This is the spec you're syncing from -- it's always included."] = "C'est la spécialisation depuis laquelle vous synchronisez - elle est toujours incluse."
L["This option applies to bar-type resources only (pips use stack counts)."] = "Cette option s'applique uniquement aux ressources de type barre (les pastilles utilisent les compteurs de piles)."
L["This option applies to pip-type resources only."] = "Cette option s'applique uniquement aux ressources de type pastille."
L["This option can't be used while you have the Power Bar Height Matched in the Unlock Mode."] = "Cette option ne peut pas être utilisée tant que la Hauteur de la barre de ressource est alignée dans le mode Déverrouillage."
L["This option does not apply while Anchor to Cursor is enabled"] = "Cette option ne s'applique pas tant qu'Ancrer au curseur est activé"
L["This option is only available for abilities with multiple charges"] = "Cette option n'est disponible que pour les capacités à charges multiples"
L["This option requires <text> to be enabled"] = "Cette option nécessite que <text> soit activé"
L["This option requires Blizzard's Assisted Highlight to be enabled"] = "Cette option nécessite que le Surlignage d'assistance de Blizzard soit activé"
L["This option requires Combine Spell Name and Target to be disabled."] = "Cette option nécessite que Combiner le nom du sort et la cible soit désactivé."
L["This option requires Countdown Format to count GCDs inside Arcane Soul"] = "Cette option nécessite que le Format du compte à rebours compte les GCD à l'intérieur d'Âme arcanique"
L["This option requires Dark Mode Class Resource to be disabled. Dark Mode colors can be adjusted in Global Settings -> Fonts & Colors."] = "Cette option nécessite que Ressource de classe en Mode sombre soit désactivé. Les couleurs du Mode sombre peuvent être ajustées dans Réglages globaux -> Polices et couleurs."
L["This option requires Display Style to be set to Icon"] = "Cette option nécessite que Style d'affichage soit réglé sur Icône"
L["This option requires Display Style to be set to Text"] = "Cette option nécessite que Style d'affichage soit réglé sur Texte"
L["This option requires Show Tooltips to be set to hide tooltips"] = "Cette option nécessite que Afficher les infobulles soit réglé pour masquer les infobulles"
L["This option requires Split Compare to include a key level"] = "Cette option nécessite que Comparaison des temps intermédiaires inclue un niveau de clé"
L["This option requires Subtitle Text to include the Guild Name"] = "Cette option nécessite que Texte de sous-titre inclue le Nom de guilde"
L["This option requires Tooltips to be set to Shown on Modifier"] = "Cette option nécessite que Infobulles soit réglé sur Affiché sur modificateur"
L["This option requires a Split Compare mode"] = "Cette option nécessite un mode Comparaison des temps intermédiaires"
L["This option requires a cooldown-tracking bar"] = "Cette option nécessite une barre de suivi de recharge"
L["This option requires a style that draws the glow ring"] = "Cette option nécessite un style qui dessine l'anneau de lueur"
L["This option requires the Button Overlay style"] = "Cette option nécessite le style Superposition du bouton"
L["This option requires the module to be enabled"] = "Cette option nécessite que le module soit activé"
L["This override has no indicators for this spec, so nothing shows here until you add some."] = "Ce remplacement n'a aucun indicateur pour cette spécialisation, donc rien ne s'affiche ici tant que vous n'en ajoutez pas."
L["This overwrites the chosen frame's current settings. Frame position, visibility, and enable state are not changed."] = "Ceci écrase les réglages actuels du cadre choisi. La position du cadre, sa visibilité et son état d'activation ne sont pas modifiés."
L["This overwrites this action menu's current settings. Its actions, name, and keybind are not changed."] = "Ceci écrase les réglages actuels de ce menu d'actions. Ses actions, son nom et son raccourci ne sont pas modifiés."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Ceci écrase les réglages actuels de ce cadre. La position du cadre, sa visibilité et son état d'activation ne sont pas modifiés."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Ceci écrase définitivement les réglages de ce profil avec le remplacement « %s » : ses réglages capturés ainsi que ses dispositions personnalisées de mode Déverrouillage et de Gestionnaire d'améliorations (le cas échéant) deviennent la base propre du profil pour chaque spécialisation. TOUS les groupes de remplacement de spécialisation de ce profil sont ensuite supprimés et l'interface se recharge. Les remplacements conditionnels ne sont pas affectés."
L["This profile already holds 16 action menus"] = "Ce profil contient déjà 16 menus d'actions"
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Cette chaîne de profil ne contient aucun réglage de Habillages de fenêtre et d'infobulle."
L["This profile string does not carry any global settings."] = "Cette chaîne de profil ne contient aucun réglage global."
L["This profile string does not carry any override data."] = "Cette chaîne de profil ne contient aucune donnée de remplacement."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Ce profil a été créé à une échelle d'interface de %1$d%% ; la vôtre est de %2$d%%. Modifier votre échelle d'interface pour correspondre au profil importé ? Ceci affichera tous les profils à cette échelle, car l'Échelle d'interface n'est pas un réglage propre à chaque profil, mais peut être remise à tout moment à votre valeur d'origine."
L["This replaces %d existing value(s) for this setting across your specs."] = "Ceci remplace %d valeur(s) existante(s) pour ce réglage sur l'ensemble de vos spécialisations."
L["This replaces %d existing value(s) for this setting on this bar."] = "Ceci remplace %d valeur(s) existante(s) pour ce réglage sur cette barre."
L["This replaces 3 existing value(s) for this setting across your specs. Do you want to continue?"] = "Ceci remplace 3 valeur(s) existante(s) pour ce réglage sur l'ensemble de vos spécialisations. Voulez-vous continuer ?"
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "La valeur active « Appliquer à la barre (toutes spés) » de ce réglage sera remplacée."
L["This setting's active Apply to Bar value will be replaced."] = "La valeur active « Appliquer à la barre » de ce réglage sera remplacée."
L["This spec doesn't have this spell."] = "Cette spécialisation n'a pas ce sort."
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "Le mode Déverrouillage personnalisé de cette spécialisation appartient à « %s ». Personnalisez-le là-bas, ou retirez la spécialisation de ce groupe."
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Cette chaîne est un export COMPTE COMPLET. Elle remplace vos réglages à l'échelle du compte par ceux de l'expéditeur, y compris Confort de jeu, les raccourcis HoverCast, les configurations de sorts du Gestionnaire de recharge, les ancrages de déblocage, l'échelle d'interface et les raccourcis de profil - pas seulement un profil. Vos autres profils sont conservés, mais un profil portant le même nom est remplacé."
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Ceci créera un Gestionnaire d'améliorations entièrement unique pour ce groupe conditionnel. Les changements apportés à votre Gestionnaire d'améliorations par défaut ne l'affecteront plus."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Ceci créera un Gestionnaire d'améliorations entièrement unique pour ce groupe de remplacement. Les changements apportés à votre Gestionnaire d'améliorations par défaut n'affecteront plus ces spécialisations."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Ceci créera un Gestionnaire d'affaiblissements entièrement unique pour ce groupe conditionnel. Vos réglages actuels du Gestionnaire d'affaiblissements sont copiés comme point de départ, et les changements apportés à votre Gestionnaire d'affaiblissements par défaut ne l'affecteront plus."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Ceci créera un Gestionnaire d'affaiblissements entièrement unique pour ce groupe de remplacement. Vos réglages actuels du Gestionnaire d'affaiblissements sont copiés comme point de départ, et les changements apportés à votre Gestionnaire d'affaiblissements par défaut n'affecteront plus ces spécialisations."
L["This will keep appearing each login until the layout is correct."] = "Ceci continuera d'apparaître à chaque connexion jusqu'à ce que la disposition soit correcte."
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Ceci remplacera VOS réglages d'Interface Blizz améliorée (les onglets Habillages de fenêtre et Infobulles, menus et fenêtres contextuelles) par ceux du partageur, sur TOUS vos profils. Vos réglages actuels sur ces deux onglets ne pourront pas être récupérés ensuite."
