L["Thresholds configured for:"] = "Seuils configurés pour :"
L["Thresholds have their own per-spec system and can't be edited while editing a spec group"] = "Les seuils ont leur propre système par spécialisation et ne peuvent pas être modifiés en éditant un groupe de spécialisations"
