L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Teinte une entrée qui n'aurait aucun effet en ce moment : rouge quand la cible est hors de portée, bleu quand la ressource vous manque, et gris quand le jeu la refuse pour toute autre raison. Sorts et objets uniquement - le jeu signale tous les jouets comme inutilisables, et l'utilisabilité d'une macro dépend de ce que son corps résout."
L["Tint the bar with the Important colour when the enemy casts a spell the game flags as important."] = "Teinte la barre avec la couleur Important quand l'ennemi lance un sort que le jeu marque comme important."
L["Tint the cast bar with the Important colour when the unit casts a spell the game flags as important. Your interrupt being on cooldown still takes priority."] = "Teinte la barre d'incantation avec la couleur Important quand l'unité lance un sort que le jeu marque comme important. Votre interruption en recharge reste prioritaire."
L["Tints the pattern with the bar's current color instead of the custom overlay color."] = "Teinte le motif avec la couleur actuelle de la barre au lieu de la couleur de surcouche personnalisée."
