L["Use a world marker entry again to pick that marker back up. Off places the marker again, at the new position.\nThis does not change the entry that clears all world markers, or the cycling entry."] = "Utilisez de nouveau une entrée de repère du monde pour reprendre ce repère. Désactivé le replace, à la nouvelle position.\nCeci ne change pas l'entrée qui efface tous les repères du monde, ni l'entrée cyclique."
L["Use unique backgrounds for each bar"] = "Utiliser des arrière-plans uniques pour chaque barre"
L["Used by the movement alert's Bar display mode."] = "Utilisé par le mode d'affichage Barre de l'alerte de déplacement."
L["Uses Blizzard's own party switch, independent of the other channels. Instance chat, the one an LFG or LFR group talks in, is covered here too."] = "Utilise le propre interrupteur de groupe de Blizzard, indépendant des autres canaux. Le chat d'instance, celui où parle un groupe LFG ou LFR, est aussi couvert ici."
L["Uses Blizzard's own raid switch, which it ships off. Ticking this turns that switch on, and it is put back the way you had it when you untick it or switch the feature off."] = "Utilise le propre interrupteur de raid de Blizzard, qu'il expédie désactivé. Cocher ceci active cet interrupteur, qui est remis comme vous l'aviez laissé quand vous décochez ou désactivez la fonction."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time."] = "Utilise l'entrée que vous pointez pendant qu'un menu est maintenu ouvert avec Basculer l'ouverture du menu. Une touche partagée par tous les menus, réquisitionnée seulement tant qu'un menu est ouvert - un bouton de souris garde son usage normal le reste du temps."
L["Uses the entry you are pointing at while a menu is kept open with Toggle Menu Open. One key shared by every menu, claimed only while a menu is up -- a mouse button keeps its normal use the rest of the time.\n\nLeft-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Utilise l'entrée que vous pointez pendant qu'un menu est maintenu ouvert avec Basculer l'ouverture du menu. Une touche partagée par tous les menus, réquisitionnée seulement tant qu'un menu est ouvert - un bouton de souris garde son usage normal le reste du temps.\n\nClic gauche pour définir un raccourci, puis appuyez sur une touche ou\ncliquez sur un bouton de souris pour l'utiliser.\nÉchap annule. Clic droit ici pour retirer le raccourci."
