L["Weekly and event choice windows such as Abundance harvests and \"how will you aid...\" pickers: option plates, headers, reward icons and buttons. Option artwork stays."] = "Les fenêtres de choix hebdomadaires et d'événement, comme les récoltes d'Abondance et les sélecteurs « comment allez-vous aider... » : plaques d'option, en-têtes, icônes de récompense et boutons. Les illustrations d'option restent inchangées."
L["What sits between the crest amounts."] = "Ce qui se place entre les quantités d'écus."
L["What sits in front of the number. Icon shows the character icon; the color swatches on the left tint it."] = "Ce qui se place devant le nombre. Icône affiche l'icône du personnage ; les nuanciers de couleur à gauche la teintent."
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position. While dragging, buttons snap to nearby buttons and the minimap border; hold Ctrl together with Shift to disable snapping."] = "Une fois activé, Maj+Clic sur n'importe quel bouton de la minicarte (courrier, calendrier, suivi, boutons d'addon) pour le faire glisser vers une position personnalisée. Pendant le glissement, les boutons s'accrochent aux boutons voisins et à la bordure de la minicarte ; maintenez Ctrl avec Maj pour désactiver l'accrochage."
L["When on, augment rune/flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Activé, les rappels de rune d'augmentation/fiole/nourriture/arme s'affichent encore (atténués) quand vous n'avez pas l'objet correspondant dans vos sacs, comme invite à vous réapprovisionner.\nDésactivé, ils sont entièrement masqués si vous ne portez pas l'objet."
L["When on, flask/food/weapon reminders still show (dimmed) when you have no matching item in your bags, as a prompt to restock.\nWhen off, they are hidden entirely if you don't carry the item."] = "Activé, les rappels de fiole/nourriture/arme s'affichent encore (atténués) quand vous n'avez pas l'objet correspondant dans vos sacs, comme invite à vous réapprovisionner.\nDésactivé, ils sont entièrement masqués si vous ne portez pas l'objet."
L["When the current spec has no bars in this group, keeps elements anchored to the group in place and shifts them up or down by one bar height (tune with the cog's Extra Y Offset) to cover its empty slot."] = "Quand la spécialisation actuelle n'a aucune barre dans ce groupe, garde les éléments ancrés au groupe en place et les décale vers le haut ou le bas d'une hauteur de barre (ajustable avec le Décalage Y supplémentaire de l'engrenage) pour combler son emplacement vide."
L["When your bags have none of one combat potion type, its icon swaps to track the next type you own."] = "Quand vos sacs n'ont plus aucun exemplaire d'un type de potion de combat, son icône bascule pour suivre le prochain type que vous possédez."
L["When your bags have none of one potion type, its icon swaps to track the other type."] = "Quand vos sacs n'ont plus aucun exemplaire d'un type de potion, son icône bascule pour suivre l'autre type."
L["Where to Show"] = "Où afficher"
L["Which audio channel the block's volume bar adjusts."] = "Le canal audio que la barre de volume du bloc ajuste."
L["Which direction new icons extend from the frame's edge."] = "La direction dans laquelle les nouvelles icônes s'étendent depuis le bord du cadre."
L["Which end of the crest ladder comes first."] = "Quelle extrémité de l'échelle d'écus vient en premier."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Dispellable shows only buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Quelles améliorations ennemies s'affichent sur les barres d'info. Important affiche les améliorations que Blizzard marque pour les barres d'info ennemies plus tout ce qui est dissipable ; Dissipable n'affiche que les améliorations pouvant être dissipées, purgées ou apaisées. Avec un style Lueur de dissipation défini, chaque amélioration dissipable affichée brille."
L["Which enemy buffs show on nameplates. Important shows the buffs Blizzard flags for enemy nameplates plus anything dispellable; Only Dispellable shows just the buffs that can be dispelled, purged or soothed. With a Dispel Glow style set, every dispellable buff shown glows."] = "Quelles améliorations ennemies s'affichent sur les barres d'info. Important affiche les améliorations que Blizzard marque pour les barres d'info ennemies plus tout ce qui est dissipable ; Seulement dissipable n'affiche que les améliorations pouvant être dissipées, purgées ou apaisées. Avec un style Lueur de dissipation défini, chaque amélioration dissipable affichée brille."
L["Which hearthstone the left click uses. Random Hearthstone picks a random owned variant each cast. Right click always rolls a random one."] = "La pierre de foyer que le clic gauche utilise. Pierre de foyer aléatoire choisit une variante possédée au hasard à chaque incantation. Le clic droit tire toujours une variante aléatoire."
L["Which latency to show: home, world, or both side by side."] = "Quelle latence afficher : domicile, monde, ou les deux côte à côte."
L["Which layer the windows and the collapsed icon draw on, relative to other frames on screen."] = "Sur quel calque les fenêtres et l'icône repliée se dessinent, par rapport aux autres cadres à l'écran."
L["Which of the season's crests this block shows."] = "Quel écu de la saison ce bloc affiche."
L["Which sections the gold tooltip shows."] = "Quelles sections l'infobulle d'or affiche."
L["Which way new bars stack as more enemies start casting."] = "Dans quel sens les nouvelles barres s'empilent à mesure que d'autres ennemis commencent à lancer un sort."
L["Which way spell flyouts (e.g. Wild Mushroom, Tiger's Fury) open from this bar. Automatic opens away from the nearest screen edge."] = "Dans quel sens les menus déroulants de sorts (par ex. Champignon sauvage, Fureur du tigre) s'ouvrent depuis cette barre. Automatique s'ouvre à l'opposé du bord d'écran le plus proche."
L["Which way the rows stack as healers are added."] = "Dans quel sens les lignes s'empilent à mesure que des soigneurs sont ajoutés."
L["Which way the windows extend from the collapsed icon when they open. The close button always lands at that same corner."] = "Dans quel sens les fenêtres s'étendent depuis l'icône repliée quand elles s'ouvrent. Le bouton de fermeture se place toujours dans ce même coin."
L["While dragging a spell or item, this bar appears so you can drop onto it."] = "Pendant que vous faites glisser un sort ou un objet, cette barre apparaît pour que vous puissiez le déposer dessus."
L["While either grouping toggle is on, drop the trailing block of empty slots so the view only shows items. Turn this off to keep the free slots visible for depositing."] = "Tant qu'un des deux interrupteurs de regroupement est actif, retire le bloc final d'emplacements vides pour que la vue n'affiche que des objets. Désactivez ceci pour garder les emplacements libres visibles pour y déposer des objets."
L["While on a glide-capable mount, ground included, where Blizzard shows its vigor HUD. Skyriding (Airborne) additionally requires you to be flying."] = "Sur une monture capable de planer, sol inclus, là où Blizzard affiche son ATH de vigueur. Vol draconique (en vol) nécessite en plus d'être en vol."
L["While resting, in a city or at an inn."] = "En train de vous reposer, en ville ou dans une auberge."
L["While seated in a vehicle."] = "Assis dans un véhicule."
L["While the spellbook or macro panel is open, this bar appears so you can drag abilities onto it."] = "Pendant que le grimoire ou le panneau de macros est ouvert, cette barre apparaît pour que vous puissiez y glisser des capacités."
L["While you are inside a house or plot."] = "Pendant que vous êtes dans une maison ou une parcelle."
L["Whirlwind and Sweeping Strikes Thresholds"] = "Seuils de Coup d'ouragan et Frappes balayantes"
L["Whirlwind and Sweeping Strikes thresholds only support the 'From' direction."] = "Les seuils de Coup d'ouragan et Frappes balayantes ne prennent en charge que la direction « Depuis »."
L["Whisper BNet"] = "Chuchoter (Battle.net)"
L["Widget Bar Size"] = "Taille de la barre de widgets"
L["Widget bar reskin requires a UI reload to apply."] = "L'habillage de la barre de widgets nécessite un rechargement de l'interface pour s'appliquer."
L["Width matched to CDM: Cooldowns. Unmatch in Unlock Mode to edit."] = "Largeur alignée sur CDM : recharges. Désaligner dans le mode Déverrouillage pour modifier."
L["Width matched to Cast Bar. Unmatch in Unlock Mode to edit."] = "Largeur alignée sur la barre d'incantation. Désaligner dans le mode Déverrouillage pour modifier."
L["Width matched to Class Resource. Unmatch in Unlock Mode to edit."] = "Largeur alignée sur la ressource de classe. Désaligner dans le mode Déverrouillage pour modifier."
L["Width matched to GCD Bar. Unmatch in Unlock Mode to edit."] = "Largeur alignée sur la barre de GCD. Désaligner dans le mode Déverrouillage pour modifier."
L["Width matched to Health Bar. Unmatch in Unlock Mode to edit."] = "Largeur alignée sur la barre de vie. Désaligner dans le mode Déverrouillage pour modifier."
L["Width matched to Player Frame. Unmatch in Unlock Mode to edit."] = "Largeur alignée sur le cadre du joueur. Désaligner dans le mode Déverrouillage pour modifier."
L["Width matched to Power Bar. Unmatch in Unlock Mode to edit."] = "Largeur alignée sur la barre de ressource. Désaligner dans le mode Déverrouillage pour modifier."
L["Window & Bar Border Styles"] = "Styles de bordure des fenêtres et barres"
L["Window & Tooltip Skins"] = "Habillages de fenêtre et d'infobulle"
L["Window Skins"] = "Habillages de fenêtre"
L["Window header, bar and timer text"] = "Texte d'en-tête de fenêtre, de barre et de chrono"
L["Window scale, icon zoom and item level settings are shared with the Bags page."] = "Les réglages d'échelle de fenêtre, de zoom d'icône et de niveau d'objet sont partagés avec la page Sacs."
L["Window skins are currently disabled for this profile."] = "Les habillages de fenêtre sont actuellement désactivés pour ce profil."
L["Window skins are now disabled for this profile. A UI reload is required to restore the stock Blizzard windows."] = "Les habillages de fenêtre sont désormais désactivés pour ce profil. Un rechargement de l'interface est requis pour restaurer les fenêtres Blizzard d'origine."
L["Window skins are now enabled for this profile. A UI reload is required to apply them."] = "Les habillages de fenêtre sont désormais activés pour ce profil. Un rechargement de l'interface est requis pour les appliquer."
L["Window skins changed for this profile. A UI reload is needed to apply them."] = "Les habillages de fenêtre ont changé pour ce profil. Un rechargement de l'interface est nécessaire pour les appliquer."
L["With health decimals on, full health renders 100% instead of 100.0% while real decimals like 99.5% stay"] = "Avec les décimales de vie activées, la vie pleine s'affiche 100% au lieu de 100,0%, tandis que les vraies décimales comme 99,5% restent"
L["With the Rectangular shape, player and party arrows no longer draw in the hidden bands above and below the map, and combat transitions no longer leave the map cut off wrong."] = "Avec la forme Rectangulaire, les flèches du joueur et du groupe ne se dessinent plus dans les bandes cachées au-dessus et en dessous de la carte, et les transitions de combat ne laissent plus la carte mal coupée."
L["Works in and out of combat, unlike Auto-Repair. When a group-wide raid buff's column header shows it's missing on someone, the icon blinks and sends the buff's spell link. In a raid, left-click reaches a provider in groups 1-4 and right-click one in groups 5-8; outside a raid, left-click reaches the only provider found. Hovering the icon always shows who each click would whisper, or that everyone already has it."] = "Fonctionne en et hors combat, contrairement à Auto-réparation. Quand l'en-tête de colonne d'une amélioration de raid collective montre qu'elle manque à quelqu'un, l'icône clignote et envoie le lien de sort de l'amélioration. En raid, le clic gauche contacte un fournisseur des groupes 1-4 et le clic droit un des groupes 5-8 ; hors raid, le clic gauche contacte le seul fournisseur trouvé. Survoler l'icône montre toujours à qui chaque clic chuchoterait, ou que tout le monde l'a déjà."
L["World Marker Entries"] = "Entrées de repères du monde"
