L["Wrap Border Around Castbar"] = "Bordure autour de la barre d'incantation"
L["Wraps into a new row (or column for vertical growth) after this many icons; 0 keeps one continuous run."] = "Passe à une nouvelle ligne (ou colonne pour une expansion verticale) après ce nombre d'icônes ; 0 garde une seule série continue."
L["Wraps into a new row (or column for vertical growth) after this many icons; below 2 keeps one continuous run."] = "Passe à une nouvelle ligne (ou colonne pour une expansion verticale) après ce nombre d'icônes ; en dessous de 2, garde une seule série continue."
L["Wrong Pet (Demo Lock)"] = "Mauvais familier (Démo)"
