L["XP Bar Text Size"] = "Taille du texte de la barre d'XP"
L["XP Bar Texture"] = "Texture de la barre d'XP"
L["XP, reputation and favor bar textures"] = "Textures des barres d'XP, de réputation et de faveur"
L["Yell"] = "Hurler"
L["You are displaying NO buffs at all."] = "Vous n'affichez AUCUNE amélioration."
L["You are displaying NO debuffs at all."] = "Vous n'affichez AUCUN affaiblissement."
L["You changed the default value of a setting that has overrides. Overrides keep their own values, so this change will not reach the specs or conditions they cover. To change it for an override, pick that override from the class glyph beside the module search bar and edit it there."] = "Vous avez changé la valeur par défaut d'un réglage qui a des remplacements. Les remplacements conservent leurs propres valeurs, donc ce changement n'atteindra pas les spécialisations ou conditions qu'ils couvrent. Pour le changer pour un remplacement, choisissez ce remplacement depuis le glyphe de classe à côté de la barre de recherche de module et modifiez-le là-bas."
L["You don't have this item in your bags"] = "Vous n'avez pas cet objet dans vos sacs"
L["You have not learned %1$s."] = "Vous n'avez pas appris %1$s."
L["You may only have %1$d windows active"] = "Vous ne pouvez avoir que %1$d fenêtres actives"
L["You're on this spec."] = "Vous êtes sur cette spécialisation."
L["Your Edit Mode layout is a Blizzard preset which cannot be modified by addons. Please switch to a custom Edit Mode layout so EllesmereUI can manage your CDM settings.\n\nOpen Edit Mode to create or select a custom layout."] = "Votre disposition du mode Édition est un préréglage Blizzard qui ne peut pas être modifié par les addons. Veuillez passer à une disposition personnalisée du mode Édition pour qu'EllesmereUI puisse gérer vos réglages du CDM.\n\nOuvrez le mode Édition pour créer ou sélectionner une disposition personnalisée."
L["Your current spec has its own custom Debuff Manager, so conditional Debuff Managers never apply to it."] = "Votre spécialisation actuelle a son propre Gestionnaire d'affaiblissements personnalisé, donc les Gestionnaires d'affaiblissements conditionnels ne s'y appliquent jamais."
L["Your focus target's nameplate never fades with the non-target opacity."] = "La barre d'info de la cible de votre Focalisation ne s'estompe jamais avec l'opacité de non-cible."
L["Your preferred food is out - using a backup you own"] = "Votre nourriture préférée est épuisée - utilisation d'une réserve que vous possédez"
L["Zone Text Color"] = "Couleur du texte de zone"
L["Zone Text Scale"] = "Échelle du texte de zone"
L["\"%1$s\" was saved but cannot be loaded because this spec has an assigned profile."] = "« %1$s » a été enregistré mais ne peut pas être chargé car cette spécialisation a un profil assigné."
L["\"Blizzard Default\" is only available when the Focus frame's source is set to Blizzard Default -- the focus-target then comes from Blizzard's focus frame."] = "« Défaut Blizzard » n'est disponible que lorsque la source du cadre Focalisation est réglée sur Défaut Blizzard - la cible de focalisation provient alors du cadre de focalisation de Blizzard."
L["\"Blizzard Default\" is only available when the Target frame's source is set to Blizzard Default -- the target-of-target then comes from Blizzard's target frame."] = "« Défaut Blizzard » n'est disponible que lorsque la source du cadre Cible est réglée sur Défaut Blizzard - la cible-de-la-cible provient alors du cadre de cible de Blizzard."
L["\nPick a gem from the list to socket it."] = "\nChoisissez une gemme dans la liste pour la sertir."
L["\n|cff66ccffDrag to reorder.\nRight-click to change action.\nMiddle-click to remove.\nDrop an action here to replace it.|r"] = "\n|cff66ccffGlissez pour réordonner.\nClic droit pour changer l'action.\nClic milieu pour retirer.\nDéposez une action ici pour la remplacer.|r"
L["\n|cffff6060Item Upgrade window is not open.|r"] = "\n|cffff6060La fenêtre d'Amélioration d'objet n'est pas ouverte.|r"
