L["|cff00ccffEllesmere:|r Reload required to create custom bars. Type /reload"] = "|cff00ccffEllesmere :|r Rechargement requis pour créer des barres personnalisées. Tapez /reload"
L["|cff00ff00[EllesmereUI]|r All hints reset. /reload to see them again."] = "|cff00ff00[EllesmereUI]|r Toutes les astuces réinitialisées. /reload pour les revoir."
L["|cff00ff00[EllesmereUI]|r UI scale reset. /reload to re-snapshot from your Blizzard scale."] = "|cff00ff00[EllesmereUI]|r Échelle d'interface réinitialisée. /reload pour recapturer depuis votre échelle Blizzard."
L["|cff00ff98EllesmereUI:|r Managers intro reset. The announcement popup fires on your next /reload."] = "|cff00ff98EllesmereUI :|r Introduction des gestionnaires réinitialisée. La fenêtre d'annonce se déclenchera à votre prochain /reload."
L["|cff00ff98EllesmereUI:|r Overrides intro reset. The announcement popup fires on your next /reload; the video guide fires on your next click of the overrides glyph."] = "|cff00ff98EllesmereUI :|r Introduction des remplacements réinitialisée. La fenêtre d'annonce se déclenchera à votre prochain /reload ; le guide en vidéo se déclenchera à votre prochain clic sur le glyphe des remplacements."
L["|cff00ff98EllesmereUI:|r Video guides and tutorial tips reset. Badges are back; one-time popups will fire again."] = "|cff00ff98EllesmereUI :|r Guides en vidéo et astuces de tutoriel réinitialisés. Les badges sont de retour ; les fenêtres à usage unique se déclencheront de nouveau."
L["|cff0cd29fEllesmereUI CDM:|r Cooldown Viewer settings are managed by EllesmereUI. Edit Mode changes are disabled."] = "|cff0cd29fEllesmereUI CDM :|r Les réglages du visualiseur de recharge sont gérés par EllesmereUI. Les changements du mode Édition sont désactivés."
