L["|cffff6060[EllesmereUI]|r Cannot enter Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r Impossible d'entrer dans le mode Déverrouillage pendant le combat."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat. Use /eui to view Patch Notes."] = "|cffff6060[EllesmereUI]|r Impossible d'ouvrir les options pendant le combat. Utilisez /eui pour voir les Notes de patch."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat."] = "|cffff6060[EllesmereUI]|r Impossible d'ouvrir les options pendant le combat."
L["|cffff6060[EllesmereUI]|r Cannot toggle Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r Impossible de basculer le mode Déverrouillage pendant le combat."
